// HELPER: Aliquota IVA in base al lead
// Legge 104 / disabilità 100% → 4% | Standard → 22%
// ─────────────────────────────────────────────────────────────────────────────
function getIvaRate(lead: any): number {
  return lead?.iva_agevolata ? 0.04 : 0.22
}
function getIvaLabel(lead: any): string {
  return lead?.iva_agevolata ? '4%' : '22%'
}
function getIvaNote(lead: any): string {
  return lead?.iva_agevolata
    ? ' (IVA agevolata 4% — Legge 104, disabilità 100%)'
    : ' (IVA 22%)'
}

// Genera proforma da contratto firmato
async function generaProformaDaContratto(contractId: string, db: any) {
  try {
    // Recupera contratto e lead
    // ⭐ CALCOLA dati intestatario in base a intestatarioContratto
    const contract = await db.prepare(`
      SELECT c.*, 
        l.nomeRichiedente, l.cognomeRichiedente, l.email, l.telefono,
        l.nomeAssistito, l.cognomeAssistito,
        l.intestatarioContratto,
        l.cfIntestatario, l.indirizzoIntestatario
      FROM contracts c
      LEFT JOIN leads l ON c.leadId = l.id
      WHERE c.id = ? AND c.status = 'SIGNED'
    `).bind(contractId).first()
    
    if (!contract) {
      return { success: false, error: 'Contratto firmato non trovato' }
    }
    
    const proformaId = `PROFORMA_${Date.now()}_${Math.random().toString(36).substring(7)}`
    const numeroProforma = `PF-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`
    const dataScadenza = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000) // ✅ 3 giorni (non 15!)
    
    // ⭐ CALCOLA dati cliente in base a intestatarioContratto
    const intestatario = contract.intestatarioContratto || 'richiedente'
    
    let nomeCliente: string
    let cognomeCliente: string
    
    if (intestatario === 'assistito') {
      nomeCliente = contract.nomeAssistito || contract.nomeRichiedente
      cognomeCliente = contract.cognomeAssistito || contract.cognomeRichiedente
    } else {
      nomeCliente = contract.nomeRichiedente
      cognomeCliente = contract.cognomeRichiedente
    }
    
    const emailCliente = contract.email
    const telefonoCliente = contract.telefono
    
    // Crea proforma
    await db.prepare(`
      INSERT INTO proforma (
        id, contract_id, leadId, numero_proforma, data_emissione, data_scadenza,
        cliente_nome, cliente_cognome, cliente_email, cliente_telefono,
        tipo_servizio, prezzo_mensile, durata_mesi, prezzo_totale, status
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      proformaId, contractId, contract.leadId, numeroProforma,
      new Date().toISOString(), dataScadenza.toISOString(),
      nomeCliente, cognomeCliente, 
      emailCliente, telefonoCliente,
      contract.tipo_contratto, contract.prezzo_mensile, contract.durata_mesi,
      contract.prezzo_totale, 'DRAFT'
    ).run()
    
    return { 
      success: true, 
      proformaId,
      numeroProforma,
      message: 'Proforma generata automaticamente'
    }
    
  } catch (error) {
    return { success: false, error: error.message }
  }
}

