// 🔄 ENDPOINT: Aggiorna template dal file HTML (con templateId in body)
app.post('/api/admin/update-template', async (c) => {
  try {
    const { templateId, htmlContent } = await c.req.json()
    
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    if (!templateId || !htmlContent) {
      return c.json({ success: false, error: 'templateId e htmlContent richiesti' }, 400)
    }
    
    console.log(`📝 Aggiornamento template: ${templateId} (${htmlContent.length} chars)`)
    
    // Aggiorna il template nel database
    const result = await c.env.DB.prepare(`
      UPDATE document_templates 
      SET html_content = ?,
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `).bind(htmlContent, templateId).run()
    
    console.log(`✅ Template ${templateId} aggiornato (changes: ${result.meta.changes})`)
    
    return c.json({
      success: true,
      templateId,
      updated: true,
      changes: result.meta.changes
    })
    
  } catch (error) {
    console.error('❌ Errore aggiornamento template:', error)
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// 🔧 ENDPOINT: Correggi fonte da HUBSPOT a IRBEMA per tutti i lead da HubSpot
app.post('/api/admin/fix-fonte-irbema', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    console.log('🔧 Correzione fonte: HUBSPOT → Form eCura')
    
    // Aggiorna tutti i lead con fonte HUBSPOT o vuota (solo per LEAD-IRBEMA-xxxxx)
    const result = await c.env.DB.prepare(`
      UPDATE leads 
      SET fonte = 'Form eCura'
      WHERE (fonte = 'HUBSPOT' OR fonte LIKE 'HubSpot%' OR fonte IS NULL OR fonte = '' OR fonte = 'IRBEMA')
        AND id LIKE 'LEAD-IRBEMA-%'
    `).run()
    
    console.log(`✅ Fonte aggiornata per ${result.meta.changes} lead`)
    
    return c.json({
      success: true,
      message: 'Fonte aggiornata da HUBSPOT a IRBEMA',
      leadsUpdated: result.meta.changes
    })
    
  } catch (error) {
    console.error('❌ Errore correzione fonte:', error)
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

/**
 * POST /api/contracts/fix-email-sent
 * Correzione one-shot: imposta email_sent=1 su tutti i contratti rinnovo
 * che hanno status SENT/SIGNED e email_sent=0, così il btn3 ✍️ si attiva.
 * Protetto dalla sessione utente normale (non richiede ADMIN_SECRET_TOKEN).
 */
app.post('/api/contracts/fix-email-sent', async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'Database non configurato' }, 500)

    const result = await c.env.DB.prepare(`
      UPDATE contracts
      SET email_sent = 1, updated_at = ?
      WHERE is_rinnovo = 1
        AND email_sent = 0
        AND status IN ('SENT', 'SIGNED')
    `).bind(new Date().toISOString()).run()

    console.log(`✅ fix-email-sent: email_sent=1 impostato su ${result.meta.changes} contratti rinnovo`)
    return c.json({
      success: true,
      updated: result.meta.changes,
      message: `email_sent=1 impostato su ${result.meta.changes} contratti rinnovo`
    })
  } catch (error) {
    console.error('❌ Errore fix-email-sent:', error)
    return c.json({ success: false, error: error instanceof Error ? error.message : String(error) }, 500)
  }
})

// 🔧 ENDPOINT: Aggiorna fonte per lead di TEST → 'Form eCura x Test'
// Cattura:
//   1. Lead con nome o cognome che è esattamente "TEST" (es. "TEST TEST", "Nur TEST")
//   2. Lead con nome+cognome entrambi "TEST" (es. "test test")
//   3. Lead specifici noti per nome (Rosaria Ressa, Roberto Poggi, Stefania Rocca)
//   4. Lead specifici per ID (LEAD-IRBEMA-00107)
//   5. Email contenente "test@" o "@test." o "@esempio." o "@example."
// ⚠️  ESCLUSO: lead con "testa/testi/testo" nelle note (es. "mal di testa") → gestiti da restore-real-leads
app.post('/api/admin/fix-test-leads', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    console.log('🔧 Aggiornamento fonte lead di TEST → Form eCura x Test')

    // Prima: mostra quali lead verranno aggiornati (per log)
    const preview = await c.env.DB.prepare(`
      SELECT id, nomeRichiedente, cognomeRichiedente, email, fonte
      FROM leads
      WHERE fonte != 'Form eCura x Test'
        AND (
          -- nome o cognome esattamente "TEST" (case-insensitive): "TEST TEST", "Nur TEST", "test test"
          UPPER(TRIM(nomeRichiedente)) = 'TEST'
          OR UPPER(TRIM(cognomeRichiedente)) = 'TEST'
          -- entrambi nome+cognome contengono solo "test"
          OR (UPPER(TRIM(nomeRichiedente)) = 'TEST' AND UPPER(TRIM(cognomeRichiedente)) = 'TEST')
          -- lead specifici noti per nome
          OR (nomeRichiedente = 'Rosaria' AND cognomeRichiedente = 'Ressa')
          OR (nomeRichiedente = 'Roberto' AND cognomeRichiedente = 'Poggi')
          OR (nomeRichiedente = 'Stefania' AND cognomeRichiedente = 'Rocca')
          -- lead specifici per ID
          OR id = 'LEAD-IRBEMA-00107'
          -- email chiaramente di test
          OR LOWER(email) LIKE 'test@%'
          OR LOWER(email) LIKE '%@test.%'
          OR LOWER(email) LIKE '%@esempio.%'
          OR LOWER(email) LIKE '%@example.%'
        )
    `).all()

    const previewLeads = preview.results || []
    console.log(`🔍 Lead di test trovati: ${previewLeads.length}`, previewLeads.map((l: any) => `${l.id} ${l.nomeRichiedente} ${l.cognomeRichiedente} (${l.email}) [${l.fonte}]`))

    // Poi: aggiorna
    const result = await c.env.DB.prepare(`
      UPDATE leads 
      SET fonte = 'Form eCura x Test'
      WHERE fonte != 'Form eCura x Test'
        AND (
          UPPER(TRIM(nomeRichiedente)) = 'TEST'
          OR UPPER(TRIM(cognomeRichiedente)) = 'TEST'
          OR (UPPER(TRIM(nomeRichiedente)) = 'TEST' AND UPPER(TRIM(cognomeRichiedente)) = 'TEST')
          OR (nomeRichiedente = 'Rosaria' AND cognomeRichiedente = 'Ressa')
          OR (nomeRichiedente = 'Roberto' AND cognomeRichiedente = 'Poggi')
          OR (nomeRichiedente = 'Stefania' AND cognomeRichiedente = 'Rocca')
          OR id = 'LEAD-IRBEMA-00107'
          OR LOWER(email) LIKE 'test@%'
          OR LOWER(email) LIKE '%@test.%'
          OR LOWER(email) LIKE '%@esempio.%'
          OR LOWER(email) LIKE '%@example.%'
        )
    `).run()
    
    console.log(`✅ Fonte aggiornata per ${result.meta.changes} lead di test`)
    
    return c.json({
      success: true,
      message: `Lead di TEST aggiornati a fonte "Form eCura x Test"`,
      leadsUpdated: result.meta.changes,
      leads: previewLeads.map((l: any) => ({
        id: l.id,
        nome: `${l.nomeRichiedente} ${l.cognomeRichiedente}`,
        email: l.email,
        fonteOld: l.fonte
      }))
    })
    
  } catch (error) {
    console.error('❌ Errore aggiornamento lead test:', error)
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

