// 🔄 Helper function: Auto-aggiorna stato lead a "non_risponde"
async function checkAndUpdateNonRispondeStatus(db: any, leadId: string): Promise<void> {
  try {
    console.log(`🔍 Controllo stato "non risponde" per lead ${leadId}`)
    
    // 1. Controlla il campo note/notes del lead (prova entrambi i nomi)
    const lead = await db.prepare('SELECT note, notes FROM leads WHERE id = ?').bind(leadId).first()
    const note = (lead?.note || lead?.notes || '').toLowerCase()
    
    console.log(`🔍 Note del lead ${leadId}: "${note.substring(0, 100)}"`)
    
    if (note.includes('non risponde')) {
      console.log(`📵 Trovato "non risponde" nelle note del lead ${leadId}`)
      await db.prepare('UPDATE leads SET stato = ?, updated_at = ? WHERE id = ?')
        .bind('non_risponde', new Date().toISOString(), leadId).run()
      console.log(`✅ Stato aggiornato a "non_risponde" per lead ${leadId}`)
      return
    }
    
    // 2. Controlla tutte le interazioni del lead
    const interactions = await db.prepare(
      'SELECT nota, azione FROM lead_interactions WHERE lead_id = ? ORDER BY data DESC'
    ).bind(leadId).all()
    
    console.log(`🔍 Trovate ${interactions.results?.length || 0} interazioni per lead ${leadId}`)
    
    for (const interaction of interactions.results || []) {
      const notaInt = (interaction.nota || '').toLowerCase()
      const azioneInt = (interaction.azione || '').toLowerCase()
      
      console.log(`🔍 Interazione: nota="${notaInt.substring(0, 50)}", azione="${azioneInt.substring(0, 50)}"`)
      
      if (notaInt.includes('non risponde') || azioneInt.includes('non risponde')) {
        console.log(`📵 Trovato "non risponde" nelle interazioni del lead ${leadId}`)
        await db.prepare('UPDATE leads SET stato = ?, updated_at = ? WHERE id = ?')
          .bind('non_risponde', new Date().toISOString(), leadId).run()
        console.log(`✅ Stato aggiornato a "non_risponde" per lead ${leadId}`)
        return
      }
    }
    
    console.log(`ℹ️ Nessun "non risponde" trovato per lead ${leadId}`)
  } catch (error) {
    console.error(`❌ Errore controllo stato "non risponde" per lead ${leadId}:`, error)
  }
}

// API endpoint per recuperare i lead (admin)
app.get('/api/leads', async (c) => {
  try {
    if (!c.env.DB) {
      return c.json({
        success: false,
        error: 'Database D1 non configurato - modalità development'
      }, 400)
    }
    
    const limit = c.req.query('limit') || '100'
    
    // Conta TUTTI i lead (senza limit)
    const countResult = await c.env.DB.prepare(`SELECT COUNT(*) as total FROM leads`).first()
    const totalLeads = countResult?.total || 0
    
    // Recupera lead con limit
    // Usa COALESCE(created_at, timestamp) per non escludere lead con timestamp=NULL
    const leads = await c.env.DB.prepare(`SELECT * FROM leads ORDER BY COALESCE(created_at, timestamp) DESC LIMIT ?`).bind(parseInt(limit)).all()
    
    console.log('📊 Leads recuperati:', leads.results?.length || 0, 'di', totalLeads, 'totali')
    
    return c.json({
      success: true,
      total: totalLeads, // ✅ Count totale (senza limit)
      count: leads.results?.length || 0, // Count dei lead restituiti
      leads: leads.results || []
    })
  } catch (error) {
    console.error('❌ Errore recupero leads:', error)
    return c.json({ success: false, error: 'Errore recupero dati' }, 500)
  }
})

// GET /api/leads/filters - Ottieni valori distinti per filtri leads
app.get('/api/leads/filters', async (c) => {
  try {
    if (!c.env.DB) {
      return c.json({
        success: false,
        error: 'Database D1 non configurato'
      }, 400)
    }

    console.log('🔍 Recupero valori distinti per filtri leads...')

    const filters: any = {
      fonti: [],
      sorgenti: [],
      dettagliFonte: [],
      servizi: [],
      piani: []
    }

    // Recupera valori distinti di fonte
    try {
      const fonti = await c.env.DB.prepare(`
        SELECT DISTINCT fonte 
        FROM leads 
        WHERE fonte IS NOT NULL AND fonte != ''
        ORDER BY fonte
      `).all()
      filters.fonti = fonti.results?.map((r: any) => r.fonte) || []
    } catch (error) {
      console.error('⚠️ Errore recupero fonti:', error)
    }

    // Recupera valori distinti di canale_acquisizione (META/GOOGLE/DIRETTO/ALTRO)
    // Usato dal filtro "Sorgente" nella leads dashboard
    try {
      const canali = await c.env.DB.prepare(`
        SELECT DISTINCT canale_acquisizione
        FROM leads
        WHERE canale_acquisizione IS NOT NULL AND canale_acquisizione != ''
        ORDER BY canale_acquisizione
      `).all()
      // Ordine fisso per la UI: META → GOOGLE → DIRETTO → ALTRO
      const ordine = ['META', 'GOOGLE', 'DIRETTO', 'ALTRO']
      const canaliRaw = canali.results?.map((r: any) => r.canale_acquisizione) || []
      filters.sorgenti = ordine.filter(c => canaliRaw.includes(c))
        .concat(canaliRaw.filter((c: string) => !ordine.includes(c)))
    } catch (error) {
      console.warn('⚠️ Colonna canale_acquisizione non trovata, fallback su hs_object_source:', error)
      // Fallback legacy: hs_object_source
      try {
        const sorgenti = await c.env.DB.prepare(`
          SELECT DISTINCT hs_object_source FROM leads
          WHERE hs_object_source IS NOT NULL AND hs_object_source != ''
          ORDER BY hs_object_source
        `).all()
        filters.sorgenti = sorgenti.results?.map((r: any) => r.hs_object_source) || []
      } catch { filters.sorgenti = [] }
    }

    // Recupera valori distinti di dettaglio_fonte (con fallback se colonna non esiste)
    try {
      const dettagliFonte = await c.env.DB.prepare(`
        SELECT DISTINCT dettaglio_fonte 
        FROM leads 
        WHERE dettaglio_fonte IS NOT NULL AND dettaglio_fonte != ''
        ORDER BY dettaglio_fonte
      `).all()
      filters.dettagliFonte = dettagliFonte.results?.map((r: any) => r.dettaglio_fonte) || []
    } catch (error) {
      console.warn('⚠️ Colonna dettaglio_fonte non trovata (eseguire POST /api/db/migrate):', error)
      filters.dettagliFonte = []
    }

    // Recupera valori distinti di servizio
    try {
      const servizi = await c.env.DB.prepare(`
        SELECT DISTINCT servizio 
        FROM leads 
        WHERE servizio IS NOT NULL AND servizio != ''
        ORDER BY servizio
      `).all()
      filters.servizi = servizi.results?.map((r: any) => r.servizio) || []
    } catch (error) {
      console.error('⚠️ Errore recupero servizi:', error)
    }

    // Recupera valori distinti di pacchetto (piano)
    try {
      const piani = await c.env.DB.prepare(`
        SELECT DISTINCT pacchetto 
        FROM leads 
        WHERE pacchetto IS NOT NULL AND pacchetto != ''
        ORDER BY pacchetto
      `).all()
      filters.piani = piani.results?.map((r: any) => r.pacchetto) || []
    } catch (error) {
      console.error('⚠️ Errore recupero piani:', error)
    }

    return c.json({
      success: true,
      filters
    })
  } catch (error) {
    console.error('❌ Errore recupero filtri leads:', error)
    return c.json({ 
      success: false, 
      error: 'Errore recupero filtri',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// GET /api/leads/channel-stats — Statistiche canali Form eCura (Meta / Google / Altro / Diretto)
//
// LOGICA CORRETTA (due query separate):
// 1. totalEcura  = COUNT leads con fonte = 'Form eCura' (campo affidabile per TUTTI i lead storici)
// 2. META/GOOGLE/ALTRO = COUNT da hs_object_source_detail_1 per i lead che hanno il suffisso canale
//    (presenti solo nei lead importati dopo il 12-13/05/2026 con CONTAINS_TOKEN)
// 3. diretto = totalEcura - meta - google - altro (lead vecchi senza suffisso canale)
//
// Nota: i lead storici hanno hs_object_source_detail_1 = 'Form eCura' (vecchio valore esatto)
// oppure NULL; solo i nuovi hanno 'Form eCura_ META' / 'Form eCura_ GOOGLE' / 'Form eCura_ ALTRO'
app.get('/api/leads/channel-stats', async (c) => {
  try {
    if (!c.env.DB) {
      return c.json({ success: false, error: 'Database D1 non configurato' }, 400)
    }

    // =====================================================================
    // FONTE DI VERITÀ UNICA: canale_acquisizione
    // Tutti i contatori (box e filtro tabella) usano lo stesso campo.
    // canale_acquisizione = 'META' | 'GOOGLE' | 'DIRETTO' | 'ALTRO' | NULL
    // Lead eCura = fonte = 'Form eCura' (esclude test, IRBEMA, ecc.)
    // =====================================================================

    // Query 1 — totale lead eCura (fonte = 'Form eCura', esclude test)
    // Usa COUNT(*) — stesso criterio del filtro tabella (conta record, non email univoche)
    let totalEcura = 0
    try {
      const r = await c.env.DB.prepare(`
        SELECT COUNT(*) as count
        FROM leads
        WHERE fonte = 'Form eCura'
      `).first() as any
      totalEcura = Number(r?.count) || 0
    } catch (err) {
      console.warn('⚠️ channel-stats: errore query totalEcura', err)
    }

    // Query 2 — breakdown per canale usando canale_acquisizione (fonte di verità unica)
    // Stessa logica usata dal filtro tabella → numeri sempre coerenti
    let meta = 0
    let google = 0
    let diretto = 0
    let altro = 0
    let breakdown: any[] = []
    try {
      const result = await c.env.DB.prepare(`
        SELECT canale_acquisizione, COUNT(*) as count
        FROM leads
        WHERE fonte = 'Form eCura'
          AND canale_acquisizione IS NOT NULL
          AND canale_acquisizione != ''
        GROUP BY canale_acquisizione
        ORDER BY count DESC
      `).all()
      const rows = result.results || []

      rows.forEach((row: any) => {
        // Supporta sia il formato normalizzato ('META') sia quello vecchio ('Form eCura_ META')
        // presenti in DB storici (TEST) popolati con versioni precedenti del codice.
        const val: string = (row.canale_acquisizione || '').toUpperCase()
        const cnt = Number(row.count) || 0
        if (val === 'META'      || val.includes('META'))    meta    += cnt
        else if (val === 'GOOGLE'  || val.includes('GOOGLE'))  google  += cnt
        else if (val === 'DIRETTO' || val.includes('DIRETTO')) diretto += cnt
        else if (val === 'ALTRO'   || val.includes('ALTRO'))   altro   += cnt
        breakdown.push({ label: row.canale_acquisizione, count: cnt })
      })
    } catch (err) {
      console.warn('⚠️ channel-stats: errore query canale_acquisizione', err)
    }

    // nonTracciato = lead eCura senza canale_acquisizione
    const nonTracciato = Math.max(0, totalEcura - meta - google - diretto - altro)

    // ─── Query 3: statistiche sconto per canale ────────────────────────────
    // Per ogni canale_acquisizione: conteggio lead con sconto, valore totale scontato, % media
    let discountByCanale: Record<string, { count: number; leads: number; risparmio: number; pct_media: number }> = {}
    let discountGlobal = { leads: 0, risparmio: 0, pct_media: 0 }
    let discountByCode: any[] = []
    try {
      // Per canale
      const dcByCanale = await c.env.DB.prepare(`
        SELECT
          COALESCE(l.canale_acquisizione, '__NON_TRACCIATO__') AS canale,
          COUNT(l.id)                                            AS leads_totali,
          SUM(CASE WHEN l.codice_sconto IS NOT NULL AND l.codice_sconto != '' THEN 1 ELSE 0 END) AS leads_scontati,
          ROUND(SUM(COALESCE(l.prezzo_anno, 0) - COALESCE(l.prezzo_scontato, COALESCE(l.prezzo_anno, 0))), 2) AS risparmio_totale,
          ROUND(AVG(CASE WHEN l.codice_sconto IS NOT NULL AND l.codice_sconto != '' THEN l.sconto_percentuale ELSE NULL END), 1) AS pct_media
        FROM leads l
        WHERE l.fonte = 'Form eCura'
        GROUP BY COALESCE(l.canale_acquisizione, '__NON_TRACCIATO__')
      `).all()

      for (const row of (dcByCanale.results || []) as any[]) {
        discountByCanale[row.canale] = {
          count:      Number(row.leads_scontati)  || 0,
          leads:      Number(row.leads_totali)     || 0,
          risparmio:  Number(row.risparmio_totale) || 0,
          pct_media:  Number(row.pct_media)        || 0
        }
      }

      // Globale (tutti i lead, non solo eCura Form)
      const dcGlobal = await c.env.DB.prepare(`
        SELECT
          SUM(CASE WHEN codice_sconto IS NOT NULL AND codice_sconto != '' THEN 1 ELSE 0 END) AS leads_scontati,
          ROUND(SUM(COALESCE(prezzo_anno, 0) - COALESCE(prezzo_scontato, COALESCE(prezzo_anno, 0))), 2) AS risparmio_totale,
          ROUND(AVG(CASE WHEN codice_sconto IS NOT NULL AND codice_sconto != '' THEN sconto_percentuale ELSE NULL END), 1) AS pct_media
        FROM leads
      `).first() as any
      discountGlobal = {
        leads:     Number(dcGlobal?.leads_scontati)  || 0,
        risparmio: Number(dcGlobal?.risparmio_totale) || 0,
        pct_media: Number(dcGlobal?.pct_media)        || 0
      }

      // Per codice sconto — parte da discount_codes (tutti i codici attivi)
      // così appaiono anche i codici con 0 utilizzi
      const dcByCod = await c.env.DB.prepare(`
        SELECT
          dc.codice                                                           AS codice,
          dc.descrizione                                                      AS descrizione,
          dc.tipo                                                             AS tipo,
          dc.valore                                                           AS valore_nominale,
          dc.sorgente                                                         AS sorgente_codice,
          dc.attivo                                                           AS attivo,
          COUNT(l.id)                                                         AS leads,
          ROUND(
            COALESCE(SUM(COALESCE(l.prezzo_anno,0) - COALESCE(l.prezzo_scontato, COALESCE(l.prezzo_anno,0))), 0)
          , 2)                                                                AS risparmio,
          ROUND(COALESCE(AVG(CASE WHEN l.codice_sconto IS NOT NULL THEN l.sconto_percentuale ELSE NULL END), 0), 1) AS pct_media
        FROM discount_codes dc
        LEFT JOIN leads l ON l.codice_sconto = dc.codice
        GROUP BY dc.codice, dc.descrizione, dc.tipo, dc.valore, dc.sorgente, dc.attivo
        ORDER BY leads DESC, dc.codice ASC
      `).all()
      discountByCode = (dcByCod.results || []) as any[]
    } catch (dcErr) {
      console.warn('⚠️ channel-stats: errore query discount stats', dcErr)
    }

    return c.json({
      success: true,
      totalEcura,
      meta,
      google,
      diretto,
      altro,
      nonTracciato,
      breakdown,
      // Statistiche sconto
      discountByCanale,
      discountGlobal,
      discountByCode
    })
  } catch (error) {
    console.error('❌ Errore channel-stats:', error)
    return c.json({ success: false, error: 'Errore recupero statistiche canale' }, 500)
  }
})

// GET /api/leads/channel-debug — Interroga HubSpot per vedere i valori ESATTI di
// hs_analytics_source per i lead "ALTRO" e "NON TRACCIATI" nel nostro DB
app.get('/api/leads/channel-debug', async (c) => {
  try {
    if (!c.env.DB) return c.json({ error: 'DB non configurato' }, 400)
    if (!c.env.HUBSPOT_ACCESS_TOKEN) return c.json({ error: 'HUBSPOT_ACCESS_TOKEN mancante' }, 400)

    const db = c.env.DB as D1Database
    const accessToken = c.env.HUBSPOT_ACCESS_TOKEN

    // 1. Riepilogo DB (valori distinti hs_object_source_detail_1)
    const detailRows = await db.prepare(`
      SELECT
        COALESCE(NULLIF(hs_object_source_detail_1,''), '(NULL/vuoto)') as valore,
        COUNT(*) as count
      FROM leads
      WHERE fonte = 'Form eCura'
         OR hs_object_source_detail_1 LIKE 'Form eCura%'
      GROUP BY hs_object_source_detail_1
      ORDER BY count DESC
    `).all()

    // 2. Prendi gli external_source_id (HubSpot ID) dei lead ALTRO e NON TRACCIATI
    const targetRows = await db.prepare(`
      SELECT external_source_id, email, nomeRichiedente, hs_object_source_detail_1
      FROM leads
      WHERE (fonte = 'Form eCura' OR hs_object_source_detail_1 LIKE 'Form eCura%')
        AND (
          hs_object_source_detail_1 LIKE '%ALTRO%'
          OR hs_object_source_detail_1 IS NULL
          OR hs_object_source_detail_1 = ''
          OR hs_object_source_detail_1 = 'Form eCura'
        )
        AND external_source_id IS NOT NULL
        AND external_source_id != ''
      LIMIT 60
    `).all()

    const targets = (targetRows.results || []) as any[]
    console.log(`🔍 [CHANNEL-DEBUG] Trovati ${targets.length} lead da interrogare su HubSpot`)

    // 3. Interroga HubSpot per ogni lead (batch di 100 via /search con IN filter)
    const hubspotIds = targets.map((r: any) => r.external_source_id).filter(Boolean)
    let hubspotData: any[] = []

    if (hubspotIds.length > 0) {
      // Usa batch search HubSpot con filtro id IN [...]
      // HubSpot non supporta IN direttamente, usiamo filterGroups multipli (OR logic)
      // Max 3 filterGroups → usiamo /crm/v3/objects/contacts con idProperty
      const batchBody = {
        inputs: hubspotIds.slice(0, 100).map((id: string) => ({ id }))
      }

      const batchRes = await fetch('https://api.hubapi.com/crm/v3/objects/contacts/batch/read', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${accessToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          ...batchBody,
          properties: [
            'email',
            'hs_object_source_detail_1',
            'hs_analytics_source',
            'hs_analytics_source_data_1',
            'hs_analytics_source_data_2',
            'hs_latest_source',
            'hs_latest_source_data_1'
          ]
        })
      })

      if (batchRes.ok) {
        const batchData = await batchRes.json() as any
        hubspotData = (batchData.results || []).map((c: any) => ({
          id: c.id,
          email: c.properties?.email,
          hs_object_source_detail_1: c.properties?.hs_object_source_detail_1,
          hs_analytics_source: c.properties?.hs_analytics_source,
          hs_analytics_source_data_1: c.properties?.hs_analytics_source_data_1,
          hs_analytics_source_data_2: c.properties?.hs_analytics_source_data_2,
          hs_latest_source: c.properties?.hs_latest_source,
          hs_latest_source_data_1: c.properties?.hs_latest_source_data_1
        }))
      } else {
        const errText = await batchRes.text()
        console.error('❌ [CHANNEL-DEBUG] HubSpot batch error:', errText)
      }
    }

    // 4. Aggrega i valori analytics per capire la distribuzione
    const analyticsSourceCount: Record<string, number> = {}
    const analyticsSourceData1Count: Record<string, number> = {}
    hubspotData.forEach((h: any) => {
      const src = h.hs_analytics_source || '(vuoto/null)'
      const src1 = h.hs_analytics_source_data_1 || '(vuoto)'
      analyticsSourceCount[src] = (analyticsSourceCount[src] || 0) + 1
      analyticsSourceData1Count[`${src} → ${src1}`] = (analyticsSourceData1Count[`${src} → ${src1}`] || 0) + 1
    })

    return c.json({
      success: true,
      riepilogo_db: detailRows.results,
      lead_analizzati: targets.length,
      // Distribuzione aggregata hs_analytics_source per questi lead
      analytics_source_distribuzione: Object.entries(analyticsSourceCount)
        .sort((a, b) => b[1] - a[1])
        .map(([source, count]) => ({ source, count })),
      analytics_source_dettaglio: Object.entries(analyticsSourceData1Count)
        .sort((a, b) => b[1] - a[1])
        .map(([source_data1, count]) => ({ source_data1, count })),
      // Dettaglio per ogni singolo lead
      dettaglio_lead: hubspotData
    })
  } catch (err) {
    return c.json({ error: (err as Error).message }, 500)
  }
})

// POST /api/leads/sync-ecura-channels — Re-sincronizza hs_object_source_detail_1
// per i lead degli ultimi N giorni (default 45) tramite auto-import HubSpot.
// Serve a popolare il campo canale (META/GOOGLE/ALTRO) sui lead già presenti nel DB
// che non ce l'hanno ancora (importati prima del 12-13/05/2026 o tramite tasto IRBEMA).
app.post('/api/leads/sync-ecura-channels', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    if (!c.env?.HUBSPOT_ACCESS_TOKEN) {
      return c.json({ success: false, error: 'HUBSPOT_ACCESS_TOKEN non configurato' }, 500)
    }

    const body = await c.req.json().catch(() => ({}))

    // Calcola giorni dall'inizio campagna HubSpot eCura (30 gennaio 2026) ad oggi
    // così copriamo TUTTI i 235 lead indipendentemente da quando sono stati creati
    const campaignStart = new Date('2026-01-30T00:00:00Z')
    const daysSinceCampaign = Math.ceil((Date.now() - campaignStart.getTime()) / (1000 * 60 * 60 * 24)) + 1
    const days = Math.min(Number(body.days) || daysSinceCampaign, 365) // default = dall'inizio campagna

    console.log(`🔄 [SYNC-CHANNELS] Re-sync canali eCura ultimi ${days} giorni (dal ${campaignStart.toLocaleDateString('it-IT')})...`)

    const { executeAutoImport } = await import('./modules/hubspot-auto-import')
    const baseUrl = c.env?.PUBLIC_URL || 'https://telemedcare-v12.pages.dev'

    const result = await executeAutoImport(c.env.DB, c.env, baseUrl, {
      enabled: true,
      startHour: 0,
      days,
      onlyEcura: true,
      dryRun: false
    })

    console.log(`✅ [SYNC-CHANNELS] Completato: ${result.imported} importati, ${result.updated} aggiornati`)

    return c.json({
      success: result.success,
      message: result.message,
      days,
      from: result.timeRange?.from ?? campaignStart.toISOString(),
      imported: result.imported,
      updated: result.updated,
      skipped: result.skipped,
      hubspotContacts: result.performance?.hubspotContacts ?? 0,
      errors: result.errorDetails ?? []
    })
  } catch (error) {
    console.error('❌ sync-ecura-channels error:', error)
    return c.json({ success: false, error: (error as Error).message }, 500)
  }
})


// POST /api/admin/normalize-canale
// Normalizza i valori vecchi di canale_acquisizione ('Form eCura_ META' → 'META' ecc.)
// nei DB storici (in particolare TEST) popolati prima del refactoring del 21/05/2026.
// Idempotente: si può rieseguire senza danni.
// Auth: ADMIN_SECRET_TOKEN (via middleware /api/admin/*)
app.post('/api/admin/normalize-canale', async (c) => {
  try {
    const db = c.env.DB
    if (!db) return c.json({ success: false, error: 'DB non configurato' }, 500)

    const mappings = [
      { from: 'Form eCura_ META',    to: 'META'    },
      { from: 'Form eCura_ GOOGLE',  to: 'GOOGLE'  },
      { from: 'Form eCura_ DIRETTO', to: 'DIRETTO' },
      { from: 'Form eCura_ ALTRO',   to: 'ALTRO'   },
      // Varianti con spazio diverso o senza spazio
      { from: 'Form eCura_META',    to: 'META'    },
      { from: 'Form eCura_GOOGLE',  to: 'GOOGLE'  },
      { from: 'Form eCura_DIRETTO', to: 'DIRETTO' },
      { from: 'Form eCura_ALTRO',   to: 'ALTRO'   },
    ]

    let totalUpdated = 0
    const details: string[] = []

    for (const { from, to } of mappings) {
      const result = await db.prepare(`
        UPDATE leads
        SET canale_acquisizione = ?, updated_at = ?
        WHERE canale_acquisizione = ?
      `).bind(to, new Date().toISOString(), from).run()
      const count = (result as any).meta?.changes ?? 0
      if (count > 0) {
        details.push(`'${from}' → '${to}': ${count} lead`)
        totalUpdated += count
      }
    }

    console.log(`✅ [NORMALIZE-CANALE] ${totalUpdated} lead normalizzati:`, details.join(', '))
    return c.json({
      success: true,
      totalUpdated,
      details,
      message: totalUpdated > 0
        ? `Normalizzati ${totalUpdated} valori canale_acquisizione`
        : 'Nessun valore da normalizzare — DB già aggiornato'
    })
  } catch (error) {
    console.error('❌ normalize-canale error:', error)
    return c.json({ success: false, error: (error as Error).message }, 500)
  }
})

// 🚀 BULK IMPORT ENDPOINT - Import 126 lead da Excel
app.post('/api/leads/import-bulk', async (c) => {
  try {
    if (!c.env.DB) {
      return c.json({
        success: false,
        error: 'Database D1 non configurato'
      }, 400)
    }

    const body = await c.req.json()
    const { leads } = body

    if (!leads || !Array.isArray(leads)) {
      return c.json({
        success: false,
        error: 'Payload invalido: array "leads" richiesto'
      }, 400)
    }

    console.log(`🚀 Import bulk: ${leads.length} lead...`)

    let importedCount = 0
    let errorCount = 0
    const errors: any[] = []

    // Import in batch da 20
    for (let i = 0; i < leads.length; i += 20) {
      const batch = leads.slice(i, i + 20)
      
      for (const lead of batch) {
        try {
          const {
            id,
            nomeRichiedente,
            cognomeRichiedente,
            email,
            telefono,
            fonte,
            tipoServizio,
            status,
            note,
            created_at
          } = lead

          await c.env.DB.prepare(`
            INSERT INTO leads (
              id, nomeRichiedente, cognomeRichiedente, email, telefono,
              fonte, tipoServizio, status, note,
              created_at, updated_at, timestamp
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          `).bind(
            id,
            nomeRichiedente || '',
            cognomeRichiedente || '',
            email || '',
            telefono || '',
            fonte || 'EXCEL_IMPORT',
            tipoServizio || 'eCura PRO',
            status || 'NEW',
            note || '',
            created_at || new Date().toISOString(),
            created_at || new Date().toISOString(),
            created_at || new Date().toISOString()
          ).run()

          importedCount++

          // 🏷️ Cerca codice sconto nelle note
          if (note) {
            try {
              const { applyDiscountFromNotes } = await import('./modules/discount-from-notes')
              const discountRes = await applyDiscountFromNotes(c.env.DB, id, note)
              if (discountRes.applied) {
                console.log(`🏷️  [IMPORT-BULK] Sconto applicato: ${discountRes.message}`)
              }
            } catch (discountErr) {
              console.warn(`⚠️  [IMPORT-BULK] Errore applicazione sconto per ${id}:`, discountErr)
            }
          }
        } catch (err: any) {
          errorCount++
          errors.push({
            lead: lead.id,
            error: err.message
          })
        }
      }
    }

    console.log(`✅ Import completato: ${importedCount} successi, ${errorCount} errori`)

    return c.json({
      success: true,
      imported: importedCount,
      errors: errorCount,
      errorDetails: errors
    })

  } catch (error: any) {
    console.error('❌ Errore import bulk:', error)
    return c.json({
      success: false,
      error: error.message || 'Errore import bulk'
    }, 500)
  }
})

// Endpoint per CLEAN IMPORT: Cancella tutti i lead esistenti e importa i 129 dall'Excel
app.post('/api/leads/clean-import', async (c) => {
  try {
    const { DB } = c.env
    
    if (!DB) {
      return c.json({ 
        success: false, 
        error: 'Database D1 non configurato' 
      }, 400)
    }

    console.log('🔄 CLEAN IMPORT: Inizio cancellazione e reimport da Excel...')

    // Step 1: Cancella tutti i lead esistenti
    console.log('🗑️  Step 1: Cancellazione lead esistenti...')
    const deleteResult = await DB.prepare('DELETE FROM leads').run()
    console.log(`✅ Cancellati ${deleteResult.changes || 0} lead esistenti`)

    // Step 2: Ricevi i lead dal body
    const body = await c.req.json()
    const leads = body.leads || []
    
    if (!Array.isArray(leads) || leads.length === 0) {
      return c.json({
        success: false,
        error: 'Nessun lead fornito nel body. Usa { "leads": [...] }'
      }, 400)
    }
    
    console.log(`📥 Step 2: Import di ${leads.length} lead dall'Excel...`)

    let imported = 0
    let errors = 0
    const errorDetails: any[] = []

    // Step 3: Inserisci i lead in batch di 20
    for (let i = 0; i < leads.length; i += 20) {
      const batch = leads.slice(i, i + 20)
      
      for (const lead of batch) {
        try {
          // Splitta nome in nome e cognome
          const nameParts = (lead.nome || '').split(' ')
          const nome = nameParts[0] || ''
          const cognome = nameParts.slice(1).join(' ') || ''
          
          await DB.prepare(`
            INSERT INTO leads (
              id, nomeRichiedente, cognomeRichiedente, email, telefono, 
              fonte, tipoServizio, status, note, 
              created_at, updated_at, timestamp
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          `).bind(
            lead.id,
            nome,
            cognome,
            lead.email || '',
            lead.telefono || '',
            lead.canale || 'IRBEMA',
            'eCura PRO',
            lead.status || 'NEW',
            lead.note || '',
            lead.data_arrivo,
            lead.data_arrivo,
            new Date(lead.data_arrivo).getTime()
          ).run()
          
          imported++
        } catch (err: any) {
          console.error(`❌ Errore import lead ${lead.id}:`, err.message)
          errors++
          errorDetails.push({
            id: lead.id,
            nome: lead.nome,
            error: err.message
          })
        }
      }
    }

    console.log(`✅ CLEAN IMPORT completato: ${imported} importati, ${errors} errori`)

    return c.json({
      success: true,
      message: 'Clean import completato',
      deleted: deleteResult.changes || 0,
      imported,
      errors,
      errorDetails,
      total: leads.length
    })

  } catch (error: any) {
    console.error('❌ Errore clean import:', error)
    return c.json({
      success: false,
      error: error.message || 'Errore clean import'
    }, 500)
  }
})

