// POST /api/leads/:id/send-contract - Genera contratto HTML e invia email
app.post('/api/leads/:id/send-contract', async (c) => {
  const leadId = c.req.param('id')
  
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    // Recupera lead con TUTTI i campi
    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    
    if (!lead) {
      return c.json({ success: false, error: 'Lead non trovato' }, 404)
    }
    
    console.log('📄 Creazione contratto per lead:', leadId)
    console.log('📄 Lead data:', { 
      email: lead.email, 
      nome: lead.nomeRichiedente, 
      cognome: lead.cognomeRichiedente,
      servizio: lead.servizio,
      piano: lead.piano
    })
    
    // ✅ VALIDAZIONE CAMPI OBBLIGATORI
    if (!lead.email) {
      console.error('❌ Email mancante per lead:', leadId)
      return c.json({ 
        success: false, 
        error: 'Email mancante',
        details: 'Il lead non ha un indirizzo email valido. Impossibile inviare il contratto.'
      }, 400)
    }
    
    if (!lead.nomeRichiedente || !lead.cognomeRichiedente) {
      console.error('❌ Nome/Cognome mancante per lead:', leadId)
      return c.json({ 
        success: false, 
        error: 'Dati incompleti',
        details: 'Nome o cognome del richiedente mancanti. Completa il profilo del lead prima di inviare il contratto.'
      }, 400)
    }
    
    // Ottieni tipoContratto e flag rinnovo dal body se presenti
    const body = await c.req.json().catch(() => ({}))
    const pianoRichiesto = body.tipoContratto || body.piano
    // Flag rinnovo opzionali dal body
    const isRinnovoReq       = !!(body.isRinnovo || body.is_rinnovo)
    const annoRinnovoReq     = body.annoRinnovo || body.anno_rinnovo || 2
    const codiceOriginaleReq = body.codiceOriginale || body.rinnovo_di || ''

    // 🔄 SE È UN RINNOVO: usa la route dedicata /api/contracts/rinnovo
    // che invia email_rinnovo_contratto invece di email_invio_contratto (primo contratto)
    if (isRinnovoReq) {
      console.log(`🔄 [SEND-CONTRACT] isRinnovo=true → delega a logica rinnovo dedicata (codice originale: ${codiceOriginaleReq})`)

      // Trova il contractId del contratto originale dal codice
      const origContract = await c.env.DB.prepare(
        `SELECT id FROM contracts WHERE codice_contratto = ? AND leadId = ? ORDER BY created_at DESC LIMIT 1`
      ).bind(codiceOriginaleReq, leadId).first() as any

      if (!origContract) {
        return c.json({
          success: false,
          error: 'Contratto originale non trovato',
          details: `Nessun contratto con codice "${codiceOriginaleReq}" per il lead ${leadId}`
        }, 404)
      }

      // ✅ Chiama la logica rinnovo direttamente via app.fetch (no self-fetch, non supportato in CF Workers)
      // dryRun=true: crea contratto nel DB ma NON invia email — restituisce link per verifica
      const rinnovoReq = new Request('https://internal/api/contracts/rinnovo', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Cookie': c.req.header('Cookie') || '' },
        body: JSON.stringify({ contractId: origContract.id, annoRinnovo: annoRinnovoReq, dryRun: true })
      })
      const rinnovoResp = await app.fetch(rinnovoReq, c.env, c.executionCtx)
      const rinnovoResult = await rinnovoResp.json() as any
      return c.json(rinnovoResult, rinnovoResp.status as any)
    }

    const timestamp = Date.now()
    const cognome = (lead.cognomeAssistito || lead.cognomeRichiedente || 'UNKNOWN').toUpperCase().replace(/[^A-Z]/g, '')
    const anno = new Date().getFullYear()
    const contractId = isRinnovoReq
      ? `CONTRACT_RIN-${cognome}-${anno}_${timestamp}`
      : `CONTRACT_CTR-${cognome}-${anno}_${timestamp}`
    const contractCode = isRinnovoReq
      ? `RIN-${cognome}-${anno}`
      : `CTR-${cognome}-${anno}`
    
    // Determina servizio e piano (usa quello richiesto se presente, altrimenti quello del lead)
    const servizio = lead.servizio || 'eCura PRO'
    const piano = pianoRichiesto || lead.piano || 'BASE'
    
    console.log('📄 Piano contratto:', piano, '(richiesto:', pianoRichiesto, 'lead:', lead.piano, ')')
    
    // ⭐ CALCOLA dati intestatario in base a intestatarioContratto
    // CRITICAL: i campi nomeIntestatario/cognomeIntestatario NON esistono nel DB!
    // Devono essere calcolati dinamicamente:
    const intestatario = lead.intestatarioContratto || 'richiedente'
    
    let nomeIntestatario: string, cognomeIntestatario: string
    let cfIntestatario: string, indirizzoIntestatario: string
    let cittaIntestatario: string, capIntestatario: string, provinciaIntestatario: string
    let luogoNascitaIntestatario: string, dataNascitaIntestatario: string
    
    if (intestatario === 'assistito') {
      // Intestatario = Assistito
      nomeIntestatario = lead.nomeAssistito || lead.nomeRichiedente
      cognomeIntestatario = lead.cognomeAssistito || lead.cognomeRichiedente
      // ✅ FIX: quando intestatario='assistito', il CF è quello dell'ASSISTITO (cfAssistito ha priorità)
      // cfIntestatario è un campo generico che può contenere il CF del richiedente/firmatario — NON dell'assistito
      cfIntestatario = lead.cfAssistito || lead.cfIntestatario || ''
      indirizzoIntestatario = lead.indirizzoIntestatario || lead.indirizzoAssistito || ''
      cittaIntestatario = lead.cittaIntestatario || lead.cittaAssistito || ''
      capIntestatario = lead.capIntestatario || lead.capAssistito || ''
      provinciaIntestatario = lead.provinciaIntestatario || lead.provinciaAssistito || ''
      luogoNascitaIntestatario = lead.luogoNascitaIntestatario || lead.luogoNascitaAssistito || ''
      dataNascitaIntestatario = lead.dataNascitaIntestatario || lead.dataNascitaAssistito || ''
    } else {
      // Intestatario = Richiedente (default)
      // I campi *Intestatario SONO GIÀ i campi del richiedente
      nomeIntestatario = lead.nomeRichiedente
      cognomeIntestatario = lead.cognomeRichiedente
      // ✅ FIX: Fallback su cfAssistito quando cfIntestatario è vuoto
      // Caso Badano Littardi: richiedente = assistito, cfIntestatario vuoto ma cfAssistito valorizzato
      cfIntestatario = lead.cfIntestatario || lead.cfAssistito || ''
      indirizzoIntestatario = lead.indirizzoIntestatario || ''
      cittaIntestatario = lead.cittaIntestatario || ''
      capIntestatario = lead.capIntestatario || ''
      provinciaIntestatario = lead.provinciaIntestatario || ''
      luogoNascitaIntestatario = lead.luogoNascitaIntestatario || ''
      dataNascitaIntestatario = lead.dataNascitaIntestatario || ''
    }
    
    // Prepara leadData per workflow
    const leadData = {
      id: leadId,
      nomeRichiedente: lead.nomeRichiedente,
      cognomeRichiedente: lead.cognomeRichiedente,
      email: lead.email,
      telefono: lead.telefono || '',
      nomeAssistito: lead.nomeAssistito || lead.nomeRichiedente,
      cognomeAssistito: lead.cognomeAssistito || lead.cognomeRichiedente,
      luogoNascitaAssistito: lead.luogoNascitaAssistito || '',
      dataNascitaAssistito: lead.dataNascitaAssistito || '',
      indirizzoAssistito: lead.indirizzoAssistito || '',
      capAssistito: lead.capAssistito || '',
      cittaAssistito: lead.cittaAssistito || '',
      provinciaAssistito: lead.provinciaAssistito || '',
      cfAssistito: lead.cfAssistito || '',
      condizioniSalute: lead.condizioniSalute || '',
      pacchetto: piano,
      servizio: servizio,
      intestatarioContratto: lead.intestatarioContratto || 'richiedente',
      // ⭐ AGGIUNGI campi intestatario CALCOLATI
      nomeIntestatario,
      cognomeIntestatario,
      emailIntestatario: lead.email,
      telefonoIntestatario: lead.telefono || '',
      cfIntestatario,
      indirizzoIntestatario,
      cittaIntestatario,
      capIntestatario,
      provinciaIntestatario,
      luogoNascitaIntestatario,
      dataNascitaIntestatario,
      vuoleBrochure: true,  // Include brochure con contratto
      vuoleManuale: false,
      vuoleContratto: true,
      // ✅ FIX: Passa iva_agevolata al workflow così il contract generator usa l'aliquota corretta
      iva_agevolata: lead.iva_agevolata ? 1 : 0
    }
    
    // Calcola prezzi corretti
    const servizioType = servizio.replace('eCura ', '').trim().toUpperCase()
    const pianoType = piano.toUpperCase()
    const { calculatePrice } = await import('./modules/pricing-calculator')
    const pricing = calculatePrice(servizioType, pianoType)

    // ✅ FIX: calcola prezzoIvaInclusa con l'aliquota corretta del lead
    // pricing.setupTotale usa sempre 22% — dobbiamo ricalcolarlo se iva_agevolata
    const ivaRateContratto = lead.iva_agevolata ? 0.04 : 0.22
    // Per rinnovo usa rinnovoBase; per primo anno usa setupBase
    const prezzoBaseContratto = isRinnovoReq
      ? (pricing.rinnovoBase ?? pricing.setupBase)
      : pricing.setupBase
    const prezzoIvaInclusa = Math.round(prezzoBaseContratto * (1 + ivaRateContratto) * 100) / 100

    console.log(`💰 [CONTRATTO] ${isRinnovoReq ? '🔄 RINNOVO' : 'PRIMO ANNO'}: base €${prezzoBaseContratto}, IVA ${ivaRateContratto * 100}%, totale €${prezzoIvaInclusa} (iva_agevolata=${lead.iva_agevolata})`)
    
    // Fetch rate di pagamento (se rateizzazione attiva)
    let rateContratto: Array<{ numero_rata: number; importo: number; data_scadenza: string; status: string }> = []
    if (lead.rateizzazione_attiva) {
      try {
        const rateRows = await c.env.DB.prepare(
          `SELECT numero_rata, importo, data_scadenza, status FROM rate_pagamento WHERE lead_id = ? ORDER BY numero_rata ASC`
        ).bind(leadId).all()
        rateContratto = (rateRows?.results || []) as any[]
        console.log(`📅 [CONTRATTO] Rate trovate: ${rateContratto.length}`)
      } catch (e) {
        console.warn(`⚠️ [CONTRATTO] Errore fetch rate:`, e)
      }
    }

    // Prepara contractData
    const contractData = {
      contractId: contractId,
      contractCode: contractCode,
      contractPdfUrl: '',
      tipoServizio: piano,
      servizio: servizio,
      prezzoBase: prezzoBaseContratto,
      prezzoIvaInclusa: prezzoIvaInclusa,  // ✅ calcolato con aliquota corretta (4% o 22%)
      // ✅ Flag rinnovo passati a generateContractHtml per adattare sezione Tariffa
      isRinnovo: isRinnovoReq,
      annoRinnovo: annoRinnovoReq,
      codiceOriginale: codiceOriginaleReq,
      // 🔒 Riserva di Dominio (solo per lead rateizzati con flag attivo)
      riserva_dominio: Boolean(lead.riserva_dominio),
      // 📅 Rateizzazione
      rateizzazione_attiva: Boolean(lead.rateizzazione_attiva),
      rateizzazione_note: lead.rateizzazione_note || '',
      rate: rateContratto
    }
    
    // Usa workflow per inviare email contratto
    console.log('📧 Import workflow-email-manager...')
    const { inviaEmailContratto } = await import('./modules/workflow-email-manager')
    
    // ✅ Non passare documentUrls: il workflow userà brochure-manager per caricare la brochure corretta
    const documentUrls: { brochure?: string; manuale?: string } = {}
    // REMOVED: documentUrls.brochure = '/brochures/Brochure_eCura_2024.pdf'
    // Il workflow caricherà automaticamente la brochure corretta in base al servizio
    
    console.log('📧 Chiamata inviaEmailContratto con:', {
      leadId: leadData.id,
      email: leadData.email,
      servizio: contractData.servizio,
      piano: contractData.tipoServizio,
      documentUrls
    })
    
    let result
    try {
      result = await inviaEmailContratto(leadData, contractData, c.env, documentUrls, c.env.DB)
      console.log('📧 Risultato invio email contratto:', result)
    } catch (emailError) {
      console.error('❌ ERRORE in inviaEmailContratto:', emailError)
      console.error('❌ Stack:', emailError instanceof Error ? emailError.stack : 'N/A')
      return c.json({
        success: false,
        error: 'Errore durante invio email',
        details: emailError instanceof Error ? emailError.message : String(emailError)
      }, 500)
    }
    
    if (result.success) {
      // Aggiorna lead
      await c.env.DB.prepare(`
        UPDATE leads SET 
          vuoleContratto = 'Si',
          status = 'CONTRACT_SENT',
          updated_at = ?
        WHERE id = ?
      `).bind(new Date().toISOString(), leadId).run()
      
      console.log('✅ Lead aggiornato, contratto inviato con successo')
      
      return c.json({
        success: true,
        message: 'Contratto inviato con successo',
        contractId: contractId,
        contractCode: contractCode
      })
    } else {
      console.error('❌ Errore invio email contratto:', result.errors)
      return c.json({
        success: false,
        error: 'Errore invio contratto',
        details: result.errors && result.errors.length > 0 ? result.errors.join(', ') : 'Errore sconosciuto durante invio email'
      }, 500)
    }
    
  } catch (error) {
    console.error('❌ Errore invio contratto (catch):', error)
    console.error('❌ Stack trace:', error instanceof Error ? error.stack : 'N/A')
    return c.json({
      success: false,
      error: 'Errore invio contratto',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})
// POST /api/leads/:id/send-brochure - Invia brochure specifica a lead
app.post('/api/leads/:id/send-brochure', async (c) => {
  const leadId = c.req.param('id')
  
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    // Recupera lead
    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    
    if (!lead) {
      return c.json({ success: false, error: 'Lead non trovato' }, 404)
    }
    
    const servizio = (lead.servizio || 'eCura PRO').replace('eCura ', '').toUpperCase()
    const piano = (lead.piano || 'BASE').toUpperCase()
    
    console.log(`📥 [BROCHURE] Invio brochure per ${servizio} ${piano}`)
    
    // 1. CARICA BROCHURE PDF
    const attachments: Array<{ filename: string; content: string; contentType: string }> = []
    
    // ✅ Usa brochure-manager per caricare PDF corretto per dispositivo
    const { loadBrochurePDF } = await import('./modules/brochure-manager')
    const { getBaseUrl: getBaseUrlFn } = await import('./modules/url-helper')
    const baseUrl = getBaseUrlFn(c.env)
    const servizioNormalized = servizio.replace(/^eCura\s+/i, '').trim().toUpperCase()
    
    console.log(`📥 [BROCHURE] Caricamento brochure per servizio: ${servizioNormalized}`)
    
    const brochurePdf = await loadBrochurePDF(servizioNormalized, baseUrl, true) // ← validateSize=true (brochure SiDLY)
    
    if (brochurePdf) {
      attachments.push({
        filename: brochurePdf.filename,
        content: brochurePdf.content,
        contentType: 'application/pdf'
      })
      console.log(`✅ [BROCHURE] Brochure allegata: ${brochurePdf.filename} (${(brochurePdf.size / 1024).toFixed(2)} KB)`)
    } else {
      console.error('❌ [BROCHURE] Servizio non trovato o PDF non disponibile')
      return c.json({ success: false, error: 'Brochure non disponibile per il servizio selezionato' }, 500)
    }
    
    // 2. INVIA EMAIL CON BROCHURE usando template DB
    const EmailServiceClass = (await import('./modules/email-service')).default
    const { loadEmailTemplate, renderTemplate } = await import('./modules/template-loader-clean')
    
    // Carica template dal database (restituisce solo HTML string)
    const templateHtml = await loadEmailTemplate('email_brochure', c.env.DB, c.env)
    
    const variables = {
      NOME_CLIENTE: lead.nomeRichiedente || 'Cliente',
      COGNOME_CLIENTE: lead.cognomeRichiedente || '',
      LEAD_ID: leadId,
      SERVIZIO: `eCura ${servizio}`,
      PIANO: piano === 'AVANZATO' ? 'Avanzato' : 'Base',
      NOME_ASSISTITO: lead.nomeAssistito || lead.nomeRichiedente || '',
      COGNOME_ASSISTITO: lead.cognomeAssistito || lead.cognomeRichiedente || ''
    }
    
    // Render template con variabili
    const htmlContent = renderTemplate(templateHtml, variables)
    
    console.log('📧 [BROCHURE] Invio email con allegato brochure...')
    console.log('📧 [BROCHURE] HTML content length:', htmlContent.length)
    console.log('📧 [BROCHURE] To:', lead.email)
    
    const emailService = new EmailServiceClass(c.env)
    const result = await emailService.sendEmail({
      to: lead.email,
      from: c.env.RESEND_FROM || c.env.EMAIL_FROM || 'info@ecura.it',
      subject: `eCura - Brochure ${servizio}`,
      html: htmlContent,
      attachments
    })
    
    // Log DEMO MODE warning
    if ((result as any).demoMode) {
      console.error('🚨 [BROCHURE] ⚠️ DEMO MODE ATTIVO - Email NON inviata realmente!')
      console.error('🚨 [BROCHURE] Configura RESEND_API_KEY o SENDGRID_API_KEY su Cloudflare Pages')
      console.error('🚨 [BROCHURE] Warning:', (result as any).warning)
      console.error('🚨 [BROCHURE] Errors:', JSON.stringify((result as any).errors, null, 2))
    }
    
    // 3. AGGIORNA DATABASE
    if (result.success) {
      // Aggiorna lead
      await c.env.DB.prepare(`
        UPDATE leads SET 
          vuoleBrochure = 'Si',
          status = CASE 
            WHEN status = 'NEW' THEN 'BROCHURE_SENT'
            ELSE status
          END,
          updated_at = ?
        WHERE id = ?
      `).bind(new Date().toISOString(), leadId).run()
      
      // Log email
      await c.env.DB.prepare(`
        INSERT INTO email_logs (
          leadId, recipient_email, template_used, 
          subject, status, provider_used, sent_at
        ) VALUES (?, ?, ?, ?, ?, 'RESEND', ?)
      `).bind(
        leadId,
        lead.email,
        'email_brochure',
        `eCura - Brochure ${servizio}`,
        result.success ? 'SENT' : 'SIMULATED',
        new Date().toISOString()
      ).run()
      
      console.log('✅ [BROCHURE] Brochure inviata con successo')
      
      return c.json({
        success: true,
        message: `Brochure ${brochurePdf.filename} inviata a ${lead.email}`,
        emailStatus: result.success ? 'sent' : 'simulated',
        attachments: attachments.length,
        demoMode: (result as any).demoMode || false,
        warning: (result as any).demoMode ? '⚠️ DEMO MODE: Email NON inviata realmente! Configura RESEND_API_KEY' : undefined
      })
    } else {
      return c.json({
        success: false,
        error: 'Errore invio email: ' + result.error
      }, 500)
    }
    
  } catch (error) {
    console.error('❌ [BROCHURE] Errore invio brochure:', error)
    return c.json({ 
      success: false, 
      error: 'Errore invio brochure',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

