// POST /api/leads/:id/complete - Endpoint per completamento dati da form email
app.post('/api/leads/:id/complete', async (c) => {
  const id = c.req.param('id')
  
  console.log(`🔔🔔🔔 [COMPLETE] Endpoint chiamato per lead: ${id}`)
  console.log(`🔔🔔🔔 [COMPLETE] Timestamp: ${new Date().toISOString()}`)
  
  try {
    // Supporta sia JSON che form-data
    const contentType = c.req.header('content-type') || ''
    let data: any
    
    if (contentType.includes('application/json')) {
      data = await c.req.json()
    } else {
      // Form data da email
      const formData = await c.req.formData()
      data = {}
      for (const [key, value] of formData.entries()) {
        data[key] = value
      }
    }
    
    console.log(`📝 [COMPLETE] Lead ${id} - Dati ricevuti:`, JSON.stringify(data, null, 2))
    console.log(`📝 [COMPLETE] Content-Type:`, contentType)
    console.log(`📝 [COMPLETE] DB disponibile:`, !!c.env?.DB)
    
    if (!c.env?.DB) {
      return c.text('✅ Grazie! I tuoi dati sono stati salvati con successo. Ti contatteremo presto.', 200, {
        'Content-Type': 'text/html; charset=utf-8'
      })
    }
    
    // Costruisci query UPDATE
    const updateFields: string[] = []
    const binds: any[] = []
    
    // Mapping campi form → DB (TUTTI i campi esistono nel DB)
    const fieldMapping: Record<string, string> = {
      nomeRichiedente: 'nomeRichiedente',
      cognomeRichiedente: 'cognomeRichiedente',
      email: 'email',
      // email: 'email',  // ← RIMOSSO: gestiamo email separatamente
      telefono: 'telefono',
      // telefono: 'telefono',  // ← RIMOSSO: gestiamo telefono separatamente
      
      // Dati Intestatario (per la proposta)
      cfIntestatario: 'cfIntestatario',
      indirizzoIntestatario: 'indirizzoIntestatario',
      capIntestatario: 'capIntestatario',
      cittaIntestatario: 'cittaIntestatario',
      provinciaIntestatario: 'provinciaIntestatario',  // ✅ FIX: aggiunto campo provincia intestatario
      luogoNascitaIntestatario: 'luogoNascitaIntestatario',  // ✅ FIX: aggiunto luogo nascita
      dataNascitaIntestatario: 'dataNascitaIntestatario',    // ✅ FIX: aggiunto data nascita
      
      // Dati Assistito
      nomeAssistito: 'nomeAssistito',
      cognomeAssistito: 'cognomeAssistito',
      dataNascitaAssistito: 'dataNascitaAssistito',
      luogoNascitaAssistito: 'luogoNascitaAssistito',
      indirizzoAssistito: 'indirizzoAssistito',
      capAssistito: 'capAssistito',
      cittaAssistito: 'cittaAssistito',
      provinciaAssistito: 'provinciaAssistito',  // ✅ FIX: aggiunto campo provincia
      cfAssistito: 'cfAssistito',
      condizioniSalute: 'condizioniSalute',  // Campo per trigger contratto
      
      servizio: 'servizio',
      piano: 'piano',
      note: 'note',
      gdprConsent: 'gdprConsent',
      iva_agevolata: 'iva_agevolata'  // 1 = IVA 4% Legge 104 (disabilità 100%), 0 = IVA 22% standard
    }
    
    for (const [formField, dbField] of Object.entries(fieldMapping)) {
      if (data[formField] !== undefined && data[formField] !== '') {
        updateFields.push(`${dbField} = ?`)
        
        // Converti checkbox a integer (0/1)
        if (formField === 'gdprConsent' || formField === 'iva_agevolata') {
          binds.push(data[formField] === '1' || data[formField] === 'true' || data[formField] === true ? 1 : 0)
        } else {
          binds.push(data[formField])
        }
      }
    }
    
    // 🔧 FIX CRITICO: Gestione doppi campi email/telefono
    // Il DB ha sia 'email' (NOT NULL legacy) che 'email' (nuovo)
    // Dobbiamo popolare ENTRAMBI per evitare NOT NULL constraint
    
    // Gestione EMAIL: popola sia 'email' che 'email'
    const emailValue = data.email || data.email
    if (emailValue) {
      // Aggiungi 'email' se non già presente
      if (!updateFields.some(f => f.startsWith('email ='))) {
        updateFields.push('email = ?')
        binds.push(emailValue)
      }
      // Aggiungi 'email' se non già presente
      if (!updateFields.some(f => f.startsWith('email ='))) {
        updateFields.push('email = ?')
        binds.push(emailValue)
      }
    }
    
    // Gestione TELEFONO: popola sia 'telefono' che 'telefono'
    const telefonoValue = data.telefono || data.telefono
    if (telefonoValue) {
      // Aggiungi 'telefono' se non già presente
      if (!updateFields.some(f => f.startsWith('telefono ='))) {
        updateFields.push('telefono = ?')
        binds.push(telefonoValue)
      }
      // Aggiungi 'telefono' se non già presente
      if (!updateFields.some(f => f.startsWith('telefono ='))) {
        updateFields.push('telefono = ?')
        binds.push(telefonoValue)
      }
    }
    
    console.log(`🔍 [COMPLETE] Fields to update:`, updateFields)
    console.log(`🔍 [COMPLETE] Values:`, binds)
    
    // ✅ Aggiungi aggiornamento status a COMPLETED
    updateFields.push('status = ?')
    binds.push('COMPLETED')

    // ✅ FIX ALLA FONTE: imposta intestatarioContratto in base ai dati ricevuti.
    // Se il form invia nomeAssistito/cognomeAssistito diversi dal richiedente → 'assistito'.
    // Se identici o assenti → 'richiedente'.
    // Questo corregge il default 'richiedente' che veniva assegnato ai lead HubSpot.
    {
      const currentLead = await c.env.DB.prepare('SELECT nomeRichiedente, cognomeRichiedente, intestatarioContratto FROM leads WHERE id = ?').bind(id).first() as any
      const nomeAss = (data.nomeAssistito || currentLead?.nomeRichiedente || '').trim().toLowerCase()
      const cogAss  = (data.cognomeAssistito || currentLead?.cognomeRichiedente || '').trim().toLowerCase()
      const nomeRic = (currentLead?.nomeRichiedente || '').trim().toLowerCase()
      const cogRic  = (currentLead?.cognomeRichiedente || '').trim().toLowerCase()
      const isAssistitoDiverso = nomeAss && cogAss && (nomeAss !== nomeRic || cogAss !== cogRic)
      const nuovoIntestario = isAssistitoDiverso ? 'assistito' : 'richiedente'
      // Aggiorna solo se non già impostato correttamente
      if (!currentLead?.intestatarioContratto || currentLead.intestatarioContratto === 'richiedente' && isAssistitoDiverso) {
        updateFields.push('intestatarioContratto = ?')
        binds.push(nuovoIntestario)
        console.log(`📋 [COMPLETE] intestatarioContratto → '${nuovoIntestario}' (assistito diverso da richiedente: ${isAssistitoDiverso})`)
      }
    }

    if (updateFields.length === 0) {
      return c.text('❌ Nessun dato da aggiornare', 400)
    }
    
    // Aggiorna lead
    binds.push(id)
    const query = `UPDATE leads SET ${updateFields.join(', ')}, updated_at = datetime('now') WHERE id = ?`
    
    console.log('🔍 [COMPLETE] Query UPDATE:', query)
    console.log('🔍 [COMPLETE] Binds:', binds)
    console.log('🔍 [COMPLETE] Lead ID:', id)
    
    let result
    try {
      result = await c.env.DB.prepare(query).bind(...binds).run()
      console.log('✅ [COMPLETE] UPDATE eseguito con successo')
    } catch (updateError) {
      console.error('❌ [COMPLETE] ERRORE UPDATE DATABASE:', updateError)
      console.error('❌ [COMPLETE] Query che ha fallito:', query)
      console.error('❌ [COMPLETE] Binds:', JSON.stringify(binds))
      throw new Error(`Errore aggiornamento database: ${updateError instanceof Error ? updateError.message : String(updateError)}`)
    }
    
    console.log('🔍 Update result:', JSON.stringify(result))
    console.log('🔍 Rows affected:', result.meta?.changes || 0)
    
    // Verifica se il lead è stato aggiornato
    if (result.meta?.changes === 0) {
      console.error('❌ Nessun lead aggiornato - ID non trovato:', id)
      return c.json({
        success: false,
        error: 'Lead non trovato',
        message: `Impossibile trovare il lead con ID: ${id}`
      }, 404)
    }
    
    // ✅ TRIGGER: Invio automatico contratto dopo completamento dati
    console.log(`🔔🔔🔔 [TRIGGER] Inizio verifica trigger contratto per lead: ${id}`)
    try {
      console.log('🔔 [COMPLETAMENTO] Verifico se inviare contratto automaticamente...')
      
      // Recupera lead aggiornato
      const updatedLead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?')
        .bind(id)
        .first()
      
      console.log(`🔍 [COMPLETAMENTO] Lead aggiornato trovato: ${!!updatedLead}`)
      
      if (updatedLead) {
        // Importa funzioni workflow
        const { inviaEmailContratto } = await import('./modules/workflow-email-manager')
        const { isLeadComplete } = await import('./modules/lead-completion')
        
        console.log(`🔍 [COMPLETAMENTO] Verifica completezza lead...`)
        
        // Verifica se lead è completo
        const leadComplete = isLeadComplete(updatedLead)
        console.log(`🔍 [COMPLETAMENTO] isLeadComplete() = ${leadComplete}`)
        
        if (leadComplete) {
          console.log('✅ [COMPLETAMENTO] Lead completo → Invio contratto e brochure automatico')
          
          // SEMPRE ATTIVO: invio contratto e brochure dopo completamento dati
          if (true) {
            // Genera contratto
            const timestamp = Date.now()
            const cognome = ((updatedLead as any).cognomeAssistito || (updatedLead as any).cognomeRichiedente || 'UNKNOWN').toUpperCase().replace(/[^A-Z]/g, '')
            const anno = new Date().getFullYear()
            const contractId = `CONTRACT_CTR-${cognome}-${anno}_${timestamp}`
            const contractCode = `CTR-${cognome}-${anno}`
            
            const servizioRaw = (updatedLead as any).servizio || 'eCura PRO'
            const pianoRaw = (updatedLead as any).piano || 'BASE'
            
            // ✅ NORMALIZZA PIANO: converte tutte le varianti in maiuscolo
            const piano = pianoRaw.toUpperCase().includes('AVANZAT') ? 'AVANZATO' : 'BASE'
            
            // ✅ FIX: Estrai tipo servizio (FAMILY/PRO/PREMIUM) da "eCura PREMIUM"
            let servizioTipo: 'FAMILY' | 'PRO' | 'PREMIUM' = 'PRO'
            if (servizioRaw.includes('FAMILY')) servizioTipo = 'FAMILY'
            else if (servizioRaw.includes('PREMIUM')) servizioTipo = 'PREMIUM'
            else if (servizioRaw.includes('PRO')) servizioTipo = 'PRO'
            
            console.log(`🔍 [COMPLETAMENTO] Servizio raw: "${servizioRaw}" → tipo: ${servizioTipo}`)
            console.log(`🔍 [COMPLETAMENTO] Piano raw: "${pianoRaw}" → normalizzato: ${piano}`)
            console.log(`🔍 [COMPLETAMENTO] getPricing('${servizioTipo}', '${piano}')`)
            
            // Calcola pricing
            const { getPricing } = await import('./modules/ecura-pricing')
            const pricing = getPricing(servizioTipo, piano)
            
            if (!pricing) {
              console.error(`❌ [COMPLETAMENTO] Pricing non trovato per ${servizioTipo} ${piano}`)
              throw new Error(`Pricing non disponibile per ${servizioTipo} ${piano}`)
            }
            
            console.log(`✅ [COMPLETAMENTO] Pricing trovato:`)
            console.log(`   - setupBase: €${pricing.setupBase} (IVA esclusa)`)
            console.log(`   - setupTotale: €${pricing.setupTotale} (IVA inclusa)`)
            console.log(`   - rinnovoBase: €${pricing.rinnovoBase} (IVA esclusa)`)
            console.log(`   - rinnovoTotale: €${pricing.rinnovoTotale} (IVA inclusa)`)
            console.log(`   - dispositivo: ${pricing.dispositivo}`)
            
            // Prepara contractData
            const contractData = {
              contractId,
              contractCode,
              contractPdfUrl: '',
              tipoServizio: piano,
              servizio: servizioRaw,
              prezzoBase: pricing.setupBase,
              prezzoIvaInclusa: pricing.setupTotale
            }
            
            // Document URLs
            // NON passare documentUrls - workflow usa brochure-manager
            const documentUrls: { brochure?: string; manuale?: string } = {}
            
            // Invia contratto
            const contractResult = await inviaEmailContratto(
              updatedLead as any,
              contractData,
              c.env,
              documentUrls,
              c.env.DB
            )
            
            if (contractResult.success) {
              console.log('✅ [COMPLETAMENTO] Contratto e brochure inviati con successo!')
              
              // Aggiorna lead
              await c.env.DB.prepare(`
                UPDATE leads SET 
                  vuoleContratto = 'Si',
                  vuoleBrochure = 'Si',
                  status = 'CONTRACT_SENT',
                  updated_at = ?
                WHERE id = ?
              `).bind(new Date().toISOString(), id).run()
            } else {
              console.error('❌ [COMPLETAMENTO] Errore invio contratto:', contractResult.errors)
            }
          } else {
            console.log('ℹ️ [COMPLETAMENTO] Invio contratto disabilitato manualmente (non dovrebbe accadere)')
          }
        } else {
          console.log('ℹ️ [COMPLETAMENTO] Lead non ancora completo, contratto non inviato')
        }
      }
    } catch (triggerError) {
      // Non blocchiamo la risposta se il trigger fallisce
      console.error('⚠️ [COMPLETAMENTO] Errore trigger contratto:', triggerError)
      console.error('⚠️ [COMPLETAMENTO] Stack trace:', (triggerError as Error)?.stack)
    }
    
    // ✅ NOTIFICA: Invia email a info@ecura.it quando form completato
    try {
      const updatedLead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?')
        .bind(id)
        .first()
      
      if (updatedLead) {
        const leadData = updatedLead as any
        
        // Prepara email notifica admin
        const emailHtml = `
          <!DOCTYPE html>
          <html>
          <head>
            <meta charset="UTF-8">
            <style>
              body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
              .container { max-width: 600px; margin: 20px auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px; }
              .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 20px; border-radius: 6px; margin-bottom: 20px; }
              .field { margin: 10px 0; padding: 8px; background: #f9f9f9; border-left: 3px solid #667eea; }
              .label { font-weight: bold; color: #555; }
              .value { color: #000; }
              .footer { margin-top: 20px; padding-top: 20px; border-top: 1px solid #ddd; font-size: 12px; color: #666; }
            </style>
          </head>
          <body>
            <div class="container">
              <div class="header">
                <h2>📝 Form Completamento Dati Compilato</h2>
              </div>
              
              <p>Un lead ha completato il form di inserimento dati.</p>
              
              <h3>📋 Dati Lead</h3>
              <div class="field"><span class="label">ID:</span> <span class="value">${leadData.id}</span></div>
              <div class="field"><span class="label">Nome Richiedente:</span> <span class="value">${leadData.nomeRichiedente} ${leadData.cognomeRichiedente}</span></div>
              <div class="field"><span class="label">Email:</span> <span class="value">${leadData.email}</span></div>
              <div class="field"><span class="label">Telefono:</span> <span class="value">${leadData.telefono || 'N/D'}</span></div>
              
              <h3>👤 Dati Assistito</h3>
              <div class="field"><span class="label">Nome:</span> <span class="value">${leadData.nomeAssistito || 'N/D'} ${leadData.cognomeAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">Data Nascita:</span> <span class="value">${leadData.dataNascitaAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">Luogo Nascita:</span> <span class="value">${leadData.luogoNascitaAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">Codice Fiscale:</span> <span class="value">${leadData.cfAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">Indirizzo:</span> <span class="value">${leadData.indirizzoAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">CAP:</span> <span class="value">${leadData.capAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">Città:</span> <span class="value">${leadData.cittaAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">Provincia:</span> <span class="value">${leadData.provinciaAssistito || 'N/D'}</span></div>
              <div class="field"><span class="label">Condizioni Salute:</span> <span class="value">${leadData.condizioniSalute || 'N/D'}</span></div>
              
              <h3>🎯 Servizio</h3>
              <div class="field"><span class="label">Servizio:</span> <span class="value">${leadData.servizio || 'N/D'}</span></div>
              <div class="field"><span class="label">Piano:</span> <span class="value">${leadData.piano || 'N/D'}</span></div>
              
              <div class="footer">
                <p>🤖 Notifica automatica - eCura V12</p>
                <p>Dashboard: <a href="https://telemedcare-v12.pages.dev/leads-dashboard">Visualizza Lead</a></p>
              </div>
            </div>
          </body>
          </html>
        `
        
        // Invia email tramite EmailService (Resend → Brevo → SendGrid con fallback automatico)
        const { EmailService } = await import('./modules/email-service')
        const emailService = new EmailService(c.env)
        const notifyResult = await emailService.sendEmail({
          to: c.env?.EMAIL_TO || c.env?.EMAIL_TO_INFO || 'info@ecura.it',
          from: c.env?.RESEND_FROM || 'info@ecura.it',
          subject: `📝 Form Completato - ${leadData.nomeRichiedente} ${leadData.cognomeRichiedente}`,
          html: emailHtml
        })
        
        if (notifyResult.success) {
          console.log(`✅ [NOTIFICA] Email admin inviata per lead ${id} (${notifyResult.messageId})`)
        } else {
          console.error(`❌ [NOTIFICA] Errore invio email admin:`, notifyResult.error)
        }
      }
    } catch (notifyError) {
      console.error('⚠️ [NOTIFICA] Errore invio email admin (non blocca risposta):', notifyError)
    }
    
    // Ritorna JSON di successo
    return c.json({
      success: true,
      message: 'Dati salvati con successo',
      updated: result.meta?.changes || 0
    })
    
  } catch (error) {
    console.error('❌ Errore completamento lead:', error)
    return c.json({
      success: false,
      error: 'Errore salvataggio dati',
      message: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

