// POST /api/contracts/sign - Salva firma digitale
app.post('/api/contracts/sign', async (c) => {
  try {
    const data = await c.req.json()
    // ✅ Accetta sia signatureData (form firma) che firmaDigitale (workflow manager)
    const { contractId, signatureData, firmaDigitale, timestamp, userAgent, screenResolution, ipAddress } = data
    const signature = signatureData || firmaDigitale || 'Firma Manuale'
    
    if (!contractId || !signature) {
      return c.json({ 
        success: false, 
        error: 'Dati firma mancanti' 
      }, 400)
    }
    
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    // Recupera contratto
    const contract = await c.env.DB.prepare('SELECT * FROM contracts WHERE id = ?')
      .bind(contractId).first() as any
    
    if (!contract) {
      return c.json({ 
        success: false, 
        error: 'Contratto non trovato' 
      }, 404)
    }
    
    if (contract.status === 'SIGNED') {
      return c.json({ 
        success: false, 
        error: 'Contratto già firmato' 
      }, 400)
    }
    
    // Ottieni IP del cliente (usa quello dal form o fallback agli headers)
    const clientIp = ipAddress || 
                     c.req.header('cf-connecting-ip') || 
                     c.req.header('x-forwarded-for') || 
                     c.req.header('x-real-ip') || 
                     'unknown'
    
    // Salva firma nel DB
    await c.env.DB.prepare(`
      UPDATE contracts 
      SET status = 'SIGNED',
          signature_data = ?,
          signature_ip = ?,
          signature_timestamp = ?,
          signature_user_agent = ?,
          signature_screen_resolution = ?,
          signed_at = ?,
          signature_method = 'inline'
      WHERE id = ?
    `).bind(
      signature,
      clientIp,
      timestamp || new Date().toISOString(),
      userAgent || '',
      screenResolution || '',
      new Date().toISOString(),
      contractId
    ).run()
    
    console.log(`✅ Contratto firmato: ${contractId} da IP ${clientIp}`)
    
    // ✅ SALVATAGGIO PDF + EMAIL con ALLEGATO
    try {
      const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?')
        .bind(contract.leadId).first() as any
      
      if (lead) {
        console.log(`📧 [FIRMA] Generazione e invio PDF contratto firmato`)
        
        // 1. GENERA HTML COMPLETO DEL CONTRATTO (con contenuto_html originale)
        const baseUrl = c.req.url.split('/api/')[0]
        const htmlContent = contract.contenuto_html || `
          <h1>Contratto eCura</h1>
          <p><strong>Cliente:</strong> ${lead.nomeRichiedente} ${lead.cognomeRichiedente}</p>
          <p><strong>Servizio:</strong> ${contract.servizio || 'N/A'}</p>
          <p><strong>Piano:</strong> ${contract.piano || 'N/A'}</p>
        `
        
        // 2. AGGIUNGI FIRMA GRAFICA
        const signatureHtml = signature.startsWith('data:image') ? 
          `<div style="margin-top: 40px; padding: 20px; border-top: 2px solid #e5e7eb;">
            <p style="font-weight: bold; margin-bottom: 10px;">Firma Cliente:</p>
            <img src="${signature}" style="max-width: 300px; height: auto; border: 1px solid #ccc; padding: 5px;" alt="Firma Cliente">
            <p style="font-size: 12px; color: #6b7280; margin-top: 10px;">
              Firmato digitalmente il ${new Date().toLocaleString('it-IT')}<br>
              IP: ${clientIp}
            </p>
          </div>` : 
          `<div style="margin-top: 40px; padding: 20px; border-top: 2px solid #e5e7eb;">
            <p style="font-weight: bold; margin-bottom: 10px;">Firma Cliente: ${signature}</p>
            <p style="font-size: 12px; color: #6b7280; margin-top: 10px;">
              Firmato digitalmente il ${new Date().toLocaleString('it-IT')}<br>
              IP: ${clientIp}
            </p>
          </div>`
        
        const fullHtml = `
        <!DOCTYPE html>
        <html lang="it">
        <head>
          <meta charset="UTF-8">
          <title>Contratto ${contractId} - ${lead.cognomeRichiedente}</title>
          <style>
            body { font-family: Arial, sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
            @media print { body { padding: 0; } }
          </style>
        </head>
        <body>
          ${htmlContent}
          ${signatureHtml}
        </body>
        </html>
        `
        
        // 3. GENERA PDF con Puppeteer
        console.log(`📄 [FIRMA] Generazione PDF con Puppeteer per ${contractId}`)
        let pdfBuffer: Buffer | null = null
        
        try {
          const puppeteer = await import('@cloudflare/puppeteer')
          const browser = await puppeteer.launch(c.env.MYBROWSER)
          const page = await browser.newPage()
          
          await page.setContent(fullHtml, { waitUntil: 'networkidle0' })
          
          pdfBuffer = await page.pdf({
            format: 'A4',
            printBackground: true,
            margin: {
              top: '20mm',
              right: '15mm',
              bottom: '20mm',
              left: '15mm'
            }
          }) as any
          
          await page.close()
          await browser.close()
          
          console.log(`✅ [FIRMA] PDF generato: ${(pdfBuffer.length / 1024).toFixed(2)} KB`)
        } catch (pdfError) {
          console.error('❌ [FIRMA] Errore generazione PDF Puppeteer:', pdfError)
          // Continua senza PDF se Puppeteer fallisce
        }
        
        // 4. SALVA PDF nella cartella /public/contratti/
        if (pdfBuffer) {
          try {
            const dataFirma = new Date().toLocaleDateString('it-IT').replace(/\//g, '.')
            const fileName = `${dataFirma}_Contratto_${lead.cognomeRichiedente}_${lead.nomeRichiedente}_FIRMATO.pdf`
            const filePath = `./public/contratti/${fileName}`
            
            // Salva file su disco usando Bun
            await Bun.write(filePath, pdfBuffer)
            
            console.log(`✅ [FIRMA] PDF salvato in: ${filePath}`)
            
            // Aggiorna record contratto con percorso PDF
            await c.env.DB.prepare(`
              UPDATE contracts 
              SET pdf_url = ? 
              WHERE id = ?
            `).bind(`/contratti/${fileName}`, contractId).run()
            
          } catch (saveError) {
            console.error('❌ [FIRMA] Errore salvataggio PDF su disco:', saveError)
          }
        }
        
        // 5. INVIA EMAIL con PDF ALLEGATO
        // ✅ FIX: usa new EmailService(c.env) invece di getInstance() per avere RESEND_API_KEY
        const EmailServiceModule = (await import('./modules/email-service'))
        const emailService = new EmailServiceModule.EmailService(c.env)
        
        const pdfUrl = `${baseUrl}/api/contratti/${contractId}/pdf-print`
        const pdfBase64 = pdfBuffer ? Buffer.from(pdfBuffer).toString('base64') : null
        
        await emailService.sendEmail({
          to: c.env?.EMAIL_TO || c.env?.EMAIL_TO_INFO || 'info@ecura.it',
          subject: `✅ Contratto Firmato - ${lead.nomeRichiedente} ${lead.cognomeRichiedente}`,
          html: `
            <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
              <h2 style="color: #16a34a;">✅ Contratto Firmato Digitalmente</h2>
              
              <p>Un nuovo contratto è stato firmato digitalmente:</p>
              
              <div style="background: #f0f9ff; border-left: 4px solid #2563eb; padding: 15px; margin: 20px 0;">
                <p style="margin: 5px 0;"><strong>Cliente:</strong> ${lead.nomeRichiedente} ${lead.cognomeRichiedente}</p>
                <p style="margin: 5px 0;"><strong>Email:</strong> ${lead.email}</p>
                <p style="margin: 5px 0;"><strong>Telefono:</strong> ${lead.telefono || 'N/A'}</p>
                <p style="margin: 5px 0;"><strong>Codice Contratto:</strong> ${contractId}</p>
                <p style="margin: 5px 0;"><strong>Data Firma:</strong> ${new Date().toLocaleString('it-IT')}</p>
                <p style="margin: 5px 0;"><strong>IP Cliente:</strong> ${clientIp}</p>
              </div>
              
              <p><strong>📎 Il PDF del contratto firmato è allegato a questa email.</strong></p>
              
              <p><strong>📄 Oppure visualizza online:</strong></p>
              <p style="margin: 20px 0;">
                <a href="${pdfUrl}" 
                   style="display: inline-block; padding: 12px 24px; background: #2563eb; color: white; text-decoration: none; border-radius: 6px; font-weight: bold;">
                  📥 Visualizza Contratto Online
                </a>
              </p>
              
              <p style="margin-top: 30px; padding-top: 20px; border-top: 1px solid #e2e8f0; color: #64748b; font-size: 12px;">
                Questo è un messaggio automatico generato dal sistema TeleMedCare V12.0
              </p>
            </div>
          `,
          text: `Contratto firmato da ${lead.nomeRichiedente} ${lead.cognomeRichiedente}. Visualizza: ${pdfUrl}`,
          attachments: pdfBase64 ? [{
            filename: `Contratto_${lead.cognomeRichiedente}_${contractId}_FIRMATO.pdf`,
            content: pdfBase64,
            contentType: 'application/pdf'
          }] : undefined
        })
        
        console.log(`✅ [FIRMA] Email notifica inviata a info@ecura.it`)
        
        // 6. INVIA COPIA CONTRATTO FIRMATO AL CLIENTE
        if (lead.email) {
          try {
            await emailService.sendEmail({
              to: lead.email,
              subject: `✅ Contratto firmato - ${contract.codice_contratto || contractId}`,
              html: `
                <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
                  <h2 style="color: #16a34a;">✅ Contratto firmato con successo</h2>
                  <p>Gentile <strong>${lead.nomeRichiedente} ${lead.cognomeRichiedente}</strong>,</p>
                  <p>La confermiamo che il suo contratto è stato firmato digitalmente il <strong>${new Date().toLocaleString('it-IT')}</strong>.</p>
                  <div style="background: #f0fdf4; border-left: 4px solid #16a34a; padding: 15px; margin: 20px 0;">
                    <p style="margin: 5px 0;"><strong>Contratto:</strong> ${contract.codice_contratto || contractId}</p>
                    <p style="margin: 5px 0;"><strong>Servizio:</strong> ${contract.servizio || 'N/A'} – Piano ${contract.piano || 'N/A'}</p>
                    <p style="margin: 5px 0;"><strong>Data firma:</strong> ${new Date().toLocaleString('it-IT')}</p>
                  </div>
                  <p>Può visualizzare il contratto firmato in qualsiasi momento al seguente link:</p>
                  <p style="margin: 20px 0;">
                    <a href="${pdfUrl}" style="display: inline-block; padding: 12px 24px; background: #16a34a; color: white; text-decoration: none; border-radius: 6px; font-weight: bold;">
                      📄 Visualizza contratto firmato
                    </a>
                  </p>
                  <p>Per qualsiasi necessità contatti il nostro team: <a href="mailto:info@ecura.it">info@ecura.it</a></p>
                  <p style="color: #6b7280; font-size: 12px; margin-top: 20px; border-top: 1px solid #e5e7eb; padding-top: 15px;">
                    eCura ${contract.servizio || ''}<br>info@ecura.it
                  </p>
                </div>
              `,
              text: `Contratto ${contract.codice_contratto} firmato il ${new Date().toLocaleString('it-IT')}. Visualizza: ${pdfUrl}`
            })
            console.log(`✅ [FIRMA] Email copia contratto inviata al cliente: ${lead.email}`)
          } catch (clientEmailError) {
            console.error('⚠️ [FIRMA] Errore invio email cliente (non critico):', clientEmailError)
          }
        }
      }
    } catch (emailError) {
      console.error('⚠️ Errore invio email notifica firma:', emailError)
      // Non bloccare il processo se l'email fallisce
    }
    
    // ✅ FIX: Auto-CREA proforma dopo firma digitale (senza inviarla — invio = passo manuale con anteprima)
    try {
      console.log(`📊 [FIRMA→PROFORMA] Avvio creazione proforma per contratto ${contractId} (invio manuale)`)
      
      // Recupera lead completo
      const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?')
        .bind(contract.leadId).first() as any
      
      if (lead) {
        console.log(`📝 [FIRMA→PROFORMA] Lead recuperato: ${lead.nomeRichiedente} ${lead.cognomeRichiedente}`)
        
        // ── Flag rinnovo ──────────────────────────────────────────────────────────
        const isRinnovoContract = contract.is_rinnovo == 1 || contract.is_rinnovo === true
        const annoRinnovoContract = contract.anno_rinnovo || 2
        const codiceOriginale = contract.rinnovo_di || ''

        // Genera numero proforma univoco — prefisso RIN per rinnovi
        const year = new Date().getFullYear()
        const month = String(new Date().getMonth() + 1).padStart(2, '0')
        const random = Math.random().toString(36).substring(2, 6).toUpperCase()
        const numeroProforma = isRinnovoContract
          ? `RIN${year}${month}-${random}`
          : `PRF${year}${month}-${random}`
        let proformaIdGenerated: number | null = null  // Sarà popolato dopo INSERT
        
        // Determina prezzi e servizio dal contratto (NON hardcoded!)
        const piano = contract.piano || contract.tipo_contratto || 'BASE'
        // ✅ FIX: Usa servizio reale dal contratto (eCura Premium, eCura Professional, etc)
        const servizio = contract.servizio || contract.service_type || 'eCura Professional'
        
        // Calcola IVA inclusa da prezzo base (usa aliquota dal lead: 4% Legge 104 o 22% standard)
        const ivaRateFirma = lead?.iva_agevolata ? 0.04 : 0.22

        // ✅ FIX CRITICO: Leggi prezzo BASE (IVA esclusa) dal contratto
        // Il contratto contiene prezzo_totale = IVA ESCLUSA
        // Per i rinnovi prezzo_totale = rinnovoBase (già corretto, es. €240)
        let prezzoBase = parseFloat(contract.prezzo_totale || 0)
        let prezzoIvaInclusa = 0
        
        if (prezzoBase > 0) {
          const iva = Math.round(prezzoBase * ivaRateFirma * 100) / 100
          prezzoIvaInclusa = Math.round((prezzoBase + iva) * 100) / 100
          console.log(`📊 [FIRMA→PROFORMA] ${isRinnovoContract ? '🔄 RINNOVO' : 'PRIMO ANNO'}: prezzo base €${prezzoBase}, IVA ${ivaRateFirma*100}% = €${prezzoIvaInclusa}`)
        } else {
          // Fallback: usa prezzi corretti da ecura-pricing
          console.warn(`⚠️ [FIRMA→PROFORMA] Prezzi non trovati nel contratto, uso prezzi standard da ecura-pricing per piano ${piano}`)
          
          const { getPricing } = await import('./modules/ecura-pricing')
          const servizioTipo = servizio.includes('PREMIUM') ? 'PREMIUM' : servizio.includes('PRO') ? 'PRO' : 'FAMILY'
          const pianoTipo = piano === 'AVANZATO' ? 'AVANZATO' : 'BASE'
          const pricing = getPricing(servizioTipo, pianoTipo)
          
          if (pricing) {
            // Per rinnovi usa rinnovoBase, per primo anno usa setupBase
            prezzoBase = isRinnovoContract ? pricing.rinnovoBase : pricing.setupBase
            prezzoIvaInclusa = Math.round((prezzoBase * (1 + ivaRateFirma)) * 100) / 100
            console.log(`✅ [FIRMA→PROFORMA] Prezzi da ecura-pricing (${isRinnovoContract ? 'rinnovo' : 'setup'}): ${servizioTipo} ${pianoTipo} = €${prezzoBase} + IVA ${ivaRateFirma*100}% = €${prezzoIvaInclusa}`)
          } else {
            console.error(`❌ [FIRMA→PROFORMA] getPricing restituito null per ${servizioTipo} ${pianoTipo}, uso fallback hardcoded`)
            if (isRinnovoContract) {
              prezzoBase = piano === 'AVANZATO' ? 600 : 240
            } else {
              prezzoBase = piano === 'AVANZATO' ? 990 : 480
            }
            prezzoIvaInclusa = Math.round((prezzoBase * (1 + ivaRateFirma)) * 100) / 100
          }
        }

        // Scadenza proforma: 15 giorni per rinnovi, 3 giorni per primo anno
        const scadenzaGiorni = isRinnovoContract ? 15 : 3
        const dataScadenzaProforma = new Date(Date.now() + scadenzaGiorni * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
        
        console.log(`📊 [FIRMA→PROFORMA] Servizio: ${servizio}, Piano: ${piano}, Prezzo Base: €${prezzoBase}, IVA Inclusa: €${prezzoIvaInclusa}`)
        
        // Fetch rate di pagamento (se rateizzazione attiva)
        let rateFirmaProforma: Array<{ numero_rata: number; importo: number; data_scadenza: string; status: string }> = []
        if (lead.rateizzazione_attiva) {
          try {
            const rateRowsFirma = await c.env.DB.prepare(
              `SELECT numero_rata, importo, data_scadenza, status FROM rate_pagamento WHERE lead_id = ? ORDER BY numero_rata ASC`
            ).bind(leadId).all()
            rateFirmaProforma = (rateRowsFirma?.results || []) as any[]
            console.log(`📅 [FIRMA→PROFORMA] Rate trovate: ${rateFirmaProforma.length}`)
          } catch (e) {
            console.warn(`⚠️ [FIRMA→PROFORMA] Errore fetch rate:`, e)
          }
        }

        // Prepara dati proforma (proformaId verrà aggiornato dopo INSERT)
        const proformaData = {
          proformaId: '', // Placeholder - sarà aggiornato dopo INSERT con ID auto-generato
          numeroProforma,
          proformaPdfUrl: '',
          tipoServizio: piano,
          servizio: servizio,
          prezzoBase: prezzoBase,
          prezzoIvaInclusa: prezzoIvaInclusa,
          dataScadenza: new Date(Date.now() + scadenzaGiorni * 24 * 60 * 60 * 1000).toISOString(),
          isRinnovo: isRinnovoContract,
          annoRinnovo: annoRinnovoContract,
          codiceOriginale: codiceOriginale,
          riserva_dominio: Boolean(lead.riserva_dominio),  // Clausola Riserva di Dominio (art. 1523 c.c.)
          rateizzazione_attiva: Boolean(lead.rateizzazione_attiva),
          rateizzazione_note: lead.rateizzazione_note || '',
          rate: rateFirmaProforma
        }
        
        console.log(`📊 [FIRMA→PROFORMA] Dati proforma (pre-UPSERT):`, JSON.stringify(proformaData, null, 2))
        
        // ⭐ CALCOLA dati intestatario in base a intestatarioContratto
        // ✅ REGOLA INTESTATARIO: il form ha scelto chi intestare contratto e proforma.
        // intestatarioContratto='assistito' → tutti i campi dall'assistito
        // intestatarioContratto='richiedente' (o default) → tutti i campi dal richiedente
        const intestatario = lead.intestatarioContratto || 'richiedente'
        
        let nomeCliente: string
        let cognomeCliente: string
        let cfCliente: string
        let indirizzoCliente: string
        let cittaCliente: string
        let capCliente: string
        let provinciaCliente: string
        
        if (intestatario === 'assistito') {
          nomeCliente    = lead.nomeAssistito    || ''
          cognomeCliente = lead.cognomeAssistito || ''
          cfCliente      = lead.cfAssistito      || ''
          indirizzoCliente = lead.indirizzoAssistito || ''
          cittaCliente     = lead.cittaAssistito     || ''
          capCliente       = lead.capAssistito       || ''
          provinciaCliente = lead.provinciaAssistito || ''
        } else {
          nomeCliente    = lead.nomeRichiedente    || ''
          cognomeCliente = lead.cognomeRichiedente || ''
          cfCliente      = lead.cfIntestatario || lead.codiceFiscaleIntestatario || ''
          indirizzoCliente = lead.indirizzoIntestatario || ''
          cittaCliente     = lead.cittaIntestatario     || ''
          capCliente       = lead.capIntestatario       || ''
          provinciaCliente = lead.provinciaIntestatario || ''
        }
        console.log(`👤 [FIRMA→PROFORMA] intestatario=${intestatario}: ${nomeCliente} ${cognomeCliente}, CF=${cfCliente}`)
        
        const emailCliente = lead.email || ''
        const telefonoCliente = lead.telefono || ''
        
        console.log(`👤 [FIRMA→PROFORMA] Dati cliente calcolati: ${nomeCliente} ${cognomeCliente}, ${indirizzoCliente}, ${cittaCliente} (${provinciaCliente})`)
        
        // ✅ UPSERT: Controlla se esiste già una proforma per questo contratto
        try {
          console.log(`🔍 [FIRMA→PROFORMA] Controllo se proforma esiste già per contract ${contractId}...`)
          
          const existingProforma = await c.env.DB.prepare(`
            SELECT id, numero_proforma, status 
            FROM proforma 
            WHERE contract_id = ? 
            ORDER BY created_at DESC 
            LIMIT 1
          `).bind(contractId).first() as any
          
          if (existingProforma && existingProforma.id) {
            // ✅ UPDATE: Proforma esiste già, aggiorna i dati
            proformaIdGenerated = existingProforma.id as number
            console.log(`♻️  [FIRMA→PROFORMA] Proforma esistente trovata (ID ${proformaIdGenerated}, numero ${existingProforma.numero_proforma}), eseguo UPDATE...`)
            
            await c.env.DB.prepare(`
              UPDATE proforma SET
                leadId = ?,
                data_emissione = ?,
                data_scadenza = ?,
                cliente_nome = ?,
                cliente_cognome = ?,
                cliente_email = ?,
                cliente_telefono = ?,
                cliente_indirizzo = ?,
                cliente_citta = ?,
                cliente_cap = ?,
                cliente_provincia = ?,
                cliente_codice_fiscale = ?,
                tipo_servizio = ?,
                prezzo_mensile = ?,
                durata_mesi = ?,
                prezzo_totale = ?,
                iva_agevolata = ?,
                is_rinnovo = ?,
                riserva_dominio = ?,
                status = ?,
                updated_at = ?
              WHERE id = ?
            `).bind(
              lead.id,
              new Date().toISOString().split('T')[0],
              dataScadenzaProforma,
              nomeCliente,
              cognomeCliente,
              emailCliente,
              telefonoCliente,
              indirizzoCliente,
              cittaCliente,
              capCliente,
              provinciaCliente,
              cfCliente,
              servizio,
              (prezzoBase / 12).toFixed(2),
              12,
              prezzoBase,
              lead.iva_agevolata ? 1 : 0,
              isRinnovoContract ? 1 : 0,
              lead.riserva_dominio ? 1 : 0,
              'PENDING',  // ✅ FIX: non ancora inviata — invio = passo manuale dopo anteprima
              new Date().toISOString(),
              proformaIdGenerated
            ).run()
            
            console.log(`✅ [FIRMA→PROFORMA] UPDATE proforma completato (ID ${proformaIdGenerated}, status=PENDING)`)
            
          } else {
            // ✅ INSERT: Proforma non esiste, creane una nuova
            console.log(`➕ [FIRMA→PROFORMA] Proforma non esistente, creo nuova proforma...`)
            
            const insertResult = await c.env.DB.prepare(`
              INSERT INTO proforma (
                contract_id, leadId, numero_proforma,
                data_emissione, data_scadenza,
                cliente_nome, cliente_cognome, cliente_email, cliente_telefono,
                cliente_indirizzo, cliente_citta, cliente_cap, cliente_provincia, cliente_codice_fiscale,
                tipo_servizio, prezzo_mensile, durata_mesi, prezzo_totale,
                iva_agevolata, is_rinnovo, riserva_dominio, status, email_sent, created_at, updated_at
              ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).bind(
              contractId || '',
              lead.id,
              numeroProforma,
              new Date().toISOString().split('T')[0],
              dataScadenzaProforma,
              nomeCliente,
              cognomeCliente,
              emailCliente,
              telefonoCliente,
              indirizzoCliente,
              cittaCliente,
              capCliente,
              provinciaCliente,
              cfCliente,
              servizio,
              (prezzoBase / 12).toFixed(2),
              12,
              prezzoBase,
              lead.iva_agevolata ? 1 : 0,
              isRinnovoContract ? 1 : 0,
              lead.riserva_dominio ? 1 : 0,
              'PENDING',  // ✅ FIX: non ancora inviata — invio = passo manuale dopo anteprima
              false,
              new Date().toISOString(),
              new Date().toISOString()
            ).run()
            
            console.log(`✅ [FIRMA→PROFORMA] INSERT proforma eseguito (status=PENDING)`)
            console.log(`🔍 [FIRMA→PROFORMA] insertResult.meta:`, JSON.stringify(insertResult.meta || {}))
            
            // Recupera l'ID auto-generato
            // ⚠️ WORKAROUND: D1 potrebbe non restituire last_row_id, quindi facciamo una SELECT
            if (insertResult.meta && insertResult.meta.last_row_id) {
              proformaIdGenerated = insertResult.meta.last_row_id as number
              console.log(`✅ [FIRMA→PROFORMA] ID recuperato da last_row_id: ${proformaIdGenerated}`)
            } else {
              console.warn(`⚠️ [FIRMA→PROFORMA] last_row_id non disponibile, eseguo SELECT per recuperare ID...`)
              
              // Fallback: recupera ID con SELECT usando numero_proforma (univoco)
              const proformaRecord = await c.env.DB.prepare(`
                SELECT id FROM proforma WHERE numero_proforma = ? ORDER BY created_at DESC LIMIT 1
              `).bind(numeroProforma).first() as any
              
              if (proformaRecord && proformaRecord.id) {
                proformaIdGenerated = proformaRecord.id as number
                console.log(`✅ [FIRMA→PROFORMA] ID recuperato da SELECT: ${proformaIdGenerated}`)
              } else {
                console.error(`❌ [FIRMA→PROFORMA] Impossibile recuperare ID proforma per ${numeroProforma}`)
              }
            }
          }
        } catch (dbError) {
          console.error(`❌ [FIRMA→PROFORMA] Errore UPSERT proforma nel DB:`, dbError)
          // Continua comunque con l'invio email
        }
        
        // ✅ FIX: Salva proforma_rinnovo_id sul contratto — NON inviare email (invio = manuale con anteprima)
        if (proformaIdGenerated) {
          // Collega la proforma al contratto rinnovo
          await c.env.DB.prepare(
            `UPDATE contracts SET proforma_rinnovo_id = ?, updated_at = ? WHERE id = ?`
          ).bind(proformaIdGenerated, new Date().toISOString(), contractId).run()
          console.log(`✅ [FIRMA→PROFORMA] Proforma ${numeroProforma} (ID ${proformaIdGenerated}) creata e collegata al contratto ${contractId}`)
          console.log(`📤 [FIRMA→PROFORMA] Email NON inviata — l'operatore invierà dopo anteprima (pulsante 📤 step=5)`)
        } else {
          console.error(`❌ [FIRMA→PROFORMA] Proforma non salvata (ID mancante)`)
        }
      } else {
        console.warn(`⚠️ [FIRMA→PROFORMA] Lead non trovato - proforma NON inviata`)
      }
    } catch (proformaError) {
      // Non blocchiamo la risposta se la proforma fallisce
      console.error(`⚠️ [FIRMA→PROFORMA] Errore trigger proforma (firma salvata comunque):`, proformaError)
      console.error(`⚠️ [FIRMA→PROFORMA] Stack:`, (proformaError as Error)?.stack)
    }
    
    // 🔥 CRITICAL FIX: Headers espliciti per prevenire redirect
    // Assicura che la risposta sia SEMPRE JSON, MAI redirect
    console.log('🔍 [DEBUG BACKEND] Sto per ritornare JSON response (NO redirect, NO Location header)')
    
    return c.json({ 
      success: true,
      message: 'Contratto firmato con successo',
      contractId: contractId
    }, 200, {
      'Content-Type': 'application/json',
      'Cache-Control': 'no-cache, no-store, must-revalidate'
    })
    
  } catch (error) {
    console.error('❌ Errore salvataggio firma:', error)
    return c.json({ 
      success: false, 
      error: 'Errore durante il salvataggio della firma',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

