// GET /api/contracts - Lista contratti (opzionale filtro per leadId)
app.get('/api/contracts', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    const leadId = c.req.query('leadId')
    
    let query = 'SELECT * FROM contracts'
    const bindings = []
    
    if (leadId) {
      query += ' WHERE leadId = ?'
      bindings.push(leadId)
    }
    
    query += ' ORDER BY created_at DESC LIMIT 50'
    
    const stmt = c.env.DB.prepare(query)
    const result = bindings.length > 0 
      ? await stmt.bind(...bindings).all() 
      : await stmt.all()
    
    console.log(`📋 Contratti trovati: ${result.results?.length || 0}`)
    
    return c.json({ 
      success: true, 
      contracts: result.results || [] 
    })
  } catch (error) {
    console.error('❌ Errore recupero contratti:', error)
    return c.json({ 
      success: false, 
      error: 'Errore recupero contratti',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// GET /api/contracts/:id - Dettaglio singolo contratto
app.get('/api/contracts/:id', async (c) => {
  try {
    const contractId = c.req.param('id')
    
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    const contract = await c.env.DB.prepare('SELECT * FROM contracts WHERE id = ?')
      .bind(contractId).first() as any
    
    if (!contract) {
      return c.json({ success: false, error: 'Contratto non trovato' }, 404)
    }
    
    // Prendi i dati del lead se disponibili
    // ✅ FIX: Usa dati INTESTATARIO (non richiedente) per il contratto
    let nomeCliente = 'Cliente'
    let cognomeCliente = ''
    let emailCliente = ''
    
    if (contract.leadId) {
      try {
        const lead = await c.env.DB.prepare(`
          SELECT nomeRichiedente, cognomeRichiedente, email
          FROM leads WHERE id = ?
        `).bind(contract.leadId).first() as any
        
        if (lead) {
          nomeCliente = lead.nomeRichiedente || 'Cliente'
          cognomeCliente = lead.cognomeRichiedente || ''
          emailCliente = lead.email || ''
        }
      } catch (leadError) {
        console.warn('⚠️  Errore caricamento lead:', leadError)
      }
    }
    
    // ✅ REGOLA UNIVERSALE: prezzo_totale nel DB = IVA ESCLUSA
    const prezzoBase = parseFloat(contract.prezzo_totale || 0)
    // ✅ FIX: recupera iva_agevolata dal lead per calcolo corretto
    let ivaAgevolataContratto = false
    if (contract.leadId) {
      try {
        const leadIva = await c.env.DB.prepare('SELECT iva_agevolata FROM leads WHERE id = ?').bind(contract.leadId).first() as any
        ivaAgevolataContratto = !!(leadIva?.iva_agevolata)
      } catch {}
    }
    const ivaRateContratto = ivaAgevolataContratto ? 0.04 : 0.22
    const iva = Math.round(prezzoBase * ivaRateContratto * 100) / 100
    const totaleIvaInclusa = Math.round((prezzoBase + iva) * 100) / 100
    
    // Mappa schema DB esistente a formato API
    return c.json({
      success: true,
      id: contract.id,
      leadId: contract.leadId,
      nomeCliente: nomeCliente,
      cognomeCliente: cognomeCliente,
      emailCliente: emailCliente,
      contractCode: contract.codice_contratto || contract.id,
      contractHtml: contract.contenuto_html || '',
      servizio: contract.servizio || 'eCura PRO',
      piano: contract.tipo_contratto || contract.piano || 'BASE',
      dispositivo: (contract.servizio?.includes('PREMIUM') ? 'SiDLY Vital Care' : 'SiDLY Care PRO'),
      prezzo: `€${prezzoBase.toFixed(2)} + IVA ${ivaAgevolataContratto ? '4%' : '22%'} (€${totaleIvaInclusa.toFixed(2)}) / anno`,
      status: contract.status || 'PENDING'
    })
  } catch (error) {
    console.error('❌ Errore recupero contratto:', error)
    return c.json({ 
      success: false, 
      error: 'Errore recupero contratto',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// GET /api/contracts/:id/pdf - Scarica contratto firmato come HTML
app.get('/api/contracts/:id/pdf', async (c) => {
  try {
    const contractId = c.req.param('id')
    
    if (!c.env?.DB) {
      return c.html('<h1>Errore: Database non configurato</h1>', 500)
    }
    
    const contract = await c.env.DB.prepare('SELECT * FROM contracts WHERE id = ?')
      .bind(contractId).first() as any
    
    if (!contract) {
      return c.html('<h1>Errore: Contratto non trovato</h1>', 404)
    }
    
    if (contract.status !== 'SIGNED') {
      return c.html('<h1>Errore: Contratto non ancora firmato</h1>', 400)
    }
    
    // Recupera HTML del contratto
    let contractHtml = contract.contenuto_html || ''
    
    // Se esiste firma, aggiungi sezione firme
    if (contract.signature_data) {
      const signatureSection = `
        <div style="margin-top: 60px; page-break-inside: avoid;">
          <h2 style="text-align: center; margin-bottom: 40px;">Firme</h2>
          <div style="display: flex; justify-content: space-between; gap: 40px;">
            <div style="flex: 1; text-align: center;">
              <p style="font-weight: bold; margin-bottom: 20px;">Il Cliente</p>
              ${contract.signature_data.startsWith('data:image') ? `<img src="${contract.signature_data}" style="max-width: 300px; border: 1px solid #ccc; padding: 10px;">` : `<p style="font-style: italic;">${contract.signature_data}</p>`}
              <p style="margin-top: 10px; font-size: 12px; color: #666;">
                Firma digitale apposta il ${new Date(contract.signature_timestamp || contract.signed_at || Date.now()).toLocaleString('it-IT')}<br>
                IP: ${contract.signature_ip || 'N/A'}
              </p>
            </div>
            <div style="flex: 1; text-align: center;">
              <p style="font-weight: bold; margin-bottom: 20px;">Per Medica GB S.r.l.</p>
              <p style="margin-top: 80px; font-size: 14px;">
                <strong>Stefania Rocca</strong><br>
                Amministratore Delegato<br>
                Medica GB S.r.l.
              </p>
              <p style="margin-top: 10px; font-size: 12px; color: #666;">
                Firma depositata presso sede legale<br>
                Corso Giuseppe Garibaldi, 34 – 20121 Milano
              </p>
            </div>
          </div>
        </div>
      `
      
      // Inserisci firma prima del tag </body>
      contractHtml = contractHtml.replace('</body>', signatureSection + '</body>')
    }
    
    // Restituisci HTML con header per download
    return c.html(contractHtml, 200, {
      'Content-Disposition': `attachment; filename="Contratto_Firmato_${contract.codice_contratto || contractId}.html"`,
      'Content-Type': 'text/html; charset=utf-8'
    })
    
  } catch (error) {
    console.error('❌ Errore download contratto:', error)
    return c.html(`<h1>Errore: ${error instanceof Error ? error.message : String(error)}</h1>`, 500)
  }
})

// DELETE /api/contracts/:id - Elimina contratto
app.delete('/api/contracts/:id', async (c) => {
  try {
    const contractId = c.req.param('id')
    
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    console.log(`🗑️ [DELETE CONTRACT] Richiesta eliminazione contratto: ${contractId}`)
    
    // Verifica che il contratto esista
    const contract = await c.env.DB.prepare('SELECT id, leadId, codice_contratto FROM contracts WHERE id = ?')
      .bind(contractId).first() as any
    
    if (!contract) {
      console.log(`⚠️ [DELETE CONTRACT] Contratto ${contractId} non trovato`)
      return c.json({ 
        success: false, 
        error: 'Contratto non trovato' 
      }, 404)
    }
    
    console.log(`📋 [DELETE CONTRACT] Trovato contratto: ${contract.codice_contratto} per lead ${contract.leadId}`)
    
    // Elimina il contratto
    await c.env.DB.prepare('DELETE FROM contracts WHERE id = ?')
      .bind(contractId).run()
    
    console.log(`✅ [DELETE CONTRACT] Contratto ${contractId} eliminato con successo`)
    
    return c.json({ 
      success: true,
      message: `Contratto ${contract.codice_contratto} eliminato con successo`,
      deletedId: contractId
    })
    
  } catch (error) {
    console.error('❌ Errore eliminazione contratto:', error)
    return c.json({ 
      success: false, 
      error: 'Errore durante l\'eliminazione del contratto',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// POST /api/contracts/bulk-manual - Inserimento contratti manuali per lead esistenti
app.post('/api/contracts/bulk-manual', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    const { contracts } = await c.req.json<{ contracts: any[] }>()
    
    if (!Array.isArray(contracts) || contracts.length === 0) {
      return c.json({ success: false, error: 'Array contracts vuoto o non valido' }, 400)
    }

    console.log(`📝 [BULK MANUAL CONTRACTS] Inserimento ${contracts.length} contratti manuali per lead esistenti...`)
    
    const results = []
    
    for (const contractData of contracts) {
      try {
        // 1. Recupera il lead esistente (NO creazione)
        const lead = await c.env.DB.prepare(`
          SELECT * FROM leads 
          WHERE UPPER(cognomeRichiedente) = UPPER(?) 
            AND UPPER(nomeRichiedente) = UPPER(?)
          LIMIT 1
        `).bind(contractData.cognome, contractData.nome).first() as any

        if (!lead) {
          throw new Error(`❌ Lead NON TROVATO per ${contractData.nome} ${contractData.cognome}. Il lead deve esistere prima di creare il contratto.`)
        }
        
        console.log(`✅ Lead trovato: ${lead.id} - ${lead.nomeRichiedente} ${lead.cognomeRichiedente}`)

        // 2. Verifica se esiste già un contratto per questo lead
        const existingContract = await c.env.DB.prepare(`
          SELECT id, codice_contratto, status FROM contracts 
          WHERE leadId = ?
          LIMIT 1
        `).bind(lead.id).first() as any

        if (existingContract) {
          console.log(`⚠️ Contratto già esistente per ${contractData.nome} ${contractData.cognome}: ${existingContract.codice_contratto}`)
          results.push({
            success: false,
            error: `Contratto già esistente: ${existingContract.codice_contratto} (status: ${existingContract.status})`,
            leadId: lead.id,
            existingContractId: existingContract.id,
            existingContractCode: existingContract.codice_contratto,
            cliente: `${contractData.nome} ${contractData.cognome}`
          })
          continue // Salta questo contratto e passa al prossimo
        }

        // 3. Crea il contratto
        // Formato corretto: codice = CTR-COGNOME-ANNO, id = CONTRACT_CTR-COGNOME-ANNO_TIMESTAMP
        const timestamp = Date.now()
        const anno = new Date(contractData.dataFirma).getFullYear()
        const contractCode = `CTR-${contractData.cognome.toUpperCase()}-${anno}`
        const contractId = `CONTRACT_CTR-${contractData.cognome.toUpperCase()}-${anno}_${timestamp}` // ID univoco
        
        // Calcola prezzo mensile (totale / 12 mesi)
        const prezzoTotale = contractData.prezzoTotale || 585.60
        const prezzoMensile = (prezzoTotale / 12).toFixed(2)
        
        // Calcola data scadenza (1 anno dalla firma - 1 giorno)
        const dataFirma = new Date(contractData.dataFirma)
        const dataScadenza = new Date(dataFirma)
        dataScadenza.setFullYear(dataScadenza.getFullYear() + 1)
        dataScadenza.setDate(dataScadenza.getDate() - 1)
        
        const piano = contractData.piano || 'BASE'
        const templateName = `Template_Contratto_${piano}_TeleMedCare`

        // URL del PDF (se fornito)
        const pdfUrl = contractData.pdfUrl || ''
        
        await c.env.DB.prepare(`
          INSERT INTO contracts (
            id, leadId, codice_contratto, tipo_contratto, template_utilizzato,
            contenuto_html, servizio, piano,
            prezzo_mensile, durata_mesi, prezzo_totale, 
            data_scadenza, status, pdf_url,
            created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 12, ?, ?, 'SIGNED', ?, datetime('now'), datetime('now'))
        `).bind(
          contractId, // ID = codice_contratto
          lead.id,
          contractCode,
          piano, // tipo_contratto = piano (BASE/AVANZATO)
          templateName, // Template_Contratto_BASE_TeleMedCare
          '', // contenuto_html vuoto per ora
          contractData.servizio || 'eCura PRO',
          piano,
          parseFloat(prezzoMensile),
          prezzoTotale,
          dataScadenza.toISOString().split('T')[0], // data_scadenza in formato YYYY-MM-DD
          pdfUrl // PDF del contratto
        ).run()

        console.log(`✅ Contratto inserito: ${contractCode} per ${contractData.nome} ${contractData.cognome}`)
        console.log(`   Data firma: ${contractData.dataFirma} → Scadenza: ${dataScadenza.toISOString().split('T')[0]}`)
        
        results.push({
          success: true,
          leadId: lead.id,
          contractId,
          contractCode,
          cliente: `${contractData.nome} ${contractData.cognome}`,
          dataFirma: contractData.dataFirma,
          dataScadenza: dataScadenza.toISOString().split('T')[0]
        })
        
      } catch (error) {
        console.error(`❌ Errore inserimento contratto per ${contractData.nome} ${contractData.cognome}:`, error)
        results.push({
          success: false,
          error: error instanceof Error ? error.message : String(error),
          cliente: `${contractData.nome} ${contractData.cognome}`
        })
      }
    }

    const successCount = results.filter(r => r.success).length
    
    return c.json({
      success: true,
      message: `Inseriti ${successCount}/${contracts.length} contratti`,
      results
    })

  } catch (error) {
    console.error('❌ Errore bulk insert contratti manuali:', error)
    return c.json({
      success: false,
      error: 'Errore durante l\'inserimento dei contratti',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// POST /api/contracts/update-dates - Aggiorna date contratti esistenti
app.post('/api/contracts/update-dates', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    const { contracts } = await c.req.json<{ contracts: any[] }>()
    
    if (!Array.isArray(contracts) || contracts.length === 0) {
      return c.json({ success: false, error: 'Array contracts vuoto o non valido' }, 400)
    }

    console.log(`📅 [UPDATE DATES] Aggiornamento date per ${contracts.length} contratti...`)
    
    const results = []
    
    for (const contractData of contracts) {
      try {
        // Cerca il lead (assistito o richiedente)
        let lead = null
        
        // Caso 1: cerca per nome assistito (es: Balzarotti ha richiedente Magri)
        if (contractData.richiedente_nome && contractData.richiedente_cognome) {
          lead = await c.env.DB.prepare(`
            SELECT * FROM leads 
            WHERE UPPER(nomeRichiedente) = UPPER(?) 
              AND UPPER(cognomeRichiedente) = UPPER(?)
            LIMIT 1
          `).bind(contractData.richiedente_nome, contractData.richiedente_cognome).first() as any
          
          if (lead) {
            console.log(`✅ Lead trovato tramite richiedente: ${contractData.richiedente_nome} ${contractData.richiedente_cognome} per assistito ${contractData.nome} ${contractData.cognome}`)
          }
        }
        
        // Caso 2: cerca per nome/cognome diretto
        if (!lead) {
          lead = await c.env.DB.prepare(`
            SELECT * FROM leads 
            WHERE (UPPER(nomeRichiedente) = UPPER(?) AND UPPER(cognomeRichiedente) = UPPER(?))
               OR (UPPER(nomeAssistito) = UPPER(?) AND UPPER(cognomeAssistito) = UPPER(?))
            LIMIT 1
          `).bind(
            contractData.nome, contractData.cognome,
            contractData.nome, contractData.cognome
          ).first() as any
        }

        if (!lead) {
          throw new Error(`❌ Lead NON TROVATO per ${contractData.nome} ${contractData.cognome}`)
        }
        
        console.log(`📋 Lead trovato: ${lead.id} - ${lead.nomeRichiedente} ${lead.cognomeRichiedente}`)

        // Cerca il contratto per questo lead
        const contract = await c.env.DB.prepare(`
          SELECT * FROM contracts 
          WHERE leadId = ?
          LIMIT 1
        `).bind(lead.id).first() as any

        if (!contract) {
          throw new Error(`❌ Contratto NON TROVATO per lead ${lead.id}`)
        }

        console.log(`📄 Contratto trovato: ${contract.codice_contratto}`)

        // Aggiorna data_scadenza (campo esistente nel DB)
        await c.env.DB.prepare(`
          UPDATE contracts 
          SET data_scadenza = ?,
              updated_at = datetime('now')
          WHERE id = ?
        `).bind(
          contractData.data_scadenza,
          contract.id
        ).run()

        console.log(`✅ Data scadenza aggiornata per contratto ${contract.codice_contratto}: ${contractData.data_scadenza}`)
        console.log(`   Nota: data_firma non salvata (campo non presente in DB, usa created_at)`)
        
        results.push({
          success: true,
          leadId: lead.id,
          contractId: contract.id,
          contractCode: contract.codice_contratto,
          cliente: `${contractData.nome} ${contractData.cognome}`,
          dataScadenza: contractData.data_scadenza,
          note: `Data scadenza aggiornata. Data firma: ${contractData.data_firma} (non salvata, usa created_at)`
        })
        
      } catch (error) {
        console.error(`❌ Errore aggiornamento date per ${contractData.nome} ${contractData.cognome}:`, error)
        results.push({
          success: false,
          error: error instanceof Error ? error.message : String(error),
          cliente: `${contractData.nome} ${contractData.cognome}`
        })
      }
    }

    const successCount = results.filter(r => r.success).length
    
    return c.json({
      success: true,
      message: `Aggiornati ${successCount}/${contracts.length} contratti`,
      results
    })

  } catch (error) {
    console.error('❌ Errore bulk update date contratti:', error)
    return c.json({
      success: false,
      error: 'Errore durante l\'aggiornamento delle date',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// POST /api/contracts/fix-manual-3 - Aggiorna i 3 contratti esistenti (NO cancellazione!)
app.post('/api/contracts/fix-manual-3', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    console.log('🔧 [FIX MANUAL 3] Aggiornamento 3 contratti esistenti (senza cancellazione)...')

    // Dati corretti dei 3 contratti
    const correctContracts = [
      {
        nome: 'Alberto',
        cognome: 'Locatelli',
        codiceContratto: 'CTR-LOCATELLI-2026',
        dataFirma: '2026-02-03', // 03/02/2026
        dataScadenza: '2027-02-02', // +12 mesi -1 giorno
        prezzoTotale: 585.60,
        prezzoMensile: 48.80,
        pdfUrl: '/contratti/03.02.2026_signor Locatelli_BASE_SIDLY VITAL CARE.pdf'
      },
      {
        nome: 'Francesco',
        cognome: 'Pepe',
        codiceContratto: 'CTR-PEPE-2026',
        dataFirma: '2026-01-27', // 27/01/2026
        dataScadenza: '2027-01-26', // +12 mesi -1 giorno
        prezzoTotale: 585.60,
        prezzoMensile: 48.80,
        pdfUrl: '/contratti/27.01.2026_Pepe Francesco Contratto.pdf'
      },
      {
        nome: 'Claudio',
        cognome: 'Macchi',
        codiceContratto: 'CTR-MACCHI-2026',
        dataFirma: '2026-02-01', // 01/02/2026
        dataScadenza: '2027-01-31', // +12 mesi -1 giorno
        prezzoTotale: 585.60,
        prezzoMensile: 48.80,
        pdfUrl: '/contratti/Documento x Claudio Macchi.pdf'
      }
    ]

    const results = []

    for (const contractData of correctContracts) {
      try {
        // 1. Trova il lead esistente
        const lead = await c.env.DB.prepare(`
          SELECT * FROM leads 
          WHERE UPPER(cognomeRichiedente) = UPPER(?) 
            AND UPPER(nomeRichiedente) = UPPER(?)
          LIMIT 1
        `).bind(contractData.cognome, contractData.nome).first() as any

        if (!lead) {
          throw new Error(`❌ Lead NON TROVATO per ${contractData.nome} ${contractData.cognome}`)
        }

        // 2. Verifica se esiste già un contratto per questo lead
        const existingContract = await c.env.DB.prepare(`
          SELECT id, codice_contratto, status, data_scadenza, pdf_url FROM contracts 
          WHERE leadId = ?
          ORDER BY created_at DESC
          LIMIT 1
        `).bind(lead.id).first() as any

        if (!existingContract) {
          throw new Error(`❌ Nessun contratto trovato per ${contractData.nome} ${contractData.cognome}`)
        }

        // 3. Verifica se il codice contratto è già corretto
        if (existingContract.codice_contratto === contractData.codiceContratto) {
          console.log(`✅ Contratto già corretto per ${contractData.nome} ${contractData.cognome}: ${contractData.codiceContratto}`)
          
          // Aggiorna solo PDF e date se necessario
          await c.env.DB.prepare(`
            UPDATE contracts
            SET 
              data_scadenza = ?,
              pdf_url = ?,
              prezzo_totale = ?,
              prezzo_mensile = ?,
              updated_at = datetime('now')
            WHERE id = ?
          `).bind(
            contractData.dataScadenza,
            contractData.pdfUrl,
            contractData.prezzoTotale,
            contractData.prezzoMensile,
            existingContract.id
          ).run()

          results.push({
            success: true,
            action: 'UPDATE_MINOR',
            contractId: existingContract.id,
            contractCode: contractData.codiceContratto,
            cliente: `${contractData.nome} ${contractData.cognome}`,
            dataScadenza: contractData.dataScadenza,
            pdfUrl: contractData.pdfUrl,
            note: `Codice già corretto, aggiornati solo PDF/date`
          })
          continue
        }

        // 4. Verifica se esiste un ALTRO contratto con il codice corretto (duplicato!)
        const duplicateContract = await c.env.DB.prepare(`
          SELECT id, codice_contratto FROM contracts 
          WHERE codice_contratto = ? AND leadId != ?
          LIMIT 1
        `).bind(contractData.codiceContratto, lead.id).first() as any

        if (duplicateContract) {
          throw new Error(`❌ DUPLICATO RILEVATO: Codice ${contractData.codiceContratto} già usato da contratto ${duplicateContract.id} (lead diverso!)`)
        }

        // 5. Aggiorna il contratto esistente con il nuovo codice
        console.log(`✏️ Aggiorno contratto: ${existingContract.codice_contratto} → ${contractData.codiceContratto}`)
        
        await c.env.DB.prepare(`
          UPDATE contracts
          SET 
            codice_contratto = ?,
            data_scadenza = ?,
            prezzo_totale = ?,
            prezzo_mensile = ?,
            pdf_url = ?,
            updated_at = datetime('now')
          WHERE id = ?
        `).bind(
          contractData.codiceContratto,
          contractData.dataScadenza,
          contractData.prezzoTotale,
          contractData.prezzoMensile,
          contractData.pdfUrl,
          existingContract.id
        ).run()

        results.push({
          success: true,
          action: 'UPDATE',
          contractId: existingContract.id,
          contractCode: contractData.codiceContratto,
          oldCode: existingContract.codice_contratto,
          cliente: `${contractData.nome} ${contractData.cognome}`,
          dataScadenza: contractData.dataScadenza,
          pdfUrl: contractData.pdfUrl,
          note: `Aggiornato da ${existingContract.codice_contratto} a ${contractData.codiceContratto}`
        })

      } catch (error) {
        console.error(`❌ Errore per ${contractData.nome} ${contractData.cognome}:`, error)
        results.push({
          success: false,
          error: error instanceof Error ? error.message : String(error),
          cliente: `${contractData.nome} ${contractData.cognome}`
        })
      }
    }

    const successCount = results.filter(r => r.success).length

    return c.json({
      success: successCount === 3,
      message: `✅ Aggiornati ${successCount}/3 contratti (senza perdita dati)`,
      results
    })

  } catch (error) {
    console.error('❌ Errore fix manual 3 contratti:', error)
    return c.json({
      success: false,
      error: 'Errore durante l\'aggiornamento dei contratti',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

