// POST /api/db/migrate - Esegue migrazioni database
app.post('/api/db/migrate', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    console.log('🔧 Esecuzione migrazioni database...')

    // Migrazione 1: Crea tabella assistiti
    try {
      await c.env.DB.prepare(`
        CREATE TABLE IF NOT EXISTS assistiti (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          codice TEXT UNIQUE NOT NULL,
          nome TEXT NOT NULL,
          email TEXT,
          telefono TEXT,
          imei TEXT UNIQUE,
          status TEXT DEFAULT 'ATTIVO',
          lead_id TEXT,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `).run()
      console.log('✅ Tabella assistiti creata')
    } catch (error) {
      console.log('ℹ️ Tabella assistiti già esistente')
    }

    // Migrazione 1.5: Aggiungi colonne nome_assistito, cognome_assistito, nome_caregiver, cognome_caregiver
    const assistitiColumns = [
      { name: 'nome_assistito', type: 'TEXT' },
      { name: 'cognome_assistito', type: 'TEXT' },
      { name: 'nome_caregiver', type: 'TEXT' },
      { name: 'cognome_caregiver', type: 'TEXT' },
      { name: 'parentela_caregiver', type: 'TEXT' }
    ]

    for (const col of assistitiColumns) {
      try {
        await c.env.DB.prepare(`
          ALTER TABLE assistiti ADD COLUMN ${col.name} ${col.type}
        `).run()
        console.log(`✅ Colonna ${col.name} aggiunta a assistiti`)
      } catch (error) {
        console.log(`ℹ️ Colonna ${col.name} già esistente in assistiti`)
      }
    }

    // Migra dati esistenti da 'nome' a 'nome_assistito' e 'cognome_assistito'
    try {
      await c.env.DB.prepare(`
        UPDATE assistiti 
        SET nome_assistito = CASE 
          WHEN nome_assistito IS NULL AND nome LIKE '% %' 
          THEN substr(nome, 1, instr(nome, ' ') - 1)
          WHEN nome_assistito IS NULL 
          THEN nome
          ELSE nome_assistito
        END,
        cognome_assistito = CASE 
          WHEN cognome_assistito IS NULL AND nome LIKE '% %' 
          THEN substr(nome, instr(nome, ' ') + 1)
          ELSE cognome_assistito
        END
        WHERE nome_assistito IS NULL OR cognome_assistito IS NULL
      `).run()
      console.log('✅ Dati migrati da nome a nome_assistito/cognome_assistito')
    } catch (error) {
      console.log('ℹ️ Migrazione dati assistiti già effettuata')
    }

    // Migrazione 2: Aggiungi colonna imei_dispositivo a contracts
    try {
      await c.env.DB.prepare(`
        ALTER TABLE contracts ADD COLUMN imei_dispositivo TEXT
      `).run()
      console.log('✅ Colonna imei_dispositivo aggiunta a contracts')
    } catch (error) {
      console.log('ℹ️ Colonna imei_dispositivo già esistente')
    }

    // Migrazione 3: Aggiungi altre colonne mancanti a contracts
    const columnsToAdd = [
      { name: 'codice_contratto', type: 'TEXT' },
      { name: 'tipo_contratto', type: 'TEXT' },
      { name: 'status', type: 'TEXT DEFAULT "DRAFT"' },
      { name: 'prezzo_totale', type: 'INTEGER' },
      { name: 'created_at', type: 'DATETIME DEFAULT CURRENT_TIMESTAMP' }
    ]

    for (const col of columnsToAdd) {
      try {
        await c.env.DB.prepare(`
          ALTER TABLE contracts ADD COLUMN ${col.name} ${col.type}
        `).run()
        console.log(`✅ Colonna ${col.name} aggiunta a contracts`)
      } catch (error) {
        console.log(`ℹ️ Colonna ${col.name} già esistente`)
      }
    }

    // Migrazione 4: Aggiungi colonna piano a contracts se non esiste
    try {
      await c.env.DB.prepare(`
        ALTER TABLE contracts ADD COLUMN piano TEXT
      `).run()
      console.log('✅ Colonna piano aggiunta a contracts')
    } catch (error) {
      console.log('ℹ️ Colonna piano già esistente in contracts')
    }

    // Migrazione 5: Aggiorna piano basandosi su prezzo_totale
    try {
      await c.env.DB.prepare(`
        UPDATE contracts 
        SET piano = CASE 
          WHEN prezzo_totale >= 800 THEN 'AVANZATO'
          ELSE 'BASE'
        END
        WHERE piano IS NULL AND prezzo_totale IS NOT NULL
      `).run()
      console.log('✅ Campo piano aggiornato nei contratti')
    } catch (error) {
      console.log('⚠️ Errore aggiornamento piano contratti:', error)
    }

    // Migrazione CRITICA: Drop tabella devices obsoleta (ora si chiama dispositivi)
    const migrations = [
      'Tabella assistiti creata',
      'Colonna imei_dispositivo aggiunta a contracts',
      'Colonne aggiuntive verificate in contracts',
      'Colonna piano aggiunta e aggiornata in contracts'
    ]
    
    try {
      // Verifica se esiste la tabella devices
      const devicesExists = await c.env.DB.prepare(`
        SELECT name FROM sqlite_master WHERE type='table' AND name='devices'
      `).first()
      
      if (devicesExists) {
        console.log('⚠️ Tabella devices obsoleta trovata, rimozione in corso...')
        
        // Drop foreign keys che puntano a devices (la tabella configurations)
        // In SQLite non si possono droppare FK direttamente, devo ricreare la tabella
        // Per ora droppo solo la tabella devices - i FK falliranno ma dispositivi funziona
        
        await c.env.DB.prepare(`DROP TABLE IF EXISTS devices`).run()
        console.log('✅ Tabella devices obsoleta rimossa')
        migrations.push('Tabella devices obsoleta rimossa')
        
        // Drop indici obsoleti
        try {
          await c.env.DB.prepare(`DROP INDEX IF EXISTS idx_devices_imei`).run()
          await c.env.DB.prepare(`DROP INDEX IF EXISTS idx_devices_leadId`).run()
          await c.env.DB.prepare(`DROP INDEX IF EXISTS idx_devices_status`).run()
          console.log('✅ Indici devices obsoleti rimossi')
          migrations.push('Indici devices obsoleti rimossi')
        } catch (e) {
          console.log('ℹ️ Indici devices già rimossi')
        }
        
        // Drop trigger obsoleto
        try {
          await c.env.DB.prepare(`DROP TRIGGER IF EXISTS devices_updated_at`).run()
          console.log('✅ Trigger devices_updated_at obsoleto rimosso')
          migrations.push('Trigger devices_updated_at rimosso')
        } catch (e) {
          console.log('ℹ️ Trigger devices_updated_at già rimosso')
        }
      } else {
        console.log('✅ Tabella devices non esiste (già migrata a dispositivi)')
        migrations.push('Tabella devices non trovata (già dispositivi)')
      }
    } catch (error) {
      console.error('❌ Errore rimozione devices:', error)
      migrations.push(`Errore rimozione devices: ${error}`)
    }

    // Migrazione CRITICA: Ricrea configurations senza FK a devices
    try {
      console.log('🔧 Verifica tabella configurations...')
      
      // Verifica se configurations ha FK a devices
      const configExists = await c.env.DB.prepare(`
        SELECT name FROM sqlite_master WHERE type='table' AND name='configurations'
      `).first()
      
      if (configExists) {
        console.log('⚠️ Ricreazione configurations senza FK a devices...')
        
        // Backup dati
        await c.env.DB.prepare(`
          CREATE TABLE IF NOT EXISTS configurations_backup AS SELECT * FROM configurations
        `).run()
        console.log('✅ Backup configurations creato')
        
        // Drop vecchia configurations
        await c.env.DB.prepare(`DROP TABLE IF EXISTS configurations`).run()
        console.log('✅ Vecchia configurations droppata')
        
        // Ricrea con TUTTE le colonne (vecchie + nuove aggiunte)
        await c.env.DB.prepare(`
          CREATE TABLE configurations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            leadId TEXT NOT NULL,
            device_id INTEGER,
            contract_id TEXT,
            nome_assistito TEXT,
            cognome_assistito TEXT,
            data_nascita TEXT,
            eta TEXT,
            peso REAL,
            altezza REAL,
            telefono TEXT,
            email TEXT,
            indirizzo TEXT,
            contatto1_nome TEXT,
            contatto1_cognome TEXT,
            contatto1_telefono TEXT,
            contatto1_email TEXT,
            contatto2_nome TEXT,
            contatto2_cognome TEXT,
            contatto2_telefono TEXT,
            contatto2_email TEXT,
            contatto3_nome TEXT,
            contatto3_cognome TEXT,
            contatto3_telefono TEXT,
            contatto3_email TEXT,
            whitelist1_nome TEXT,
            whitelist1_cognome TEXT,
            whitelist1_telefono TEXT,
            whitelist1_email TEXT,
            whitelist2_nome TEXT,
            whitelist2_cognome TEXT,
            whitelist2_telefono TEXT,
            whitelist2_email TEXT,
            whitelist3_nome TEXT,
            whitelist3_cognome TEXT,
            whitelist3_telefono TEXT,
            whitelist3_email TEXT,
            patologie TEXT,
            note_mediche TEXT,
            farmaci_data TEXT,
            contatto_emergenza_1_nome TEXT,
            contatto_emergenza_1_telefono TEXT,
            contatto_emergenza_1_relazione TEXT,
            contatto_emergenza_2_nome TEXT,
            contatto_emergenza_2_telefono TEXT,
            contatto_emergenza_2_relazione TEXT,
            medico_curante_nome TEXT,
            medico_curante_telefono TEXT,
            centro_medico_riferimento TEXT,
            allergie TEXT,
            patologie_croniche TEXT,
            farmaci_assunti TEXT,
            modalita_utilizzo TEXT,
            orari_attivazione TEXT,
            status TEXT DEFAULT 'PENDING',
            data_completamento DATETIME,
            form_inviato BOOLEAN DEFAULT FALSE,
            email_benvenuto_inviata BOOLEAN DEFAULT FALSE,
            email_conferma_inviata BOOLEAN DEFAULT FALSE,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (leadId) REFERENCES leads(id) ON DELETE CASCADE,
            FOREIGN KEY (contract_id) REFERENCES contracts(id) ON DELETE CASCADE
          )
        `).run()
        console.log('✅ Nuova configurations creata (senza FK devices)')
        
        // Ripristina dati
        await c.env.DB.prepare(`
          INSERT INTO configurations SELECT * FROM configurations_backup
        `).run()
        console.log('✅ Dati configurations ripristinati')
        
        // Drop backup
        await c.env.DB.prepare(`DROP TABLE configurations_backup`).run()
        console.log('✅ Backup configurations rimosso')
        
        migrations.push('Tabella configurations ricreata senza FK a devices')
      } else {
        console.log('ℹ️ Tabella configurations non trovata')
        migrations.push('Tabella configurations non trovata')
      }
    } catch (error) {
      console.error('❌ Errore fix configurations:', error)
      migrations.push(`Errore fix configurations: ${error}`)
    }

    // ✅ MIGRATION: Aggiungi colonne mancanti a configurations (2026-03-06)
    try {
      console.log('🔧 [MIGRATION] Aggiunta colonne configurations per form post-pagamento...')
      
      const configurationsColumns = [
        // Dati assistito
        { name: 'nome_assistito', type: 'TEXT' },
        { name: 'cognome_assistito', type: 'TEXT' },
        { name: 'data_nascita', type: 'TEXT' },
        { name: 'eta', type: 'TEXT' },
        { name: 'peso', type: 'REAL' },
        { name: 'altezza', type: 'REAL' },
        { name: 'telefono', type: 'TEXT' },
        { name: 'email', type: 'TEXT' },
        { name: 'indirizzo', type: 'TEXT' },
        // Contatti emergenza nuovo formato
        { name: 'contatto1_nome', type: 'TEXT' },
        { name: 'contatto1_cognome', type: 'TEXT' },
        { name: 'contatto1_telefono', type: 'TEXT' },
        { name: 'contatto1_email', type: 'TEXT' },
        { name: 'contatto2_nome', type: 'TEXT' },
        { name: 'contatto2_cognome', type: 'TEXT' },
        { name: 'contatto2_telefono', type: 'TEXT' },
        { name: 'contatto2_email', type: 'TEXT' },
        { name: 'contatto3_nome', type: 'TEXT' },
        { name: 'contatto3_cognome', type: 'TEXT' },
        { name: 'contatto3_telefono', type: 'TEXT' },
        { name: 'contatto3_email', type: 'TEXT' },
        // Whitelist chiamate
        { name: 'whitelist1_nome', type: 'TEXT' },
        { name: 'whitelist1_cognome', type: 'TEXT' },
        { name: 'whitelist1_telefono', type: 'TEXT' },
        { name: 'whitelist1_email', type: 'TEXT' },
        { name: 'whitelist2_nome', type: 'TEXT' },
        { name: 'whitelist2_cognome', type: 'TEXT' },
        { name: 'whitelist2_telefono', type: 'TEXT' },
        { name: 'whitelist2_email', type: 'TEXT' },
        { name: 'whitelist3_nome', type: 'TEXT' },
        { name: 'whitelist3_cognome', type: 'TEXT' },
        { name: 'whitelist3_telefono', type: 'TEXT' },
        { name: 'whitelist3_email', type: 'TEXT' },
        // Patologie/farmaci nuovo formato
        { name: 'patologie', type: 'TEXT' },
        { name: 'note_mediche', type: 'TEXT' },
        { name: 'farmaci_data', type: 'TEXT' }
      ]

      let addedCount = 0
      let existingCount = 0

      for (const col of configurationsColumns) {
        try {
          await c.env.DB.prepare(`
            ALTER TABLE configurations ADD COLUMN ${col.name} ${col.type} DEFAULT ''
          `).run()
          console.log(`✅ [MIGRATION] Colonna ${col.name} aggiunta a configurations`)
          addedCount++
        } catch (error) {
          // Colonna già esistente (normale e safe)
          existingCount++
        }
      }

      console.log(`✅ [MIGRATION] Configurations: ${addedCount} colonne aggiunte, ${existingCount} già esistenti`)
      migrations.push(`Configurations: ${addedCount} colonne aggiunte, ${existingCount} esistenti`)

    } catch (error) {
      console.error('❌ [MIGRATION] Errore aggiunta colonne configurations:', error)
      migrations.push(`Errore colonne configurations: ${error}`)
    }

    // ✅ MIGRATION: Aggiungi campi HubSpot source a leads (2026-03-08)
    try {
      console.log('🔧 [MIGRATION] Aggiunta campi HubSpot source a leads...')
      
      const hubspotColumns = [
        { name: 'hs_object_source', type: 'TEXT', description: 'Fonte HubSpot (FORM, IMPORT, INTEGRATION, etc.)' },
        { name: 'hs_object_source_detail_1', type: 'TEXT', description: 'Dettaglio fonte (es. "Form eCura")' },
        { name: 'dettaglio_fonte', type: 'TEXT', description: 'Campo calcolato basato su hs_object_source' }
      ]

      for (const col of hubspotColumns) {
        try {
          await c.env.DB.prepare(`
            ALTER TABLE leads ADD COLUMN ${col.name} ${col.type}
          `).run()
          console.log(`✅ Colonna ${col.name} aggiunta a leads (${col.description})`)
          migrations.push(`Colonna ${col.name} aggiunta a leads`)
        } catch (error) {
          console.log(`ℹ️ Colonna ${col.name} già esistente in leads`)
        }
      }

      // Popola hs_object_source_detail_1 per lead esistenti con fonte "Form eCura" dal 29/01/2026
      // Include anche varianti: "Form eCura x Test", "Form eCura x test"
      try {
        const result = await c.env.DB.prepare(`
          UPDATE leads 
          SET hs_object_source_detail_1 = 'Form eCura'
          WHERE (fonte = 'Form eCura' OR fonte LIKE 'Form eCura x %')
            AND (created_at >= '2026-01-29' OR timestamp >= '2026-01-29 00:00:00')
            AND hs_object_source_detail_1 IS NULL
        `).run()
        console.log(`✅ Popolato hs_object_source_detail_1 = 'Form eCura' per ${result.meta?.changes || 0} lead esistenti (dal 29/01/2026)`)
        migrations.push(`Popolato hs_object_source_detail_1 = 'Form eCura' per ${result.meta?.changes || 0} lead esistenti (dal 29/01/2026)`)
      } catch (error) {
        console.log('⚠️ Errore popolamento hs_object_source_detail_1:', error)
      }

      // Popola hs_object_source per lead esistenti con fonte "Form eCura" dal 29/01/2026
      // Valore default: 'FORM' (sarà aggiornato quando arriveranno dati reali da HubSpot)
      try {
        const result = await c.env.DB.prepare(`
          UPDATE leads 
          SET hs_object_source = 'FORM'
          WHERE (fonte = 'Form eCura' OR fonte LIKE 'Form eCura x %')
            AND (created_at >= '2026-01-29' OR timestamp >= '2026-01-29 00:00:00')
            AND hs_object_source IS NULL
        `).run()
        console.log(`✅ Popolato hs_object_source = 'FORM' per ${result.meta?.changes || 0} lead esistenti (dal 29/01/2026)`)
        migrations.push(`Popolato hs_object_source = 'FORM' per ${result.meta?.changes || 0} lead esistenti (dal 29/01/2026)`)
      } catch (error) {
        console.log('⚠️ Errore popolamento hs_object_source:', error)
      }

      // Popola dettaglio_fonte per lead esistenti (calcolato da hs_object_source_detail_1)
      try {
        const result = await c.env.DB.prepare(`
          UPDATE leads 
          SET dettaglio_fonte = hs_object_source_detail_1
          WHERE hs_object_source_detail_1 IS NOT NULL
            AND (dettaglio_fonte IS NULL OR dettaglio_fonte = '')
        `).run()
        console.log(`✅ Popolato dettaglio_fonte da hs_object_source_detail_1 per ${result.meta?.changes || 0} lead esistenti`)
        migrations.push(`Popolato dettaglio_fonte da hs_object_source_detail_1 per ${result.meta?.changes || 0} lead esistenti`)
      } catch (error) {
        console.log('⚠️ Errore popolamento dettaglio_fonte:', error)
      }

      console.log('✅ [MIGRATION] Campi HubSpot source aggiunti con successo')
      migrations.push('Campi HubSpot source (hs_object_source, hs_object_source_detail_1, dettaglio_fonte) aggiunti a leads')
    } catch (error) {
      console.error('❌ [MIGRATION] Errore aggiunta campi HubSpot source:', error)
      migrations.push(`Errore campi HubSpot source: ${error}`)
    }

    return c.json({
      success: true,
      message: 'Migrazioni completate',
      migrations
    })
  } catch (error) {
    console.error('❌ Errore migrazioni:', error)
    return c.json({
      success: false,
      error: 'Errore esecuzione migrazioni',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// GET /api/debug/leads-fonte - Report diagnostico sui campi fonte e dettaglio_fonte
app.get('/api/debug/leads-fonte', async (c) => {
  try {
    if (!c.env.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    console.log('🔍 Report diagnostico campi fonte...')

    // Count totale lead
    const totalCount = await c.env.DB.prepare(`
      SELECT COUNT(*) as count FROM leads
    `).first()

    // Count per fonte
    const fonteStats = await c.env.DB.prepare(`
      SELECT 
        fonte,
        COUNT(*) as count
      FROM leads
      GROUP BY fonte
      ORDER BY count DESC
    `).all()

    // Count per dettaglio_fonte
    const dettaglioStats = await c.env.DB.prepare(`
      SELECT 
        dettaglio_fonte,
        COUNT(*) as count
      FROM leads
      GROUP BY dettaglio_fonte
      ORDER BY count DESC
    `).all()

    // Lead con fonte='Form eCura' dal 29/01/2026
    const eCuraFrom29Jan = await c.env.DB.prepare(`
      SELECT COUNT(*) as count
      FROM leads
      WHERE fonte = 'Form eCura' 
        AND (created_at >= '2026-01-29' OR timestamp >= '2026-01-29 00:00:00')
    `).first()

    // Lead con fonte='Form eCura' (tutti)
    const eCuraTotal = await c.env.DB.prepare(`
      SELECT COUNT(*) as count
      FROM leads
      WHERE fonte = 'Form eCura'
    `).first()

    // Lead con dettaglio_fonte popolato
    const withDettaglio = await c.env.DB.prepare(`
      SELECT COUNT(*) as count
      FROM leads
      WHERE dettaglio_fonte IS NOT NULL
    `).first()

    // 🔍 FIND: Lead con fonte vuota o NULL
    const emptyFonte = await c.env.DB.prepare(`
      SELECT id, nomeRichiedente, cognomeRichiedente, email, fonte, created_at, timestamp, COALESCE(fonte, 'NULL') as fonte_display
      FROM leads
      WHERE fonte IS NULL OR TRIM(fonte) = ''
      LIMIT 5
    `).all()

    // Count per hs_object_source (campo HubSpot)
    const hsObjectSourceStats = await c.env.DB.prepare(`
      SELECT 
        hs_object_source,
        COUNT(*) as count
      FROM leads
      GROUP BY hs_object_source
      ORDER BY count DESC
    `).all()

    // Count per hs_object_source_detail_1 (campo HubSpot)
    const hsObjectSourceDetail1Stats = await c.env.DB.prepare(`
      SELECT 
        hs_object_source_detail_1,
        COUNT(*) as count
      FROM leads
      GROUP BY hs_object_source_detail_1
      ORDER BY count DESC
    `).all()

    return c.json({
      success: true,
      report: {
        total_leads: totalCount?.count || 0,
        fonte_distribution: fonteStats.results || [],
        dettaglio_fonte_distribution: dettaglioStats.results || [],
        hs_object_source_distribution: hsObjectSourceStats.results || [],
        hs_object_source_detail_1_distribution: hsObjectSourceDetail1Stats.results || [],
        form_ecura_all: eCuraTotal?.count || 0,
        form_ecura_from_29jan: eCuraFrom29Jan?.count || 0,
        with_dettaglio_fonte: withDettaglio?.count || 0,
        empty_fonte_leads: emptyFonte.results || []
      }
    })
  } catch (error) {
    console.error('❌ Errore report diagnostico:', error)
    return c.json({ 
      success: false, 
      error: 'Errore report',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// GET /api/debug/fix-empty-fonte - Fix lead con fonte vuota
app.get('/api/debug/fix-empty-fonte', async (c) => {
  try {
    if (!c.env.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    console.log('🔧 Fixing lead con fonte vuota...')

    // Fix: imposta fonte = 'MANUAL_ENTRY' per tutti i lead con fonte vuota
    const result = await c.env.DB.prepare(`
      UPDATE leads 
      SET fonte = 'MANUAL_ENTRY'
      WHERE fonte IS NULL OR TRIM(fonte) = ''
    `).run()

    console.log(`✅ Fix completato: ${result.meta.changes} lead aggiornati`)

    return c.json({
      success: true,
      message: `${result.meta.changes} lead aggiornati con fonte='MANUAL_ENTRY'`,
      changes: result.meta.changes
    })
  } catch (error) {
    console.error('❌ Errore fix:', error)
    return c.json({ 
      success: false, 
      error: 'Errore fix',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

