// CRON: REMINDER AUTOMATICI
// ============================================

// POST /api/cron/send-reminders - Invia reminder per lead incompleti
// Cache per evitare esecuzioni multiple del CRON
const cronExecutionCache = new Map<string, number>()

app.post('/api/cron/send-reminders', async (c) => {
  try {
    const db = c.env.DB as D1Database
    const env = c.env
    
    if (!db) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    // Verifica Authorization header per sicurezza
    const authHeader = c.req.header('Authorization')
    const cronSecret = env.CRON_SECRET
    
    if (!cronSecret) {
      // CRON_SECRET non configurato su Cloudflare → log warning ma procedi
      // (non bloccare il cron solo perché il secret non è impostato)
      console.warn('⚠️ [CRON] CRON_SECRET non configurato su Cloudflare — endpoint non protetto!')
    } else if (authHeader !== `Bearer ${cronSecret}`) {
      // CRON_SECRET configurato MA token errato → rifiuta (401)
      console.log(`⚠️ [CRON] Tentativo non autorizzato — header ricevuto: "${authHeader?.substring(0, 20)}..."`)
      console.log('⚠️ [CRON] Verifica che CRON_SECRET su GitHub Secrets == CRON_SECRET su Cloudflare env vars')
      return c.json({ success: false, error: 'Non autorizzato — CRON_SECRET non corrisponde. Verifica Settings → Secrets su GitHub e Cloudflare.' }, 401)
    }
    
    // Previeni esecuzioni multiple entro 1 ora
    const now = Date.now()
    const lastExecution = cronExecutionCache.get('send-reminders') || 0
    const oneHour = 60 * 60 * 1000
    
    if (now - lastExecution < oneHour) {
      const minutesAgo = Math.floor((now - lastExecution) / 1000 / 60)
      console.log(`⚠️ [CRON] Esecuzione già avvenuta ${minutesAgo} minuti fa - skip`)
      return c.json({
        success: true,
        message: 'Esecuzione recente già completata',
        lastExecution: new Date(lastExecution).toISOString(),
        minutesAgo
      }, 429)  // 429 Too Many Requests
    }
    
    // Registra esecuzione
    cronExecutionCache.set('send-reminders', now)
    
    console.log('🔔 [CRON] Avvio processo reminder...')
    
    // Importa funzioni da lead-completion
    const { processReminders } = await import('./modules/lead-completion')
    
    // Processa reminder
    const result = await processReminders(db, env)
    
    // Se cron disabilitato dalla dashboard
    if (result.disabled) {
      console.log('⚠️ [CRON] Cron disabilitato - nessuna azione')
      return c.json({
        success: true,
        message: 'Cron disabilitato dalla dashboard',
        stats: result
      }, 204)  // 204 No Content
    }
    
    console.log(`✅ [CRON] Processo reminder completato: ${result.success}/${result.total} successo, ${result.failed} falliti`)
    
    // ✅ CRON: dopo i reminder, esegui anche l'auto-import HubSpot per eCura
    // (aggiorna hs_object_source_detail_1 con META/GOOGLE/ALTRO e importa nuovi lead)
    let importResult: any = null
    try {
      const { executeAutoImport } = await import('./modules/hubspot-auto-import')
      const baseUrl = env?.PUBLIC_URL || 'https://telemedcare-v12.pages.dev'
      // Ultimi 7 giorni per aggiornare i lead recenti (il sync completo è manuale)
      importResult = await executeAutoImport(db, env, baseUrl, {
        enabled: true,
        startHour: 0,
        days: 7,
        onlyEcura: true,
        dryRun: false
      })
      console.log(`✅ [CRON] Auto-import eCura: ${importResult.imported} importati, ${importResult.updated} canali aggiornati`)
    } catch (importErr) {
      console.warn('⚠️ [CRON] Auto-import eCura fallito (non critico):', importErr)
    }
    
    return c.json({
      success: true,
      message: 'Processo reminder completato',
      stats: result,
      ecuraImport: importResult ? {
        imported: importResult.imported,
        updated: importResult.updated,
        skipped: importResult.skipped
      } : null
    })
    
  } catch (error) {
    console.error('❌ [CRON] Errore processo reminder:', error)
    return c.json({ success: false, error: (error as Error).message }, 500)
  }
})

