// POST /api/migrate-schema - Migrazione automatica schema database
app.post('/api/migrate-schema', async (c) => {
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    console.log('🔄 MIGRAZIONE SCHEMA DATABASE...')
    const migrations = []

    // MIGRAZIONE 1: Aggiungi colonna servizio alla tabella assistiti
    try {
      await c.env.DB.prepare(`
        ALTER TABLE assistiti 
        ADD COLUMN servizio TEXT DEFAULT 'eCura PRO'
      `).run()
      migrations.push('✅ Colonna servizio aggiunta')
      console.log('✅ Colonna servizio aggiunta')
    } catch (e: any) {
      if (e.message && e.message.includes('duplicate column')) {
        migrations.push('ℹ️ Colonna servizio già esiste')
        console.log('ℹ️ Colonna servizio già esiste')
      } else {
        migrations.push(`⚠️ Errore colonna servizio: ${e.message}`)
      }
    }

    // MIGRAZIONE 2: Aggiungi colonna piano alla tabella assistiti
    try {
      await c.env.DB.prepare(`
        ALTER TABLE assistiti 
        ADD COLUMN piano TEXT DEFAULT 'BASE'
      `).run()
      migrations.push('✅ Colonna piano aggiunta')
      console.log('✅ Colonna piano aggiunta')
    } catch (e: any) {
      if (e.message && e.message.includes('duplicate column')) {
        migrations.push('ℹ️ Colonna piano già esiste')
        console.log('ℹ️ Colonna piano già esiste')
      } else {
        migrations.push(`⚠️ Errore colonna piano: ${e.message}`)
      }
    }

    // MIGRAZIONE 3: Aggiorna Eileen a AVANZATO
    try {
      const eileenUpdate = await c.env.DB.prepare(`
        UPDATE assistiti 
        SET piano = 'AVANZATO', servizio = 'eCura PREMIUM'
        WHERE (nome_assistito LIKE '%Eileen%' AND cognome_assistito LIKE '%King%')
           OR (nome_caregiver LIKE '%Elena%' AND cognome_caregiver LIKE '%Saglia%')
      `).run()
      
      if (eileenUpdate.changes && eileenUpdate.changes > 0) {
        migrations.push(`✅ Eileen aggiornata a AVANZATO (${eileenUpdate.changes} record)`)
      } else {
        migrations.push('ℹ️ Eileen non trovata o già aggiornata')
      }
    } catch (e: any) {
      migrations.push(`⚠️ Errore aggiornamento Eileen: ${e.message}`)
    }

    // MIGRAZIONE 4-12: Aggiungi colonne mancanti alla tabella leads
    const leadsColumns = [
      { name: 'luogoNascitaAssistito', type: 'TEXT', default: null },
      { name: 'dataNascitaAssistito', type: 'TEXT', default: null },
      { name: 'indirizzoAssistito', type: 'TEXT', default: null },
      { name: 'capAssistito', type: 'TEXT', default: null },
      { name: 'cittaAssistito', type: 'TEXT', default: null },
      { name: 'provinciaAssistito', type: 'TEXT', default: null },
      { name: 'cfAssistito', type: 'TEXT', default: null },
      { name: 'condizioniSalute', type: 'TEXT', default: null },
      { name: 'intestatarioContratto', type: 'TEXT', default: "'richiedente'" }
    ]

    for (const col of leadsColumns) {
      try {
        const defaultClause = col.default ? `DEFAULT ${col.default}` : ''
        await c.env.DB.prepare(`
          ALTER TABLE leads 
          ADD COLUMN ${col.name} ${col.type} ${defaultClause}
        `).run()
        migrations.push(`✅ Colonna ${col.name} aggiunta a leads`)
        console.log(`✅ Colonna ${col.name} aggiunta a leads`)
      } catch (e: any) {
        if (e.message && e.message.includes('duplicate column')) {
          migrations.push(`ℹ️ Colonna ${col.name} già esiste`)
          console.log(`ℹ️ Colonna ${col.name} già esiste`)
        } else {
          migrations.push(`⚠️ Errore colonna ${col.name}: ${e.message}`)
        }
      }
    }

    // MIGRAZIONE UNIFICAZIONE: sincronizza intestatarioContratto da intestazioneContratto
    // Per i lead creati prima dell'unificazione: intestazioneContratto='assistito' ma
    // intestatarioContratto='richiedente' (default). Allineiamo il nuovo campo.
    try {
      const syncResult = await c.env.DB.prepare(`
        UPDATE leads 
        SET intestatarioContratto = intestazioneContratto
        WHERE intestazioneContratto IN ('richiedente', 'assistito')
          AND (intestatarioContratto IS NULL OR intestatarioContratto = 'richiedente')
          AND intestazioneContratto = 'assistito'
      `).run()
      migrations.push(`✅ Sync intestatarioContratto da intestazioneContratto: ${syncResult.meta?.changes ?? 0} lead aggiornati`)
      console.log(`✅ Sync intestatarioContratto: ${syncResult.meta?.changes ?? 0} record aggiornati`)
    } catch (e: any) {
      migrations.push(`⚠️ Errore sync intestatarioContratto: ${e.message}`)
    }

    // ─── MIGRAZIONE SCONTI: colonne leads ───────────────────────────────────
    const leadsDiscount = [
      { name: 'codice_sconto',       def: `TEXT DEFAULT NULL` },
      { name: 'sconto_percentuale',  def: `REAL DEFAULT 0` },
      { name: 'sconto_fisso',        def: `REAL DEFAULT 0` },
      { name: 'prezzo_scontato',     def: `REAL DEFAULT NULL` },
      { name: 'sconto_sorgente',     def: `TEXT DEFAULT NULL` },
    ]
    for (const col of leadsDiscount) {
      try {
        await c.env.DB.prepare(`ALTER TABLE leads ADD COLUMN ${col.name} ${col.def}`).run()
        migrations.push(`✅ leads.${col.name} aggiunto`)
      } catch (e: any) {
        if (e.message && e.message.includes('duplicate column')) {
          migrations.push(`ℹ️ leads.${col.name} già esiste`)
        } else {
          migrations.push(`⚠️ Errore leads.${col.name}: ${e.message}`)
        }
      }
    }

    // ─── MIGRAZIONE SCONTI: colonne contracts ───────────────────────────────
    const contractsDiscount = [
      { name: 'codice_sconto',     def: `TEXT DEFAULT NULL` },
      { name: 'sconto_applicato',  def: `REAL DEFAULT 0` },
      { name: 'prezzo_scontato',   def: `REAL DEFAULT NULL` },
    ]
    for (const col of contractsDiscount) {
      try {
        await c.env.DB.prepare(`ALTER TABLE contracts ADD COLUMN ${col.name} ${col.def}`).run()
        migrations.push(`✅ contracts.${col.name} aggiunto`)
      } catch (e: any) {
        if (e.message && e.message.includes('duplicate column')) {
          migrations.push(`ℹ️ contracts.${col.name} già esiste`)
        } else {
          migrations.push(`⚠️ Errore contracts.${col.name}: ${e.message}`)
        }
      }
    }

    // ─── MIGRAZIONE SCONTI: tabella discount_codes ─────────────────────────
    try {
      await c.env.DB.prepare(`
        CREATE TABLE IF NOT EXISTS discount_codes (
          id              INTEGER PRIMARY KEY AUTOINCREMENT,
          codice          TEXT NOT NULL UNIQUE,
          descrizione     TEXT,
          tipo            TEXT NOT NULL DEFAULT 'PERCENTUALE',  -- PERCENTUALE | FISSO
          valore          REAL NOT NULL DEFAULT 0,
          sorgente        TEXT NOT NULL DEFAULT 'MANUALE',      -- CANALE | MANUALE | PROMOZIONE | FORM
          canale_associato TEXT DEFAULT NULL,                   -- AON | DOUBLEYOU | ... (solo per sorgente CANALE)
          condizione      TEXT DEFAULT NULL,                    -- eventuale regola JSON futura
          cumulabile      INTEGER NOT NULL DEFAULT 1,           -- 1=cumulabile con altri sconti
          cap_percentuale REAL NOT NULL DEFAULT 20,            -- cap massimo cumulo sconti (%)
          data_scadenza   TEXT DEFAULT NULL,
          utilizzi_max    INTEGER DEFAULT NULL,                 -- NULL = illimitato
          utilizzi_count  INTEGER NOT NULL DEFAULT 0,
          attivo          INTEGER NOT NULL DEFAULT 1,
          created_at      TEXT NOT NULL DEFAULT (datetime('now')),
          updated_at      TEXT NOT NULL DEFAULT (datetime('now'))
        )
      `).run()
      migrations.push('✅ Tabella discount_codes creata (o già esiste)')
    } catch (e: any) {
      migrations.push(`⚠️ Errore creazione discount_codes: ${e.message}`)
    }

    // ─── SEED discount_codes: AON 10% e DOUBLEYOU 10% ──────────────────────
    const seedCodes = [
      {
        codice: 'AON2026',
        descrizione: 'Sconto canale AON 10%',
        tipo: 'PERCENTUALE',
        valore: 10,
        sorgente: 'CANALE',
        canale_associato: 'AON',
        cumulabile: 1,
        cap_percentuale: 20,
        attivo: 1
      },
      {
        codice: 'DOUBLEYOU2026',
        descrizione: 'Sconto canale DoubleYou 10%',
        tipo: 'PERCENTUALE',
        valore: 10,
        sorgente: 'CANALE',
        canale_associato: 'DOUBLEYOU',
        cumulabile: 1,
        cap_percentuale: 20,
        attivo: 1
      }
    ]
    for (const seed of seedCodes) {
      try {
        await c.env.DB.prepare(`
          INSERT OR IGNORE INTO discount_codes
            (codice, descrizione, tipo, valore, sorgente, canale_associato, cumulabile, cap_percentuale, attivo)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          seed.codice, seed.descrizione, seed.tipo, seed.valore,
          seed.sorgente, seed.canale_associato, seed.cumulabile,
          seed.cap_percentuale, seed.attivo
        ).run()
        migrations.push(`✅ Seed discount_code: ${seed.codice}`)
      } catch (e: any) {
        migrations.push(`⚠️ Seed ${seed.codice}: ${e.message}`)
      }
    }

    // ─── MIGRAZIONE SCONTI: tabella lead_discounts (storico applicazioni) ──
    try {
      await c.env.DB.prepare(`
        CREATE TABLE IF NOT EXISTS lead_discounts (
          id               INTEGER PRIMARY KEY AUTOINCREMENT,
          lead_id          TEXT NOT NULL,
          discount_code_id INTEGER NOT NULL,
          codice           TEXT NOT NULL,
          tipo             TEXT NOT NULL,
          valore           REAL NOT NULL,
          sconto_effettivo REAL NOT NULL,  -- importo effettivo scontato (€)
          prezzo_originale REAL NOT NULL,
          prezzo_finale    REAL NOT NULL,
          sorgente         TEXT NOT NULL,
          applicato_da     TEXT DEFAULT NULL,  -- operatore / sistema
          created_at       TEXT NOT NULL DEFAULT (datetime('now'))
        )
      `).run()
      migrations.push('✅ Tabella lead_discounts creata (o già esiste)')
    } catch (e: any) {
      migrations.push(`⚠️ Errore creazione lead_discounts: ${e.message}`)
    }

    // ─── MIGRAZIONE RATEIZZAZIONE: colonne leads ────────────────────────────
    const leadsRateizz = [
      { name: 'rateizzazione_attiva',    def: `INTEGER NOT NULL DEFAULT 0` },   // 1 = pagamento rateizzato
      { name: 'rateizzazione_note',      def: `TEXT DEFAULT NULL` },             // note libere operatore
      { name: 'rateizzazione_saldo',     def: `INTEGER NOT NULL DEFAULT 0` },   // 1 = saldato completamente
      { name: 'riserva_dominio',         def: `INTEGER NOT NULL DEFAULT 1` },   // 1 = clausola riserva dominio attiva (default per rateizzati)
    ]
    for (const col of leadsRateizz) {
      try {
        await c.env.DB.prepare(`ALTER TABLE leads ADD COLUMN ${col.name} ${col.def}`).run()
        migrations.push(`✅ leads.${col.name} aggiunto`)
      } catch (e: any) {
        if (e.message && e.message.includes('duplicate column')) {
          migrations.push(`ℹ️ leads.${col.name} già esiste`)
        } else {
          migrations.push(`⚠️ Errore leads.${col.name}: ${e.message}`)
        }
      }
    }

    // ─── MIGRAZIONE RATEIZZAZIONE: colonne contracts ─────────────────────────
    const contractsRateizz = [
      { name: 'rateizzazione_attiva', def: `INTEGER NOT NULL DEFAULT 0` },
      { name: 'riserva_dominio',      def: `INTEGER NOT NULL DEFAULT 0` },
    ]
    for (const col of contractsRateizz) {
      try {
        await c.env.DB.prepare(`ALTER TABLE contracts ADD COLUMN ${col.name} ${col.def}`).run()
        migrations.push(`✅ contracts.${col.name} aggiunto`)
      } catch (e: any) {
        if (e.message && e.message.includes('duplicate column')) {
          migrations.push(`ℹ️ contracts.${col.name} già esiste`)
        } else {
          migrations.push(`⚠️ Errore contracts.${col.name}: ${e.message}`)
        }
      }
    }

    // ─── MIGRAZIONE RATEIZZAZIONE: tabella rate_pagamento ───────────────────
    try {
      await c.env.DB.prepare(`
        CREATE TABLE IF NOT EXISTS rate_pagamento (
          id                INTEGER PRIMARY KEY AUTOINCREMENT,
          lead_id           TEXT NOT NULL,
          contract_id       TEXT DEFAULT NULL,
          numero_rata       INTEGER NOT NULL,
          importo           REAL NOT NULL,
          importo_iva       REAL DEFAULT 0,
          aliquota_iva      REAL DEFAULT 0,
          data_scadenza     TEXT NOT NULL,
          status            TEXT NOT NULL DEFAULT 'ATTESA',
          data_pagamento    TEXT DEFAULT NULL,
          metodo_pagamento  TEXT DEFAULT NULL,
          riferimento       TEXT DEFAULT NULL,
          note              TEXT DEFAULT NULL,
          creato_da         TEXT DEFAULT NULL,
          created_at        TEXT NOT NULL DEFAULT (datetime('now')),
          updated_at        TEXT NOT NULL DEFAULT (datetime('now'))
        )
      `).run()
      migrations.push('✅ Tabella rate_pagamento creata (o già esiste)')
    } catch (e: any) {
      migrations.push(`⚠️ Errore creazione rate_pagamento: ${e.message}`)
    }
    // ─── MIGRAZIONE: aggiungi aliquota_iva se mancante (tabelle pre-esistenti) ─
    try {
      await c.env.DB.prepare(`ALTER TABLE rate_pagamento ADD COLUMN aliquota_iva REAL DEFAULT 0`).run()
      migrations.push('✅ Colonna aliquota_iva aggiunta a rate_pagamento')
    } catch (e: any) {
      // Colonna già presente — normale
      migrations.push(`ℹ️ aliquota_iva già presente (${e.message})`)
    }

    // ─── MIGRAZIONE RATEIZZAZIONE: colonne proforma ─────────────────────────
    const proformaRateizz = [
      { name: 'rata_numero',    def: `INTEGER DEFAULT NULL` },  // se è una proforma rata: quale rata
      { name: 'rate_totali',    def: `INTEGER DEFAULT NULL` },  // numero totale di rate
      { name: 'riserva_dominio', def: `INTEGER NOT NULL DEFAULT 0` },
    ]
    for (const col of proformaRateizz) {
      try {
        await c.env.DB.prepare(`ALTER TABLE proforma ADD COLUMN ${col.name} ${col.def}`).run()
        migrations.push(`✅ proforma.${col.name} aggiunto`)
      } catch (e: any) {
        if (e.message && e.message.includes('duplicate column')) {
          migrations.push(`ℹ️ proforma.${col.name} già esiste`)
        } else {
          migrations.push(`⚠️ Errore proforma.${col.name}: ${e.message}`)
        }
      }
    }

    return c.json({
      success: true,
      message: 'Migrazione schema completata',
      migrations
    })
  } catch (error) {
    console.error('❌ Errore migrazione schema:', error)
    return c.json({
      success: false,
      error: 'Errore migrazione schema',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// ═══════════════════════════════════════════════════════════════════════════
//  SISTEMA SCONTI — helper + CRUD endpoints
// ═══════════════════════════════════════════════════════════════════════════

/**
 * applyDiscountToLead — applica uno sconto a un lead e persiste i dati.
 *
 * Logica:
 *  1. Recupera il codice da discount_codes (deve essere attivo, non scaduto, con utilizzi disponibili)
 *  2. Calcola lo sconto effettivo rispettando il CAP (default 20%) sul prezzo_anno del lead
 *  3. Aggiorna leads.codice_sconto / sconto_percentuale / sconto_fisso / prezzo_scontato / sconto_sorgente
 *  4. Inserisce riga in lead_discounts (storico)
 *  5. Incrementa discount_codes.utilizzi_count
 *
 * @param db          D1 database binding
 * @param leadId      ID del lead
 * @param codiceSc    Codice sconto da applicare
 * @param sorgente    'CANALE' | 'MANUALE' | 'PROMOZIONE' | 'FORM'
 * @param applicatoDa Nome operatore / sistema (opzionale)
 * @returns { success, prezzo_finale, sconto_effettivo, message }
 */
async function applyDiscountToLead(
  db: any,
  leadId: string,
  codiceSc: string,
  sorgente: string,
  applicatoDa?: string
): Promise<{ success: boolean; prezzo_finale?: number; sconto_effettivo?: number; message: string }> {
  try {
    // 1. Recupera il codice sconto
    const dc = await db.prepare(`
      SELECT * FROM discount_codes
      WHERE codice = ? AND attivo = 1
        AND (data_scadenza IS NULL OR date(data_scadenza) >= date('now'))
        AND (utilizzi_max IS NULL OR utilizzi_count < utilizzi_max)
    `).bind(codiceSc).first() as any

    if (!dc) {
      return { success: false, message: `Codice sconto "${codiceSc}" non valido, scaduto o esaurito` }
    }

    // 2. Recupera prezzo originale lead
    const lead = await db.prepare('SELECT prezzo_anno, codice_sconto FROM leads WHERE id = ?').bind(leadId).first() as any
    if (!lead) {
      return { success: false, message: `Lead ${leadId} non trovato` }
    }

    const prezzoOriginale = Number(lead.prezzo_anno) || 0
    if (prezzoOriginale <= 0) {
      return { success: false, message: `Lead ${leadId} non ha un prezzo_anno valido` }
    }

    // 3. Calcola sconto effettivo rispettando CAP
    const capPerc = Number(dc.cap_percentuale) || 20
    let percentualeEffettiva = 0
    let importoFisso = 0

    if (dc.tipo === 'PERCENTUALE') {
      // Applica CAP percentuale
      percentualeEffettiva = Math.min(Number(dc.valore), capPerc)
      importoFisso = 0
    } else {
      // Sconto fisso — converti in % per verificare il CAP
      const percEquivalente = (Number(dc.valore) / prezzoOriginale) * 100
      if (percEquivalente > capPerc) {
        // Riduci importo fisso al CAP
        importoFisso = (prezzoOriginale * capPerc) / 100
        percentualeEffettiva = capPerc
      } else {
        importoFisso = Number(dc.valore)
        percentualeEffettiva = percEquivalente
      }
    }

    const scontoEffettivo = dc.tipo === 'PERCENTUALE'
      ? Math.round((prezzoOriginale * percentualeEffettiva / 100) * 100) / 100
      : Math.round(importoFisso * 100) / 100

    const prezzoFinale = Math.round((prezzoOriginale - scontoEffettivo) * 100) / 100

    // 4. Aggiorna leads
    await db.prepare(`
      UPDATE leads SET
        codice_sconto      = ?,
        sconto_percentuale = ?,
        sconto_fisso       = ?,
        prezzo_scontato    = ?,
        sconto_sorgente    = ?,
        updated_at         = datetime('now')
      WHERE id = ?
    `).bind(
      dc.codice,
      dc.tipo === 'PERCENTUALE' ? percentualeEffettiva : 0,
      dc.tipo === 'FISSO'       ? importoFisso         : 0,
      prezzoFinale,
      sorgente,
      leadId
    ).run()

    // 5. Storico
    await db.prepare(`
      INSERT INTO lead_discounts
        (lead_id, discount_code_id, codice, tipo, valore, sconto_effettivo,
         prezzo_originale, prezzo_finale, sorgente, applicato_da)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      leadId, dc.id, dc.codice, dc.tipo, dc.valore,
      scontoEffettivo, prezzoOriginale, prezzoFinale,
      sorgente, applicatoDa || 'sistema'
    ).run()

    // 6. Incrementa utilizzi
    await db.prepare(`
      UPDATE discount_codes SET utilizzi_count = utilizzi_count + 1, updated_at = datetime('now')
      WHERE id = ?
    `).bind(dc.id).run()

    return {
      success: true,
      prezzo_finale: prezzoFinale,
      sconto_effettivo: scontoEffettivo,
      message: `Sconto ${dc.codice} applicato: -${scontoEffettivo}€ → prezzo finale €${prezzoFinale}`
    }
  } catch (err: any) {
    console.error('❌ applyDiscountToLead error:', err)
    return { success: false, message: err?.message || 'Errore interno sconti' }
  }
}

// ─── GET /api/discount-codes — lista tutti i codici ────────────────────────
app.get('/api/discount-codes', requireAuth, async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const rows = await c.env.DB.prepare(
      'SELECT * FROM discount_codes ORDER BY sorgente, codice'
    ).all()
    return c.json({ success: true, codes: rows.results || [] })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message }, 500)
  }
})

// ─── POST /api/discount-codes — crea nuovo codice ─────────────────────────
app.post('/api/discount-codes', requireAuth, async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const body = await c.req.json() as any
    const {
      codice, descrizione, tipo = 'PERCENTUALE', valore,
      sorgente = 'MANUALE', canale_associato, condizione,
      cumulabile = 1, cap_percentuale = 20,
      data_scadenza, utilizzi_max, attivo = 1
    } = body

    if (!codice || valore === undefined) {
      return c.json({ success: false, error: 'codice e valore sono obbligatori' }, 400)
    }

    const r = await c.env.DB.prepare(`
      INSERT INTO discount_codes
        (codice, descrizione, tipo, valore, sorgente, canale_associato,
         condizione, cumulabile, cap_percentuale, data_scadenza, utilizzi_max, attivo)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      codice.toUpperCase(), descrizione || null, tipo, Number(valore),
      sorgente, canale_associato || null, condizione || null,
      cumulabile ? 1 : 0, Number(cap_percentuale),
      data_scadenza || null, utilizzi_max ? Number(utilizzi_max) : null,
      attivo ? 1 : 0
    ).run()

    return c.json({ success: true, id: r.meta?.last_row_id, codice: codice.toUpperCase() })
  } catch (error: any) {
    const dupMsg = error?.message?.includes('UNIQUE') ? `Codice già esistente` : error?.message
    return c.json({ success: false, error: dupMsg }, 500)
  }
})

// ─── PUT /api/discount-codes/:codice — aggiorna codice ────────────────────
app.put('/api/discount-codes/:codice', requireAuth, async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const codice = c.req.param('codice').toUpperCase()
    const body = await c.req.json() as any

    const existing = await c.env.DB.prepare(
      'SELECT * FROM discount_codes WHERE codice = ?'
    ).bind(codice).first() as any
    if (!existing) return c.json({ success: false, error: 'Codice non trovato' }, 404)

    const {
      descrizione, tipo, valore, sorgente, canale_associato,
      condizione, cumulabile, cap_percentuale, data_scadenza,
      utilizzi_max, attivo
    } = body

    await c.env.DB.prepare(`
      UPDATE discount_codes SET
        descrizione      = COALESCE(?, descrizione),
        tipo             = COALESCE(?, tipo),
        valore           = COALESCE(?, valore),
        sorgente         = COALESCE(?, sorgente),
        canale_associato = COALESCE(?, canale_associato),
        condizione       = COALESCE(?, condizione),
        cumulabile       = COALESCE(?, cumulabile),
        cap_percentuale  = COALESCE(?, cap_percentuale),
        data_scadenza    = COALESCE(?, data_scadenza),
        utilizzi_max     = COALESCE(?, utilizzi_max),
        attivo           = COALESCE(?, attivo),
        updated_at       = datetime('now')
      WHERE codice = ?
    `).bind(
      descrizione ?? null, tipo ?? null,
      valore !== undefined ? Number(valore) : null,
      sorgente ?? null, canale_associato ?? null, condizione ?? null,
      cumulabile !== undefined ? (cumulabile ? 1 : 0) : null,
      cap_percentuale !== undefined ? Number(cap_percentuale) : null,
      data_scadenza ?? null,
      utilizzi_max !== undefined ? Number(utilizzi_max) : null,
      attivo !== undefined ? (attivo ? 1 : 0) : null,
      codice
    ).run()

    return c.json({ success: true, codice })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message }, 500)
  }
})

// ─── DELETE /api/discount-codes/:codice — disattiva (soft-delete) ─────────
app.delete('/api/discount-codes/:codice', requireAuth, async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const codice = c.req.param('codice').toUpperCase()
    await c.env.DB.prepare(
      `UPDATE discount_codes SET attivo = 0, updated_at = datetime('now') WHERE codice = ?`
    ).bind(codice).run()
    return c.json({ success: true, message: `Codice ${codice} disattivato` })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message }, 500)
  }
})

// ─── POST /api/leads/:id/apply-discount — applica sconto MANUALE ──────────
app.post('/api/leads/:id/apply-discount', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const body = await c.req.json() as any
    const { codice, applicato_da } = body
    if (!codice) return c.json({ success: false, error: 'Campo "codice" obbligatorio' }, 400)

    const result = await applyDiscountToLead(
      c.env.DB, leadId, codice.toUpperCase(), 'MANUALE', applicato_da || 'operatore'
    )
    if (!result.success) return c.json({ success: false, error: result.message }, 400)
    return c.json({ success: true, ...result })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message }, 500)
  }
})

// ─── DELETE /api/leads/:id/apply-discount — rimuove sconto da un lead ─────
app.delete('/api/leads/:id/apply-discount', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    await c.env.DB.prepare(`
      UPDATE leads SET
        codice_sconto = NULL, sconto_percentuale = 0,
        sconto_fisso = 0, prezzo_scontato = NULL, sconto_sorgente = NULL,
        updated_at = datetime('now')
      WHERE id = ?
    `).bind(leadId).run()
    return c.json({ success: true, message: 'Sconto rimosso dal lead' })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message }, 500)
  }
})

// ─── GET /api/leads/:id/discounts — storico sconti di un lead ─────────────
app.get('/api/leads/:id/discounts', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const rows = await c.env.DB.prepare(
      'SELECT * FROM lead_discounts WHERE lead_id = ? ORDER BY created_at DESC'
    ).bind(leadId).all()
    return c.json({ success: true, discounts: rows.results || [] })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message }, 500)
  }
})

// ─── POST /api/leads/apply-canale-discounts ────────────────────────────────
// Scansiona i lead AON/DOUBLEYOU senza sconto e applica automaticamente
// il codice canale corrispondente (sorgente CANALE).
// Può essere chiamato:
//   - dopo ogni import batch
//   - da cron / manuale per recuperare lead pregressi
app.post('/api/leads/apply-canale-discounts', requireAuth, async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)

    // Mappa canale → codice_sconto
    const CANALE_MAP: Record<string, string> = {
      'AON':        'AON2026',
      'DOUBLEYOU':  'DOUBLEYOU2026',
      'DOUBLE YOU': 'DOUBLEYOU2026',
    }

    let applied = 0
    let skipped = 0
    const errors: string[] = []

    for (const [canaleKey, codiceSconto] of Object.entries(CANALE_MAP)) {
      // Recupera lead di questo canale senza sconto già applicato
      const candidati = await c.env.DB.prepare(`
        SELECT id, prezzo_anno, fonte, canale
        FROM leads
        WHERE (
            UPPER(fonte)   LIKE ?
          OR UPPER(canale) LIKE ?
          OR id            LIKE ?
        )
        AND (codice_sconto IS NULL OR codice_sconto = '')
        AND prezzo_anno IS NOT NULL AND prezzo_anno > 0
        ORDER BY created_at DESC
      `).bind(
        `%${canaleKey}%`,
        `%${canaleKey}%`,
        `%${canaleKey.replace(' ', '')}%`
      ).all()

      const leads = (candidati.results || []) as any[]
      console.log(`🏷️ [CANALE-DISCOUNT] ${canaleKey}: ${leads.length} lead candidati`)

      for (const lead of leads) {
        const result = await applyDiscountToLead(
          c.env.DB, lead.id, codiceSconto, 'CANALE', 'sistema-canale'
        )
        if (result.success) {
          applied++
          console.log(`✅ [CANALE-DISCOUNT] ${lead.id} → ${codiceSconto}: ${result.message}`)
        } else {
          skipped++
          errors.push(`${lead.id}: ${result.message}`)
          console.warn(`⚠️ [CANALE-DISCOUNT] skip ${lead.id}: ${result.message}`)
        }
      }
    }

    return c.json({
      success: true,
      applied,
      skipped,
      errors,
      message: `Sconti canale applicati: ${applied} lead aggiornati, ${skipped} saltati`
    })
  } catch (error: any) {
    console.error('❌ [CANALE-DISCOUNT] Errore:', error)
    return c.json({ success: false, error: error?.message }, 500)
  }
})

// ═══════════════════════════════════════════════════════════════════════════
// RATEIZZAZIONE — endpoint CRUD
// ═══════════════════════════════════════════════════════════════════════════

// ─── POST /api/leads/:id/rateizzazione — imposta piano rate per un lead ────
app.post('/api/leads/:id/rateizzazione', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const body = await c.req.json() as {
      rate: Array<{ numero_rata: number; importo: number; data_scadenza: string; note?: string }>
      riserva_dominio: boolean
      note_rateizzazione?: string
    }

    if (!body.rate || !Array.isArray(body.rate) || body.rate.length === 0) {
      return c.json({ success: false, error: 'Array rate obbligatorio' }, 400)
    }

    const db = c.env.DB
    const now = new Date().toISOString()

    // 0. Assicura che la tabella esista (colonne minime) + aggiungi colonne leads se mancanti
    const step0a = 'CREATE TABLE rate_pagamento'
    await db.prepare(`
      CREATE TABLE IF NOT EXISTS rate_pagamento (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        lead_id          TEXT NOT NULL,
        numero_rata      INTEGER NOT NULL,
        importo          REAL NOT NULL,
        data_scadenza    TEXT NOT NULL,
        status           TEXT NOT NULL DEFAULT 'ATTESA',
        metodo_pagamento TEXT DEFAULT NULL,
        riferimento      TEXT DEFAULT NULL,
        note             TEXT DEFAULT NULL,
        created_at       TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at       TEXT NOT NULL DEFAULT (datetime('now'))
      )
    `).run()

    // Aggiungi colonne leads mancanti (migration non eseguita)
    const leadsColsDefs: Array<[string, string]> = [
      ['rateizzazione_attiva', 'INTEGER NOT NULL DEFAULT 0'],
      ['rateizzazione_saldo',  'INTEGER NOT NULL DEFAULT 0'],
      ['rateizzazione_note',   'TEXT DEFAULT NULL'],
      ['riserva_dominio',      'INTEGER NOT NULL DEFAULT 0'],
    ]
    for (const [col, def] of leadsColsDefs) {
      try { await db.prepare(`ALTER TABLE leads ADD COLUMN ${col} ${def}`).run() } catch {}
    }
    // Aggiungi colonne contracts mancanti
    const contractsColsDefs: Array<[string, string]> = [
      ['rateizzazione_attiva', 'INTEGER NOT NULL DEFAULT 0'],
      ['riserva_dominio',      'INTEGER NOT NULL DEFAULT 0'],
    ]
    for (const [col, def] of contractsColsDefs) {
      try { await db.prepare(`ALTER TABLE contracts ADD COLUMN ${col} ${def}`).run() } catch {}
    }

    // 1. Cancella rate precedenti ATTESA/SCADUTA
    await db.prepare(`DELETE FROM rate_pagamento WHERE lead_id = ? AND status IN ('ATTESA','SCADUTA')`).bind(leadId).run()

    // 2. Inserisce le nuove rate
    for (const r of body.rate) {
      if (!r.importo || !r.data_scadenza) continue
      await db.prepare(`
        INSERT INTO rate_pagamento (lead_id, numero_rata, importo, data_scadenza, status, note, created_at, updated_at)
        VALUES (?, ?, ?, ?, 'ATTESA', ?, ?, ?)
      `).bind(leadId, r.numero_rata, r.importo, r.data_scadenza, r.note || null, now, now).run()
    }

    // 3. Aggiorna flags sul lead
    await db.prepare(`
      UPDATE leads SET rateizzazione_attiva=1, riserva_dominio=?, rateizzazione_note=?, rateizzazione_saldo=0, updated_at=?
      WHERE id=?
    `).bind(body.riserva_dominio ? 1 : 0, body.note_rateizzazione || null, now, leadId).run()

    // 4. Aggiorna contratto firmato se esiste
    try {
      await db.prepare(`
        UPDATE contracts SET rateizzazione_attiva=1, riserva_dominio=?, updated_at=?
        WHERE leadId=? AND status IN ('SIGNED','COMPLETED')
      `).bind(body.riserva_dominio ? 1 : 0, now, leadId).run()
    } catch {}

    console.log(`📅 [RATEIZZAZIONE] Lead ${leadId}: ${body.rate.length} rate impostate`)
    return c.json({ success: true, rate_create: body.rate.length, message: `Piano rateizzazione impostato: ${body.rate.length} rate` })
  } catch (err: any) {
    console.error('❌ [RATEIZZAZIONE] Errore:', err)
    return c.json({ success: false, error: err?.message ?? String(err) }, 500)
  }
})

// ─── GET /api/leads/:id/rateizzazione — legge piano rate e stato ───────────
app.get('/api/leads/:id/rateizzazione', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const db = c.env.DB

    const lead = await db.prepare(`
      SELECT rateizzazione_attiva, rateizzazione_note, rateizzazione_saldo, riserva_dominio, prezzo_anno, prezzo_scontato
      FROM leads WHERE id = ?
    `).bind(leadId).first() as any

    if (!lead) return c.json({ success: false, error: 'Lead non trovato' }, 404)

    const rate = await db.prepare(`
      SELECT * FROM rate_pagamento WHERE lead_id = ? ORDER BY numero_rata ASC
    `).bind(leadId).all()

    const totaleImporti = (rate.results || []).reduce((sum: number, r: any) => sum + (Number(r.importo) || 0), 0)
    const totalePagato  = (rate.results || []).filter((r: any) => r.status === 'PAGATA').reduce((sum: number, r: any) => sum + (Number(r.importo) || 0), 0)
    const ratePagate    = (rate.results || []).filter((r: any) => r.status === 'PAGATA').length

    return c.json({
      success: true,
      rateizzazione_attiva: Boolean(lead.rateizzazione_attiva),
      rateizzazione_saldo:  Boolean(lead.rateizzazione_saldo),
      riserva_dominio:      Boolean(lead.riserva_dominio),
      rateizzazione_note:   lead.rateizzazione_note,
      prezzo_totale:        lead.prezzo_scontato || lead.prezzo_anno,
      totale_rate:          totaleImporti,
      totale_pagato:        totalePagato,
      rate_pagate:          ratePagate,
      rate_totali:          (rate.results || []).length,
      rate:                 rate.results || []
    })
  } catch (err: any) {
    return c.json({ success: false, error: err?.message }, 500)
  }
})

// ─── PATCH /api/leads/:id/rate/:rataId — aggiorna stato singola rata ──────
app.patch('/api/leads/:id/rate/:rataId', requireAuth, async (c) => {
  const leadId  = c.req.param('id')
  const rataId  = c.req.param('rataId')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const body = await c.req.json() as {
      status: 'PAGATA' | 'ATTESA' | 'SCADUTA' | 'ANNULLATA'
      data_pagamento?: string
      metodo_pagamento?: string
      riferimento?: string
      note?: string
    }
    const db = c.env.DB
    const now = new Date().toISOString()

    await db.prepare(`
      UPDATE rate_pagamento SET
        status           = ?,
        data_pagamento   = ?,
        metodo_pagamento = ?,
        riferimento      = ?,
        note             = COALESCE(?, note),
        updated_at       = ?
      WHERE id = ? AND lead_id = ?
    `).bind(
      body.status,
      body.status === 'PAGATA' ? (body.data_pagamento || now) : null,
      body.metodo_pagamento || null,
      body.riferimento || null,
      body.note || null,
      now,
      rataId, leadId
    ).run()

    // Verifica se tutte le rate sono pagate → aggiorna saldo
    const rate = await db.prepare(
      `SELECT status FROM rate_pagamento WHERE lead_id = ?`
    ).bind(leadId).all()
    const tuttiPagati = (rate.results || []).length > 0
      && (rate.results || []).every((r: any) => r.status === 'PAGATA')

    if (tuttiPagati) {
      await db.prepare(`
        UPDATE leads SET rateizzazione_saldo = 1, updated_at = ? WHERE id = ?
      `).bind(now, leadId).run()
    }

    return c.json({
      success: true,
      saldato: tuttiPagati,
      message: `Rata ${rataId} aggiornata a ${body.status}${tuttiPagati ? ' — piano SALDATO ✅' : ''}`
    })
  } catch (err: any) {
    return c.json({ success: false, error: err?.message }, 500)
  }
})

// ─── DELETE /api/leads/:id/rateizzazione — rimuove piano rate ──────────────
app.delete('/api/leads/:id/rateizzazione', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
    const db = c.env.DB
    const now = new Date().toISOString()

    await db.prepare(`DELETE FROM rate_pagamento WHERE lead_id = ? AND status = 'ATTESA'`).bind(leadId).run()
    await db.prepare(`
      UPDATE leads SET rateizzazione_attiva = 0, riserva_dominio = 0, rateizzazione_saldo = 0, rateizzazione_note = NULL, updated_at = ?
      WHERE id = ?
    `).bind(now, leadId).run()
    await db.prepare(`
      UPDATE contracts SET rateizzazione_attiva = 0, riserva_dominio = 0, updated_at = ? WHERE leadId = ?
    `).bind(now, leadId).run()

    return c.json({ success: true, message: 'Piano rateizzazione rimosso' })
  } catch (err: any) {
    return c.json({ success: false, error: err?.message }, 500)
  }
})

