// Utility per generare ID lead
function generateLeadId(): string {
  const timestamp = new Date().toISOString().replace(/[:.]/g, '')
  const random = Math.random().toString(36).substring(2, 8).toUpperCase()
  return `LEAD_${timestamp}_${random}`
}

