// 🔧 ENDPOINT ONE-SHOT: Deduplicazione tabella assistiti
app.get('/api/oneshot-dedup-assistiti-9k3mq', async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)

    // 1. Leggi tutti gli assistiti prima della pulizia
    const { results: prima } = await c.env.DB.prepare(
      `SELECT id, codice, nome_assistito, cognome_assistito, imei, created_at FROM assistiti ORDER BY cognome_assistito, id`
    ).all()

    // 2. Trova duplicati: stessa combinazione (nome_assistito + cognome_assistito) o stesso imei
    //    Tieni il record con id minore (il più vecchio), elimina gli altri
    const { results: duplicati } = await c.env.DB.prepare(`
      SELECT id FROM assistiti
      WHERE id NOT IN (
        SELECT MIN(id) FROM assistiti
        GROUP BY LOWER(TRIM(cognome_assistito)), LOWER(TRIM(nome_assistito))
      )
    `).all()

    const idsDaEliminare = duplicati.map((r: any) => r.id)
    let eliminati = 0

    for (const id of idsDaEliminare) {
      await c.env.DB.prepare(`DELETE FROM assistiti WHERE id = ?`).bind(id).run()
      eliminati++
    }

    // 3. Leggi tutti gli assistiti dopo la pulizia
    const { results: dopo } = await c.env.DB.prepare(
      `SELECT id, codice, nome_assistito, cognome_assistito, imei, created_at FROM assistiti ORDER BY cognome_assistito, id`
    ).all()

    return c.json({
      success: true,
      prima: { totale: prima.length, assistiti: prima },
      eliminati: { totale: eliminati, ids: idsDaEliminare },
      dopo: { totale: dopo.length, assistiti: dopo }
    })
  } catch (err: any) {
    return c.json({ success: false, error: err.message }, 500)
  }
})

// 🔧 ENDPOINT ONE-SHOT: Aggiorna IMEI corretti per King e Pennacchio
app.get('/api/oneshot-fix-imei-king-pennacchio-4r7wz', async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)

    const oggi = new Date().toISOString()
    const aggiornamenti: any[] = []

    // ── Fix cognomi nei lead collegati ai contratti CTR-*-2026 ───────────────
    // La dashboard mostra nomeRichiedente/cognomeRichiedente dalla tabella leads
    // via JOIN. init-assistiti aveva messo il cognome del caregiver invece
    // dell'assistito. Fix: per ogni contratto CTR-*-2026, legge il nome corretto
    // dalla tabella assistiti (per IMEI) e aggiorna il lead collegato.
    // Zero hardcoding: tutti i dati vengono dal DB.
    const fixLeadsResult: any[] = []

    // Recupera tutti i contratti CTR-*-2026 con il loro leadId e l'IMEI dispositivo
    const { results: contratti2026 } = await c.env.DB.prepare(`
      SELECT codice_contratto, leadId, imei_dispositivo
      FROM contracts
      WHERE codice_contratto LIKE 'CTR-%-2026'
        AND is_rinnovo IS NULL OR is_rinnovo = 0
    `).all() as { results: any[] }

    for (const ctr of contratti2026) {
      if (!ctr.leadId || !ctr.imei_dispositivo) continue

      // Trova l'assistito corrispondente per IMEI — è la fonte di verità
      const ass = await c.env.DB.prepare(`
        SELECT nome_assistito, cognome_assistito
        FROM assistiti
        WHERE imei = ?
      `).bind(ctr.imei_dispositivo).first() as any

      if (!ass?.cognome_assistito) continue

      // Aggiorna il lead con i dati corretti dell'assistito
      const r = await c.env.DB.prepare(`
        UPDATE leads
        SET nomeRichiedente    = ?,
            cognomeRichiedente = ?,
            nomeAssistito      = ?,
            cognomeAssistito   = ?,
            updated_at         = ?
        WHERE id = ?
      `).bind(
        ass.nome_assistito, ass.cognome_assistito,
        ass.nome_assistito, ass.cognome_assistito,
        oggi, ctr.leadId
      ).run()

      fixLeadsResult.push({
        codice: ctr.codice_contratto,
        leadId: ctr.leadId,
        imei: ctr.imei_dispositivo,
        nome: ass.nome_assistito,
        cognome: ass.cognome_assistito,
        changes: r.meta?.changes
      })
    }

    // ── Inserisce contratti mancanti King 2026 e Cacace 2026 ─────────────────
    // leadId noto: LEAD-IRBEMA-00019 (Elena Saglia — caregiver di King e referral Cacace)
    // IMEI noti (già nel DB assistiti): King=868298061208378, Cacace=864866058470732
    // Dati contrattuali dai PDF firmati (codici, date, importi — non dati personali)
    const contrattiFirm = [
      {
        codice:    'CTR-KING-AVANZATO-2026',
        imei:      '868298061208378',
        leadId:    'LEAD-IRBEMA-00019',
        piano:     'AVANZATO',
        servizio:  'eCura PRO',
        prezzo:    860,
        mensile:   72,
        dataInizio:'2026-05-06',
        dataScad:  '2027-05-05',
        status:    'SIGNED',
      },
      {
        codice:    'CTR-CACACE-BASE-2026',
        imei:      '864866058470732',
        leadId:    'LEAD-IRBEMA-00019',
        piano:     'AVANZATO',
        servizio:  'eCura PRO',
        prezzo:    840,
        mensile:   70,
        dataInizio:'2026-05-28',
        dataScad:  '2027-05-27',
        status:    'SIGNED',
      },
    ]

    // Rileva colonne reali di contracts tramite PRAGMA
    const { results: cols } = await c.env.DB.prepare(`PRAGMA table_info(contracts)`).all()
    const colNames = (cols as any[]).map((r: any) => r.name)

    const insertRisultati: any[] = []
    for (const ctr of contrattiFirm) {
      // Contratto già presente? Skip idempotente
      const existing = await c.env.DB.prepare(
        `SELECT id FROM contracts WHERE codice_contratto = ?`
      ).bind(ctr.codice).first()
      if (existing) { insertRisultati.push({ codice: ctr.codice, esito: 'già presente' }); continue }

      // Legge dati assistito dal DB tramite IMEI
      const ass = await c.env.DB.prepare(
        `SELECT nome_assistito, cognome_assistito FROM assistiti WHERE imei = ?`
      ).bind(ctr.imei).first() as any

      // Legge dati lead dal DB tramite leadId
      const lead = await c.env.DB.prepare(
        `SELECT nomeRichiedente, cognomeRichiedente, email, telefono FROM leads WHERE id = ?`
      ).bind(ctr.leadId).first() as any

      if (!ass || !lead) {
        insertRisultati.push({ codice: ctr.codice, esito: 'assistito o lead non trovato', ass, lead })
        continue
      }

      // Costruisce INSERT dinamicamente sulle colonne reali del DB
      const has = (col: string) => colNames.includes(col)
      const insertCols: string[] = ['id']
      const insertVals: any[]    = [`${ctr.codice}-ID`]
      const add = (col: string, val: any) => { if (has(col)) { insertCols.push(col); insertVals.push(val) } }

      add('leadId',              ctr.leadId)
      add('lead_id',             ctr.leadId)
      add('codice_contratto',    ctr.codice)
      add('contract_code',       ctr.codice)
      add('tipo_contratto',      ctr.piano)
      add('contract_type',       ctr.piano)
      add('piano',               ctr.piano)
      add('servizio',            ctr.servizio)
      add('template_utilizzato', 'contratto_b2c')
      add('contenuto_html',      '')
      add('contract_html',       '')
      add('cliente_nome',        lead.nomeRichiedente)
      add('nome_cliente',        lead.nomeRichiedente)
      add('cliente_cognome',     lead.cognomeRichiedente)
      add('cognome_cliente',     lead.cognomeRichiedente)
      add('cliente_email',       lead.email || '')
      add('email_cliente',       lead.email || '')
      add('cliente_telefono',    lead.telefono || '')
      add('assistito_nome',      ass.nome_assistito)
      add('assistito_cognome',   ass.cognome_assistito)
      add('imei_dispositivo',    ctr.imei)
      add('status',              ctr.status)
      add('prezzo_totale',       ctr.prezzo)
      add('prezzo_base',         ctr.prezzo)
      add('prezzo_mensile',      ctr.mensile)
      add('durata_mesi',         12)
      add('data_invio',          ctr.dataInizio)
      add('data_scadenza',       ctr.dataScad)
      add('created_at',          oggi)
      add('updated_at',          oggi)

      const ph = insertCols.map(() => '?').join(', ')
      await c.env.DB.prepare(
        `INSERT INTO contracts (${insertCols.join(', ')}) VALUES (${ph})`
      ).bind(...insertVals).run()

      insertRisultati.push({
        codice: ctr.codice,
        esito: 'inserito',
        leadId: ctr.leadId,
        assistito: `${ass.nome_assistito} ${ass.cognome_assistito}`,
        lead: `${lead.nomeRichiedente} ${lead.cognomeRichiedente}`,
      })
    }

    // Verifica finale
    const { results: statoImei } = await c.env.DB.prepare(`
      SELECT id, nome_assistito, cognome_assistito, imei, updated_at
      FROM assistiti
    `).all()

    return c.json({
      success: true,
      fix_leads: fixLeadsResult,
      contratti_inseriti: insertRisultati,
      assistiti: statoImei
    })
  } catch (err: any) {
    return c.json({ success: false, error: err.message }, 500)
  }
})



// 🔧 ENDPOINT ONE-SHOT: Diagnostica contratti CTR-*-2026 — mostra lead agganciati
// Nessun hardcoding: legge tutto dal DB e mostra la situazione reale
app.get('/api/oneshot-diagnosi-contratti-2026-5nw8v', async (c) => {
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)

    // Legge tutti i contratti CTR-*-2026 con il lead agganciato
    // così vediamo esattamente quali cognomi errati provengono da quale lead
    const { results } = await c.env.DB.prepare(`
      SELECT
        c.codice_contratto,
        c.leadId,
        c.imei_dispositivo,
        l.nomeRichiedente,
        l.cognomeRichiedente,
        l.nomeAssistito,
        l.cognomeAssistito,
        a.nome_assistito  AS ass_nome,
        a.cognome_assistito AS ass_cognome
      FROM contracts c
      LEFT JOIN leads l ON c.leadId = l.id
      LEFT JOIN assistiti a ON c.imei_dispositivo = a.imei
      WHERE c.codice_contratto LIKE 'CTR-%-2026'
        AND (c.is_rinnovo IS NULL OR c.is_rinnovo = 0)
      ORDER BY c.codice_contratto
    `).all()

    return c.json({ success: true, contratti: results })
  } catch (err: any) {
    return c.json({ success: false, error: err.message }, 500)
  }
})

