/**
 * 1. FIRMA MANUALE CONTRATTO
 * Firma contratto senza processo digitale (firma staff)
 */
app.post('/api/leads/:id/manual-sign', async (c) => {
  const leadId = c.req.param('id')
  
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    // Recupera lead
    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    
    if (!lead) {
      return c.json({ success: false, error: 'Lead non trovato' }, 404)
    }
    
    console.log(`🖊️ [MANUAL-SIGN] Firma manuale contratto per lead ${leadId}`)
    
    // Genera ID contratto
    const timestamp = Date.now()
    const cognome = (lead.cognomeAssistito || lead.cognomeRichiedente || 'UNKNOWN').toUpperCase().replace(/[^A-Z]/g, '')
    const anno = new Date().getFullYear()
    const contractId = `CONTRACT_CTR-${cognome}-${anno}_${timestamp}`
    const contractCode = `CTR-${cognome}-${anno}`
    
    // Determina servizio e piano
    const servizio = lead.servizio || 'eCura PRO'
    const piano = lead.piano || 'BASE'
    
    // Calcola prezzi — normalizza servizioType: 'eCura FAMILY PRO' → 'FAMILY', 'eCura PREMIUM' → 'PREMIUM', ecc.
    const rawType = servizio.replace(/^eCura\s+/i, '').trim().toUpperCase()
    const servizioType = rawType.includes('PREMIUM') ? 'PREMIUM'
      : rawType.includes('FAMILY') ? 'FAMILY'
      : 'PRO'
    const pricing = calculatePrice(servizioType, piano.toUpperCase())
    
    // Genera HTML contratto (semplificato)
    const contractHtml = `
      <h1>Contratto ${servizio} - ${piano}</h1>
      <p><strong>Cliente:</strong> ${lead.nomeRichiedente} ${lead.cognomeRichiedente}</p>
      <p><strong>Assistito:</strong> ${lead.nomeAssistito} ${lead.cognomeAssistito}</p>
      <p><strong>Codice Contratto:</strong> ${contractCode}</p>
      <p><strong>Importo:</strong> €${pricing.setupTotale} (IVA inclusa)</p>
      <p><em>Firma manuale apposta dallo staff eCura</em></p>
    `
    
    // Salva contratto nel DB — colonne reali della tabella contracts
    // Usa codice univoco con timestamp per evitare UNIQUE constraint violation
    const contractCodeUnique = `${contractCode}-M${timestamp}`

    // INSERT con tutte le colonne NOT NULL obbligatorie della tabella contracts reale
    await c.env.DB.prepare(`
      INSERT INTO contracts (
        id, leadId, codice_contratto,
        tipo_contratto, template_utilizzato,
        contenuto_html,
        prezzo_mensile, durata_mesi, prezzo_totale,
        servizio, piano,
        status, signature_data, signature_method, signed_at,
        created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      contractId,
      leadId,
      contractCodeUnique,
      'MANUALE',
      'manual-sign',
      contractHtml,
      (pricing.setupBase / 12).toFixed(2),  // prezzo_mensile = IVA ESCLUSA / 12
      12,
      pricing.setupBase,  // ✅ prezzo_totale = IVA ESCLUSA (setupBase, non setupTotale)
      servizio,
      piano,
      'SIGNED',
      'Firma Manuale Staff eCura',
      'manual',
      new Date().toISOString(),
      new Date().toISOString(),
      new Date().toISOString()
    ).run()

    // Aggiorna lead
    await c.env.DB.prepare(`
      UPDATE leads SET 
        vuoleContratto = 'Si',
        status = 'CONTRACT_SIGNED',
        updated_at = ?
      WHERE id = ?
    `).bind(new Date().toISOString(), leadId).run()
    
    console.log(`✅ [MANUAL-SIGN] Contratto ${contractCode} firmato manualmente`)
    
    // Trigger proforma automatica
    try {
      console.log(`📊 [MANUAL-SIGN→PROFORMA] Avvio workflow proforma`)
      
      const year = new Date().getFullYear()
      const month = String(new Date().getMonth() + 1).padStart(2, '0')
      const random = Math.random().toString(36).substring(2, 6).toUpperCase()
      const numeroProforma = `PRF${year}${month}-${random}`
      
      // ✅ IVA: calcola con aliquota corretta (4% Legge 104 o 22% standard)
      const ivaRateManual = lead.iva_agevolata ? 0.04 : 0.22
      const prezzoBaseManual = pricing.setupBase  // IVA ESCLUSA
      const prezzoIvaInclusa = Math.round(prezzoBaseManual * (1 + ivaRateManual) * 100) / 100

      // Fetch rate di pagamento (se rateizzazione attiva)
      let rateManualProforma: Array<{ numero_rata: number; importo: number; data_scadenza: string; status: string }> = []
      if (lead.rateizzazione_attiva) {
        try {
          const rateRowsManual = await c.env.DB.prepare(
            `SELECT numero_rata, importo, data_scadenza, status FROM rate_pagamento WHERE lead_id = ? ORDER BY numero_rata ASC`
          ).bind(leadId).all()
          rateManualProforma = (rateRowsManual?.results || []) as any[]
          console.log(`📅 [MANUAL-SIGN→PROFORMA] Rate trovate: ${rateManualProforma.length}`)
        } catch (e) {
          console.warn(`⚠️ [MANUAL-SIGN→PROFORMA] Errore fetch rate:`, e)
        }
      }

      const proformaData = {
        proformaId: numeroProforma,  // usa numero_proforma come ID nel link (cercato dal GET /api/proforma/:id)
        numeroProforma,
        proformaPdfUrl: '',
        tipoServizio: piano,
        servizio: servizio,
        prezzoBase: prezzoBaseManual,        // IVA ESCLUSA (es. €390)
        prezzoIvaInclusa: prezzoIvaInclusa,  // IVA INCLUSA con aliquota corretta (es. €405,60 al 4%)
        dataScadenza: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
        riserva_dominio: Boolean(lead.riserva_dominio),
        rateizzazione_attiva: Boolean(lead.rateizzazione_attiva),
        rateizzazione_note: lead.rateizzazione_note || '',
        rate: rateManualProforma
      }
      
      // ✅ REGOLA INTESTATARIO: rispetta la scelta del form
      const intestatarioManual = lead.intestatarioContratto || 'richiedente'
      let nomeProformaManual: string, cognomeProformaManual: string
      let cfProformaManual: string, indirizzoProformaManual: string
      let cittaProformaManual: string, capProformaManual: string, provinciaProformaManual: string

      if (intestatarioManual === 'assistito') {
        nomeProformaManual      = lead.nomeAssistito        || ''
        cognomeProformaManual   = lead.cognomeAssistito     || ''
        cfProformaManual        = lead.cfAssistito          || ''
        indirizzoProformaManual = lead.indirizzoAssistito   || ''
        cittaProformaManual     = lead.cittaAssistito       || ''
        capProformaManual       = lead.capAssistito         || ''
        provinciaProformaManual = lead.provinciaAssistito   || ''
      } else {
        nomeProformaManual      = lead.nomeRichiedente       || ''
        cognomeProformaManual   = lead.cognomeRichiedente    || ''
        cfProformaManual        = lead.cfIntestatario || lead.codiceFiscaleIntestatario || ''
        indirizzoProformaManual = lead.indirizzoIntestatario || ''
        cittaProformaManual     = lead.cittaIntestatario     || ''
        capProformaManual       = lead.capIntestatario       || ''
        provinciaProformaManual = lead.provinciaIntestatario || ''
      }
      console.log(`👤 [MANUAL-SIGN→PROFORMA] intestatario=${intestatarioManual}: ${nomeProformaManual} ${cognomeProformaManual}, CF=${cfProformaManual}`)

      // Salva proforma nel DB — schema reale verificato con PRAGMA
      // ✅ REGOLA: prezzo_totale = IVA ESCLUSA (setupBase), prezzo_mensile = setupBase/12
      await c.env.DB.prepare(`
        INSERT INTO proforma (
          contract_id, leadId, numero_proforma,
          data_emissione, data_scadenza,
          cliente_nome, cliente_cognome, cliente_email, cliente_telefono,
          cliente_indirizzo, cliente_citta, cliente_cap, cliente_provincia, cliente_codice_fiscale,
          tipo_servizio, prezzo_mensile, durata_mesi, prezzo_totale,
          iva_agevolata, status, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(
        contractId || '',
        leadId,
        numeroProforma,
        new Date().toISOString().split('T')[0],
        new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        lead.nomeRichiedente || '',
        lead.cognomeRichiedente || '',
        lead.email || '',
        lead.telefono || '',
        indirizzoProformaManual,
        cittaProformaManual,
        capProformaManual,
        provinciaProformaManual,
        cfProformaManual,  // ✅ CF ASSISTITO prioritario
        servizio,
        (prezzoBaseManual / 12).toFixed(2),  // ✅ IVA ESCLUSA / 12
        12,
        prezzoBaseManual,  // ✅ IVA ESCLUSA
        lead.iva_agevolata ? 1 : 0,  // ✅ salva iva_agevolata
        'SENT',
        new Date().toISOString(),
        new Date().toISOString()
      ).run()
      
      // Invia email proforma
      await WorkflowEmailManager.inviaEmailProforma(lead, proformaData, c.env, c.env.DB)
      
      console.log(`✅ [MANUAL-SIGN→PROFORMA] Proforma ${numeroProforma} inviata`)
    } catch (proformaError) {
      console.error(`⚠️ [MANUAL-SIGN→PROFORMA] Errore:`, proformaError)
    }
    
    return c.json({
      success: true,
      message: `Contratto ${contractCode} firmato manualmente e proforma inviata`,
      contractId,
      contractCode
    })
    
  } catch (error) {
    console.error('❌ [MANUAL-SIGN] Errore:', error)
    return c.json({
      success: false,
      error: 'Errore durante firma manuale',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

/**
 * 2. INVIO PROFORMA MANUALE
 * Invia proforma a lead che ha già contratto firmato
 */
app.post('/api/leads/:id/send-proforma', async (c) => {
  const leadId = c.req.param('id')
  
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    
    if (!lead) {
      return c.json({ success: false, error: 'Lead non trovato' }, 404)
    }
    
    console.log(`💰 [SEND-PROFORMA] Invio proforma manuale per lead ${leadId}`)
    
    // ✅ STEP 1: Cerca contratto firmato per questo lead (fonte primaria)
    const contract = await c.env.DB.prepare(`
      SELECT servizio, piano 
      FROM contracts 
      WHERE leadId = ? AND status = 'firmato'
      ORDER BY created_at DESC 
      LIMIT 1
    `).bind(leadId).first() as any
    
    // ✅ STEP 2: Determina servizio e piano dalla fonte corretta
    let servizio: string
    let piano: string
    
    if (contract && contract.servizio && contract.piano) {
      // Usa dati dal contratto firmato (priorità massima)
      servizio = contract.servizio
      piano = contract.piano
      console.log(`✅ [PRICING] Dati da CONTRATTO: ${servizio} - ${piano}`)
    } else if (lead.servizio && lead.piano) {
      // Fallback: usa dati dal lead
      servizio = lead.servizio
      piano = lead.piano
      console.log(`⚠️ [PRICING] Dati da LEAD (no contratto): ${servizio} - ${piano}`)
    } else {
      // Ultimo fallback: usa default più comune
      servizio = 'eCura PRO'
      piano = 'BASE'
      console.warn(`⚠️ [PRICING] ATTENZIONE: usando default PRO BASE (nessun dato trovato in DB)`)
    }
    
    console.log(`📊 [PRICING] FINALE - Servizio: "${servizio}", Piano: "${piano}"`)
    
    // Calcola prezzi
    const servizioType = servizio.replace(/^eCura\s+/i, '').trim().toUpperCase()
    console.log(`📊 [PRICING] Tipo servizio calcolato: "${servizioType}"`)
    
    const { calculatePrice } = await import('./modules/pricing-calculator')
    const pricing = calculatePrice(servizioType, piano.toUpperCase())
    
    console.log(`💰 [PRICING] Prezzo calcolato: ${servizioType} ${piano.toUpperCase()} = €${pricing.setupTotale.toFixed(2)}`)
    console.log(`💰 [PRICING] Dettaglio: base €${pricing.setupBase} + IVA €${pricing.setupIva} = TOT €${pricing.setupTotale}`)

    
    // Genera numero proforma (l'ID sarà auto-generato da SQLite)
    const year = new Date().getFullYear()
    const month = String(new Date().getMonth() + 1).padStart(2, '0')
    const random = Math.random().toString(36).substring(2, 6).toUpperCase()
    const numeroProforma = `PRF${year}${month}-${random}`

    // Fetch rate di pagamento (se rateizzazione attiva)
    let rateSendProforma: Array<{ numero_rata: number; importo: number; data_scadenza: string; status: string }> = []
    if (lead.rateizzazione_attiva) {
      try {
        const rateRowsSend = await c.env.DB.prepare(
          `SELECT numero_rata, importo, data_scadenza, status FROM rate_pagamento WHERE lead_id = ? ORDER BY numero_rata ASC`
        ).bind(leadId).all()
        rateSendProforma = (rateRowsSend?.results || []) as any[]
        console.log(`📅 [SEND-PROFORMA] Rate trovate: ${rateSendProforma.length}`)
      } catch (e) {
        console.warn(`⚠️ [SEND-PROFORMA] Errore fetch rate:`, e)
      }
    }

    const proformaData = {
      proformaId: '', // Sarà popolato dopo INSERT/UPDATE
      numeroProforma,
      proformaPdfUrl: '',
      tipoServizio: piano,
      servizio: servizio,
      prezzoBase: pricing.setupBase,
      prezzoIvaInclusa: pricing.setupTotale,
      dataScadenza: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // ✅ 3 giorni massimo
      riserva_dominio: Boolean(lead.riserva_dominio),
      rateizzazione_attiva: Boolean(lead.rateizzazione_attiva),
      rateizzazione_note: lead.rateizzazione_note || '',
      rate: rateSendProforma
    }
    
    // ✅ LOGICA INTESTATARIO: se 'assistito' tutti i campi dall'assistito, altrimenti dal richiedente
    const intestatarioSendProforma = lead.intestatarioContratto || 'richiedente'
    let nomeSendProforma: string, cognomeSendProforma: string
    let cfSendProforma: string, indirizzoSendProforma: string
    let cittaSendProforma: string, capSendProforma: string, provinciaSendProforma: string

    if (intestatarioSendProforma === 'assistito') {
      nomeSendProforma      = lead.nomeAssistito        || ''
      cognomeSendProforma   = lead.cognomeAssistito     || ''
      cfSendProforma        = lead.cfAssistito          || ''
      indirizzoSendProforma = lead.indirizzoAssistito   || ''
      cittaSendProforma     = lead.cittaAssistito       || ''
      capSendProforma       = lead.capAssistito         || ''
      provinciaSendProforma = lead.provinciaAssistito   || ''
    } else {
      nomeSendProforma      = lead.nomeRichiedente       || ''
      cognomeSendProforma   = lead.cognomeRichiedente    || ''
      cfSendProforma        = lead.cfIntestatario || lead.codiceFiscaleIntestatario || ''
      indirizzoSendProforma = lead.indirizzoIntestatario || ''
      cittaSendProforma     = lead.cittaIntestatario     || ''
      capSendProforma       = lead.capIntestatario       || ''
      provinciaSendProforma = lead.provinciaIntestatario || ''
    }
    console.log(`👤 [SEND-PROFORMA] Intestatario: ${intestatarioSendProforma} → ${nomeSendProforma} ${cognomeSendProforma} CF:${cfSendProforma}`)

    // ✅ VERIFICA SE ESISTE GIÀ UNA PROFORMA PER QUESTO LEAD
    // Lo schema in produzione usa: id, contract_id, leadId, numero_proforma, data_emissione, data_scadenza
    const existingProforma = await c.env.DB.prepare(
      'SELECT * FROM proforma WHERE leadId = ? ORDER BY data_emissione DESC LIMIT 1'
    ).bind(leadId).first() as any
    
    let proformaIdGenerated: string | null = null
    
    if (existingProforma) {
      // 🔄 ESISTE GIÀ: fai UPDATE
      // Se id è NULL, genera uno nuovo
      const proformaId = existingProforma.id || `PRF-${Date.now()}-${Math.random().toString(36).substring(2, 9).toUpperCase()}`
      
      console.log(`🔄 [SEND-PROFORMA] Proforma esistente trovata (ID ${existingProforma.id || 'NULL'}), aggiorno con ID ${proformaId}...`)
      
      // ✅ NOTA SCHEMA: tipo_servizio contiene il SERVIZIO COMPLETO (es. "eCura PREMIUM")
      // Il piano viene memorizzato in prezzo_mensile come flag: BASE < 500, AVANZATO >= 500
      await c.env.DB.prepare(`
        UPDATE proforma 
        SET id = ?,
            numero_proforma = ?,
            data_emissione = ?,
            data_scadenza = ?,
            tipo_servizio = ?,
            prezzo_mensile = ?,
            prezzo_totale = ?,
            cliente_nome = ?,
            cliente_cognome = ?,
            cliente_codice_fiscale = ?,
            cliente_indirizzo = ?,
            cliente_citta = ?,
            cliente_cap = ?,
            cliente_provincia = ?
        WHERE leadId = ? AND numero_proforma = ?
      `).bind(
        proformaId,
        numeroProforma,
        new Date().toISOString().split('T')[0],
        new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], // ✅ 3 giorni
        servizio,    // ✅ SERVIZIO COMPLETO (es. "eCura PREMIUM")
        (pricing.setupBase / 12).toFixed(2), // prezzo_mensile (IVA ESCLUSA / 12)
        pricing.setupBase, // ✅ REGOLA UNIVERSALE: prezzo_totale = IVA ESCLUSA
        nomeSendProforma,
        cognomeSendProforma,
        cfSendProforma,
        indirizzoSendProforma,
        cittaSendProforma,
        capSendProforma,
        provinciaSendProforma,
        leadId,
        existingProforma.numero_proforma
      ).run()
      
      proformaIdGenerated = proformaId
      proformaData.proformaId = proformaId
      console.log(`✅ [SEND-PROFORMA] Proforma ${numeroProforma} aggiornata con ID ${proformaId}`)
      
    } else {
      // ✅ NON ESISTE: fai INSERT con schema URGENT (quello in produzione)
      console.log(`📝 [SEND-PROFORMA] Nessuna proforma esistente, creo nuova...`)
      
      const proformaId = `PRF-${Date.now()}-${Math.random().toString(36).substring(2, 9).toUpperCase()}`
      
      // id è INTEGER AUTOINCREMENT in produzione — non va specificato
      const insertResult = await c.env.DB.prepare(`
        INSERT INTO proforma (
          contract_id, leadId, numero_proforma,
          data_emissione, data_scadenza,
          cliente_nome, cliente_cognome, cliente_email, cliente_telefono,
          cliente_codice_fiscale, cliente_indirizzo, cliente_citta, cliente_cap, cliente_provincia,
          tipo_servizio, prezzo_mensile, durata_mesi, prezzo_totale,
          iva_agevolata, status, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(
        'MANUAL',
        leadId,
        numeroProforma,
        new Date().toISOString().split('T')[0],
        new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        nomeSendProforma,
        cognomeSendProforma,
        lead.email || '',
        lead.telefono || '',
        cfSendProforma,
        indirizzoSendProforma,
        cittaSendProforma,
        capSendProforma,
        provinciaSendProforma,
        servizio,
        (pricing.setupBase / 12).toFixed(2),  // ✅ IVA ESCLUSA / 12
        12,
        pricing.setupBase,  // ✅ IVA ESCLUSA (non setupTotale!)
        lead.iva_agevolata ? 1 : 0,
        'DRAFT',
        new Date().toISOString(),
        new Date().toISOString()
      ).run()
      
      proformaIdGenerated = numeroProforma  // id INTEGER autoincrement, usiamo numero_proforma
      proformaData.proformaId = numeroProforma
      console.log(`✅ [SEND-PROFORMA] Proforma ${numeroProforma} creata`)
    }
    
    // Invia email (con gestione errore graceful)
    const { inviaEmailProforma } = await import('./modules/workflow-email-manager')
    
    let emailSuccess = false
    let emailError = ''
    
    try {
      const result = await inviaEmailProforma(lead, proformaData, c.env, c.env.DB)
      
      if (result.success) {
        emailSuccess = true
        // Aggiorna lead status solo se email inviata con successo
        await c.env.DB.prepare('UPDATE leads SET status = ? WHERE id = ?')
          .bind('PROFORMA_SENT', leadId).run()
        
        console.log(`✅ [SEND-PROFORMA] Proforma ${numeroProforma} inviata`)
      } else {
        emailError = result.errors.join(', ')
        console.warn(`⚠️ [SEND-PROFORMA] Email fallita: ${emailError}`)
      }
    } catch (emailErr) {
      emailError = emailErr instanceof Error ? emailErr.message : String(emailErr)
      console.error(`❌ [SEND-PROFORMA] Errore invio email:`, emailErr)
    }
    
    // Rispondi sempre con successo (proforma salvata nel DB)
    return c.json({
      success: true,
      message: emailSuccess 
        ? `Proforma ${numeroProforma} inviata con successo`
        : `Proforma ${numeroProforma} creata, ma email non inviata: ${emailError}`,
      proformaId: proformaIdGenerated,
      numeroProforma,
      importo: pricing.setupTotale.toFixed(2),
      servizio: servizio,     // ✅ es. "eCura PREMIUM"
      piano: piano,           // ✅ es. "AVANZATO"
      emailSent: emailSuccess,
      emailError: emailSuccess ? undefined : emailError
    })
    
  } catch (error) {
    console.error('❌ [SEND-PROFORMA] Errore:', error)
    return c.json({
      success: false,
      error: 'Errore durante invio proforma',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// ============================================================
// POST /api/leads/:id/send-benvenuto
// Invia manualmente email di benvenuto al lead (con IVA agevolata e dispositivo corretti)
// ============================================================
app.post('/api/leads/:id/send-benvenuto', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'Database non configurato' }, 500)

    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    if (!lead) return c.json({ success: false, error: 'Lead non trovato' }, 404)

    const { inviaEmailBenvenuto } = await import('./modules/workflow-email-manager')
    const result = await inviaEmailBenvenuto(lead as any, c.env)

    if (result.success) {
      console.log(`✅ [SEND-BENVENUTO] Email inviata a ${lead.email}`)
      return c.json({ success: true, message: `Email benvenuto inviata a ${lead.email}` })
    } else {
      return c.json({ success: false, error: result.errors?.join(', ') || 'Errore invio' }, 500)
    }
  } catch (error) {
    console.error('❌ [SEND-BENVENUTO]', error)
    return c.json({ success: false, error: error instanceof Error ? error.message : String(error) }, 500)
  }
})

// ============================================================
// POST /api/leads/:id/genera-ddt
// Genera DDT, crea record dispositivo, crea record assistito, invia email a info@ecura.it
// Body: { imei, telefonoSim, numeroDdt?, dataConsegna?, note? }
// ============================================================
app.post('/api/leads/:id/genera-ddt', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'Database non configurato' }, 500)

    const body = await c.req.json() as any
    const { imei: imeiInput, telefonoSim, numeroDdt, dataConsegna, note } = body
    // IMEI è opzionale: se il DDT esiste già lo prendiamo da lì

    // --- 1. Carica lead + contratto + configurazione ---
    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    if (!lead) return c.json({ success: false, error: 'Lead non trovato' }, 404)

    // Configurazione compilata dal cliente (fonte di verità per dati assistito)
    const config = await c.env.DB.prepare(
      `SELECT * FROM configurations WHERE leadId = ? ORDER BY updated_at DESC LIMIT 1`
    ).bind(leadId).first() as any

    const contract = await c.env.DB.prepare(
      `SELECT * FROM contracts WHERE leadId = ? AND status = 'firmato' ORDER BY created_at DESC LIMIT 1`
    ).bind(leadId).first() as any

    // --- 2. Determina servizio/piano e dispositivo ---
    const servizio = contract?.servizio || lead.servizio || 'eCura PRO'
    const piano    = contract?.piano    || lead.piano    || 'BASE'
    const servizioUpper = servizio.replace(/^eCura\s+/i,'').trim().toUpperCase() as 'FAMILY'|'PRO'|'PREMIUM'
    const pianoUpper    = (piano.toUpperCase() === 'AVANZATO' ? 'AVANZATO' : 'BASE') as 'BASE'|'AVANZATO'

    const { getPricing } = await import('./modules/ecura-pricing')
    const pricing = getPricing(servizioUpper, pianoUpper)
    const dispositivo = pricing?.dispositivo || 'SiDLY Care PRO'

    // --- 3. Determina intestatario (assistito o richiedente) ---
    const intestatario = lead.intestatarioContratto || 'richiedente'
    const nomeDestinatario = intestatario === 'assistito'
      ? `${lead.nomeAssistito || ''} ${lead.cognomeAssistito || ''}`.trim()
      : `${lead.nomeRichiedente || ''} ${lead.cognomeRichiedente || ''}`.trim()
    const indirizzoDestinatario = intestatario === 'assistito'
      ? lead.indirizzoAssistito || lead.indirizzoIntestatario || ''
      : lead.indirizzoIntestatario || ''
    const capDestinatario = intestatario === 'assistito'
      ? lead.capAssistito || lead.capIntestatario || ''
      : lead.capIntestatario || ''
    const cittaDestinatario = intestatario === 'assistito'
      ? lead.cittaAssistito || lead.cittaIntestatario || ''
      : lead.cittaIntestatario || ''
    const provinciaDestinatario = intestatario === 'assistito'
      ? lead.provinciaAssistito || lead.provinciaIntestatario || ''
      : lead.provinciaIntestatario || ''

    // --- 4. Numero DDT: formato "DDT-NNN-AAAA" (es. DDT-008-2026) ---
    const annoCorrente = new Date().getFullYear()

    // Helper: normalizza qualsiasi input nel formato DDT-NNN-AAAA
    const formatNumeroDdt = (n: number, anno: number) =>
      `DDT-${String(n).padStart(3, '0')}-${anno}`

    let numDdt: string
    if (numeroDdt && String(numeroDdt).trim()) {
      const raw = String(numeroDdt).trim()
      // Se già nel formato DDT-NNN-AAAA, usalo as-is
      if (/^DDT-\d+-\d{4}$/i.test(raw)) {
        numDdt = raw.toUpperCase()
      } else {
        // Altrimenti estrai il numero progressivo e formatta
        const n = parseInt(raw.replace(/\D/g, '')) || 1
        numDdt = formatNumeroDdt(n, annoCorrente)
      }
    } else {
      // Auto-incremento: MAX progressivo tra tutti i DDT dell'anno corrente
      const allDdts = await c.env.DB.prepare(`SELECT numero_ddt FROM ddts`).all() as any
      const nums = (allDdts?.results || [])
        .map((r: any) => {
          const m = String(r.numero_ddt).match(/DDT-(\d+)-(\d{4})/i)
          return m ? parseInt(m[1]) : 0
        })
        .filter((n: number) => n > 0)
      const maxNum = nums.length > 0 ? Math.max(...nums) : 0
      numDdt = formatNumeroDdt(maxNum + 1, annoCorrente)
    }

    // Verifica unicità: se esiste già incrementa il progressivo
    const existing = await c.env.DB.prepare(
      `SELECT id FROM ddts WHERE numero_ddt = ? LIMIT 1`
    ).bind(numDdt).first() as any
    if (existing) {
      const m = numDdt.match(/DDT-(\d+)-\d{4}/i)
      const n = m ? parseInt(m[1]) + 1 : 1
      numDdt = formatNumeroDdt(n, annoCorrente)
    }

    // Data DDT: è la data del DDT/consegna — indipendente dalla data firma contratto.
    // Se passata esplicitamente dal frontend usala, altrimenti usa la data odierna
    // in fuso Europe/Rome (non UTC, altrimenti alle 23:xx IT il giorno è già cambiato).
    const todayItaly = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Rome' }).format(new Date())
    const dataDoc = dataConsegna || todayItaly
    const codiceContratto = contract?.codice_contratto || contract?.id || `CTR-${leadId}`
    const baseUrl = new URL(c.req.url).origin

    // --- 5. Controlla se esiste già un DDT per questo lead (note LIKE 'LeadID:X%') ---
    const existingDDT = await c.env.DB.prepare(
      `SELECT id, numero_ddt, serial_number FROM ddts WHERE note LIKE ? ORDER BY created_at DESC LIMIT 1`
    ).bind(`LeadID:${leadId}%`).first() as any

    let ddtId: string
    let pdfUrl: string
    let ddtCreated = false
    // IMEI effettivo: se DDT esiste già, usa il suo serial_number (fonte di verità)
    // ignorando quello inserito dall'utente che potrebbe essere di un altro dispositivo
    const imei = existingDDT?.serial_number || imeiInput

    if (existingDDT) {
      // DDT già esiste: riusa, non duplicare — IMEI dal DDT, non dall'utente
      ddtId = existingDDT.id
      pdfUrl = `${baseUrl}/api/ddts/${ddtId}/pdf-print`
      numDdt = existingDDT.numero_ddt
      console.log(`ℹ️ [GENERA-DDT] DDT già esistente per LeadID:${leadId} → ${numDdt} (IMEI: ${imei}), skip INSERT`)
    } else {
      // DDT non esiste: serve IMEI — se non fornito, chiedi al frontend
      if (!imei) {
        return c.json({ success: false, needsImei: true, error: 'IMEI richiesto per creare nuovo DDT' })
      }
      ddtId = `DDT-${leadId}-${Date.now()}`
      pdfUrl = `${baseUrl}/api/ddts/${ddtId}/pdf-print`
      const noteConLeadId = `LeadID:${leadId}${note ? ' | ' + note : ''}`
      // Esegui migration sim_number se non esiste (idempotente)
      try { await c.env.DB.prepare(`ALTER TABLE ddts ADD COLUMN sim_number TEXT`).run() } catch (_) {}
      await c.env.DB.prepare(`
        INSERT INTO ddts (
          id, numero_ddt, contract_code,
          data_spedizione, data_consegna,
          destinatario_nome, destinatario_indirizzo, destinatario_cap,
          destinatario_citta, destinatario_provincia,
          destinatario_email, destinatario_telefono,
          dispositivo, serial_number, sim_number, quantita,
          status, pdf_url, pdf_generated, note,
          created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))
      `).bind(
        ddtId, numDdt, codiceContratto,
        dataDoc, dataDoc,
        nomeDestinatario, indirizzoDestinatario, capDestinatario,
        cittaDestinatario, provinciaDestinatario,
        lead.email || '', lead.telefono || '',
        dispositivo, imei, telefonoSim || null, 1,
        'CONSEGNATO', pdfUrl, 1, noteConLeadId
      ).run()
      ddtCreated = true
      console.log(`✅ [GENERA-DDT] DDT ${numDdt} inserito (IMEI: ${imei}, PDF: ${pdfUrl})`)
    }

    // --- 6. Dispositivo: aggiorna solo se l'IMEI corrisponde a quello del DDT ---
    const now = new Date().toISOString()
    const existingDevice = await c.env.DB.prepare(
      `SELECT id FROM dispositivi WHERE serial_number = ? LIMIT 1`
    ).bind(imei).first() as any

    if (existingDevice) {
      await c.env.DB.prepare(
        `UPDATE dispositivi SET lead_id=?, status='ASSIGNED', assigned_at=? WHERE serial_number=?`
      ).bind(leadId, now, imei).run()
      console.log(`✅ [GENERA-DDT] Dispositivo S/N ${imei} aggiornato`)
    } else {
      await c.env.DB.prepare(
        `INSERT INTO dispositivi (serial_number, modello, lead_id, status, assigned_at, created_at) VALUES (?, ?, ?, 'ASSIGNED', ?, ?)`
      ).bind(imei, dispositivo, leadId, now, now).run()
      console.log(`✅ [GENERA-DDT] Dispositivo S/N ${imei} creato`)
    }

    // --- 7. Crea / aggiorna record assistito ---
    // FONTE DI VERITÀ (priorità decrescente):
    //   1. configurations (compilato dal cliente nel form di configurazione)
    //   2. leads (dati raccolti al momento della lead)
    // Assistito  = il paziente        → config.nome_assistito / lead.nomeAssistito
    // Caregiver  = chi ha compilato   → config.contatto1_nome  / lead.nomeRichiedente
    // Parentela  = rapporto assistito→caregiver → lead.parentelaAssistito

    // Dati assistito — configurations è la fonte di verità, leads è il fallback
    const nomeAssistitoField    = config?.nome_assistito    || lead.nomeAssistito    || lead.nomeRichiedente    || ''
    const cognomeAssistitoField = config?.cognome_assistito || lead.cognomeAssistito || lead.cognomeRichiedente || ''
    const nomeCaregiverField    = config?.contatto1_nome    || lead.nomeRichiedente  || ''
    const cognomeCaregiverField = config?.contatto1_cognome || lead.cognomeRichiedente || ''
    const parentelaField        = lead.parentelaAssistito   || 'Caregiver'
    const emailAssistito        = config?.email             || lead.email            || ''
    const telefonoAssistito     = config?.telefono          || lead.telefono         || ''
    const nomeCompleto          = `${nomeAssistitoField} ${cognomeAssistitoField}`.trim()
    // Campi aggiuntivi da configurations (già presenti nel DB assistiti)
    const dataNascita           = config?.data_nascita      || lead.dataNascitaAssistito || null
    const indirizzoField        = config?.indirizzo         || lead.indirizzoAssistito   || null
    const comuneField           = lead.cittaAssistito       || null
    const codiceFiscale         = lead.cfAssistito          || null
    const pesoField             = config?.peso              || null
    const altezzaField          = config?.altezza           || null
    const caregiverTelefono     = config?.contatto1_telefono || null

    // Codice standard: ASS-COGNOME-timestamp  (es. ASS-BADANOLITTARDI-1749876543210)
    const codiceAssistito = `ASS-${(cognomeAssistitoField || nomeAssistitoField || 'UNKNOWN').toUpperCase().replace(/[^A-Z]/g, '')}-${Date.now()}`

    // Assicura che le colonne extra esistano (ALTER TABLE idempotente)
    const colsToAdd = ['imei TEXT', 'nome_assistito TEXT', 'cognome_assistito TEXT',
      'nome_caregiver TEXT', 'cognome_caregiver TEXT', 'parentela_caregiver TEXT',
      'servizio TEXT', 'piano TEXT']
    for (const colDef of colsToAdd) {
      try {
        await c.env.DB.prepare(`ALTER TABLE assistiti ADD COLUMN ${colDef}`).run()
      } catch (_) { /* già esiste — ok */ }
    }

    const existingAssistito = await c.env.DB.prepare(
      `SELECT id, codice FROM assistiti WHERE lead_id=? LIMIT 1`
    ).bind(leadId).first() as any

    if (!existingAssistito) {
      await c.env.DB.prepare(`
        INSERT INTO assistiti (
          codice, nome, nome_assistito, cognome_assistito,
          nome_caregiver, cognome_caregiver, parentela_caregiver,
          email, telefono, imei, servizio, piano, lead_id,
          data_nascita, indirizzo, comune, codice_fiscale,
          peso, altezza, caregiver_nome, caregiver_telefono,
          status, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ATTIVO', datetime('now'), datetime('now'))
      `).bind(
        codiceAssistito, nomeCompleto,
        nomeAssistitoField, cognomeAssistitoField,
        nomeCaregiverField, cognomeCaregiverField,
        parentelaField,
        emailAssistito, telefonoAssistito,
        imei, servizio, piano, leadId,
        dataNascita, indirizzoField, comuneField, codiceFiscale,
        pesoField, altezzaField,
        nomeCaregiverField, caregiverTelefono
      ).run()
      console.log(`✅ [GENERA-DDT] Assistito creato: ${codiceAssistito} — ${nomeCompleto} (config: ${!!config})`)
    } else {
      // UPDATE completo — include tutti i campi esistenti + status='ATTIVO'
      await c.env.DB.prepare(`
        UPDATE assistiti SET
          nome=?, nome_assistito=?, cognome_assistito=?,
          nome_caregiver=?, cognome_caregiver=?, parentela_caregiver=?,
          email=?, telefono=?, imei=?, servizio=?, piano=?,
          data_nascita=?, indirizzo=?, comune=?, codice_fiscale=?,
          peso=?, altezza=?, caregiver_nome=?, caregiver_telefono=?,
          status='ATTIVO', updated_at=datetime('now')
        WHERE lead_id=?
      `).bind(
        nomeCompleto, nomeAssistitoField, cognomeAssistitoField,
        nomeCaregiverField, cognomeCaregiverField,
        parentelaField,
        emailAssistito, telefonoAssistito, imei, servizio, piano,
        dataNascita, indirizzoField, comuneField, codiceFiscale,
        pesoField, altezzaField,
        nomeCaregiverField, caregiverTelefono,
        leadId
      ).run()
      console.log(`✅ [GENERA-DDT] Assistito aggiornato (id=${existingAssistito.id}): ${nomeCompleto} → ATTIVO (config: ${!!config})`)
    }

    // --- 8. Invia email riepilogo DDT a info@ecura.it (con link PDF) ---
    const { EmailService } = await import('./modules/email-service')
    const emailSvc = EmailService.getInstance()
    const emailBody = `
      <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">
        <h2 style="color:#1e40af;border-bottom:2px solid #1e40af;padding-bottom:8px">
          DDT N° ${numDdt} — Nuovo Documento di Trasporto
        </h2>
        <table style="border-collapse:collapse;width:100%;margin-bottom:16px">
          <tr style="background:#f0f4ff"><td style="padding:8px 12px;font-weight:bold;width:40%">N° DDT</td><td style="padding:8px 12px"><strong>${numDdt}</strong></td></tr>
          <tr><td style="padding:8px 12px;font-weight:bold">Contratto</td><td style="padding:8px 12px">${codiceContratto}</td></tr>
          <tr style="background:#f0f4ff"><td style="padding:8px 12px;font-weight:bold">Destinatario</td><td style="padding:8px 12px">${nomeDestinatario}</td></tr>
          <tr><td style="padding:8px 12px;font-weight:bold">Indirizzo</td><td style="padding:8px 12px">${indirizzoDestinatario}, ${capDestinatario} ${cittaDestinatario}${provinciaDestinatario ? ' (' + provinciaDestinatario + ')' : ''}</td></tr>
          <tr style="background:#f0f4ff"><td style="padding:8px 12px;font-weight:bold">Dispositivo</td><td style="padding:8px 12px">${dispositivo}</td></tr>
          <tr><td style="padding:8px 12px;font-weight:bold">IMEI / S/N</td><td style="padding:8px 12px"><strong style="font-family:monospace">${imei}</strong></td></tr>
          <tr style="background:#f0f4ff"><td style="padding:8px 12px;font-weight:bold">Tel. SIM</td><td style="padding:8px 12px">${telefonoSim || '—'}</td></tr>
          <tr><td style="padding:8px 12px;font-weight:bold">Data Consegna</td><td style="padding:8px 12px">${dataDoc}</td></tr>
          ${note ? '<tr style="background:#f0f4ff"><td style="padding:8px 12px;font-weight:bold">Note</td><td style="padding:8px 12px">' + note + '</td></tr>' : ''}
        </table>
        <div style="text-align:center;margin:24px 0">
          <a href="${pdfUrl}" target="_blank"
             style="display:inline-block;padding:12px 28px;background:#1e40af;color:white;text-decoration:none;border-radius:6px;font-weight:bold;font-size:15px">
            Visualizza DDT (PDF)
          </a>
        </div>
        <p style="color:#666;font-size:11px;margin-top:16px;border-top:1px solid #eee;padding-top:12px">
          Assistito: ${nomeCompleto} | Servizio: ${servizio} ${piano}<br>
          Record registrati: Dispositivo ${imei} (ASSIGNED), Assistito ${codiceAssistito}
        </p>
      </div>
    `
    try {
      await emailSvc.sendEmail({
        to: 'info@ecura.it',
        from: 'info@ecura.it',
        subject: `DDT N° ${numDdt} — ${dispositivo} per ${nomeDestinatario}`,
        html: emailBody
      }, c.env)
      console.log(`✅ [GENERA-DDT] Email con link PDF inviata a info@ecura.it`)
    } catch (emailErr) {
      console.warn(`⚠️ [GENERA-DDT] Email non inviata (non bloccante): ${emailErr}`)
    }

    return c.json({
      success: true,
      message: ddtCreated
        ? `DDT N° ${numDdt} creato, dispositivo e assistito registrati`
        : `DDT N° ${numDdt} già esistente — solo assistito creato/aggiornato`,
      ddt: { id: ddtId, numero: numDdt, dispositivo, imei, pdfUrl, status: 'CONSEGNATO', existing: !ddtCreated },
      assistito: { codice: codiceAssistito, nome: nomeCompleto },
    })

  } catch (error) {
    console.error('❌ [GENERA-DDT]', error)
    return c.json({ success: false, error: error instanceof Error ? error.message : String(error) }, 500)
  }
})

// POST /api/leads/:id/fix-assistito
// Crea o aggiorna l'assistito di un lead leggendo configurations + lead + DDT
// Corregge status, nomi, caregiver, parentela su record esistenti errati
app.post('/api/leads/:id/fix-assistito', requireAuth, async (c) => {
  const leadId = c.req.param('id')
  try {
    if (!c.env?.DB) return c.json({ success: false, error: 'Database non configurato' }, 500)

    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    if (!lead) return c.json({ success: false, error: 'Lead non trovato' }, 404)

    // FONTE DI VERITÀ: configurations ha i dati compilati dal cliente
    const config = await c.env.DB.prepare(
      `SELECT * FROM configurations WHERE leadId = ? ORDER BY updated_at DESC LIMIT 1`
    ).bind(leadId).first() as any

    const contract = await c.env.DB.prepare(
      `SELECT * FROM contracts WHERE leadId = ? ORDER BY created_at DESC LIMIT 1`
    ).bind(leadId).first() as any

    // DDT: cerca per note (LeadID:X) poi per destinatario
    const ddtByNote = await c.env.DB.prepare(
      `SELECT * FROM ddts WHERE note LIKE ? ORDER BY created_at DESC LIMIT 1`
    ).bind(`LeadID:${leadId}%`).first() as any
    const ddtFallback = !ddtByNote
      ? await c.env.DB.prepare(
          `SELECT * FROM ddts WHERE destinatario_nome LIKE ? ORDER BY created_at DESC LIMIT 1`
        ).bind(`%${lead.cognomeRichiedente || lead.cognomeAssistito || ''}%`).first() as any
      : null
    const ddt = ddtByNote || ddtFallback

    const servizio = contract?.servizio || lead.servizio || lead.tipoServizio || 'eCura PRO'
    const piano    = contract?.piano    || lead.piano    || 'BASE'
    const imei     = ddt?.serial_number || ''

    // Dati assistito: configurations > leads
    const nomeAssistitoField    = config?.nome_assistito    || lead.nomeAssistito    || lead.nomeRichiedente    || ''
    const cognomeAssistitoField = config?.cognome_assistito || lead.cognomeAssistito || lead.cognomeRichiedente || ''
    const nomeCaregiverField    = config?.contatto1_nome    || lead.nomeRichiedente  || ''
    const cognomeCaregiverField = config?.contatto1_cognome || lead.cognomeRichiedente || ''
    const parentelaField        = lead.parentelaAssistito   || 'Caregiver'
    const emailAssistito        = config?.email    || lead.email    || ''
    const telefonoAssistito     = config?.telefono || lead.telefono || ''
    const nomeCompleto          = `${nomeAssistitoField} ${cognomeAssistitoField}`.trim()
    // Campi aggiuntivi da configurations / leads (colonne già presenti nel DB assistiti)
    const dataNascita           = config?.data_nascita || lead.dataNascitaAssistito || null
    const indirizzoField        = config?.indirizzo    || lead.indirizzoAssistito   || null
    const comuneField           = lead.cittaAssistito  || null
    const codiceFiscale         = lead.cfAssistito     || null
    const pesoField             = config?.peso         || null
    const altezzaField          = config?.altezza      || null
    const caregiverTelefono     = config?.contatto1_telefono || null

    const debugInfo = {
      leadId, configFound: !!config, ddtFound: !!ddt,
      nomeCompleto, servizio, piano, imei,
      caregiver: `${nomeCaregiverField} ${cognomeCaregiverField}`,
      parentela: parentelaField, dataNascita, indirizzo: indirizzoField
    }
    console.log('[FIX-ASSISTITO] debug:', JSON.stringify(debugInfo))

    // Assicura colonne extra (ALTER TABLE idempotente)
    const colsToAdd = ['imei TEXT', 'nome_assistito TEXT', 'cognome_assistito TEXT',
      'nome_caregiver TEXT', 'cognome_caregiver TEXT', 'parentela_caregiver TEXT',
      'servizio TEXT', 'piano TEXT']
    for (const colDef of colsToAdd) {
      try { await c.env.DB.prepare(`ALTER TABLE assistiti ADD COLUMN ${colDef}`).run() } catch (_) {}
    }

    const existingAssistito = await c.env.DB.prepare(
      `SELECT id, codice FROM assistiti WHERE lead_id=? LIMIT 1`
    ).bind(leadId).first() as any

    if (!existingAssistito) {
      // Codice standard: ASS-COGNOME-timestamp
      const codiceAssistito = `ASS-${(cognomeAssistitoField || nomeAssistitoField || 'UNKNOWN').toUpperCase().replace(/[^A-Z]/g, '')}-${Date.now()}`
      try {
        await c.env.DB.prepare(`
          INSERT INTO assistiti (
            codice, nome, nome_assistito, cognome_assistito,
            nome_caregiver, cognome_caregiver, parentela_caregiver,
            email, telefono, imei, servizio, piano, lead_id,
            data_nascita, indirizzo, comune, codice_fiscale,
            peso, altezza, caregiver_nome, caregiver_telefono,
            status, created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ATTIVO', datetime('now'), datetime('now'))
        `).bind(
          codiceAssistito, nomeCompleto,
          nomeAssistitoField, cognomeAssistitoField,
          nomeCaregiverField, cognomeCaregiverField,
          parentelaField,
          emailAssistito, telefonoAssistito,
          imei, servizio, piano, leadId,
          dataNascita, indirizzoField, comuneField, codiceFiscale,
          pesoField, altezzaField,
          nomeCaregiverField, caregiverTelefono
        ).run()
      } catch (insertErr: any) {
        // IMEI duplicato → ritenta senza imei
        console.warn('[FIX-ASSISTITO] INSERT fallito (IMEI dup?):', String(insertErr?.message || insertErr))
        await c.env.DB.prepare(`
          INSERT INTO assistiti (
            codice, nome, nome_assistito, cognome_assistito,
            nome_caregiver, cognome_caregiver, parentela_caregiver,
            email, telefono, servizio, piano, lead_id,
            data_nascita, indirizzo, comune, codice_fiscale,
            peso, altezza, caregiver_nome, caregiver_telefono,
            status, created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ATTIVO', datetime('now'), datetime('now'))
        `).bind(
          codiceAssistito, nomeCompleto,
          nomeAssistitoField, cognomeAssistitoField,
          nomeCaregiverField, cognomeCaregiverField,
          parentelaField,
          emailAssistito, telefonoAssistito,
          servizio, piano, leadId,
          dataNascita, indirizzoField, comuneField, codiceFiscale,
          pesoField, altezzaField,
          nomeCaregiverField, caregiverTelefono
        ).run()
      }
      const verify = await c.env.DB.prepare(`SELECT id FROM assistiti WHERE lead_id=?`).bind(leadId).first()
      return c.json({ success: true, action: 'created', nome: nomeCompleto, servizio, piano, imei, debug: debugInfo, verified: !!verify })
    } else {
      // UPDATE completo — tutti i campi + status='ATTIVO', imei separato per UNIQUE
      await c.env.DB.prepare(`
        UPDATE assistiti SET
          nome=?, nome_assistito=?, cognome_assistito=?,
          nome_caregiver=?, cognome_caregiver=?, parentela_caregiver=?,
          email=?, telefono=?, servizio=?, piano=?,
          data_nascita=?, indirizzo=?, comune=?, codice_fiscale=?,
          peso=?, altezza=?, caregiver_nome=?, caregiver_telefono=?,
          status='ATTIVO', updated_at=datetime('now')
        WHERE id=?
      `).bind(
        nomeCompleto, nomeAssistitoField, cognomeAssistitoField,
        nomeCaregiverField, cognomeCaregiverField,
        parentelaField,
        emailAssistito, telefonoAssistito, servizio, piano,
        dataNascita, indirizzoField, comuneField, codiceFiscale,
        pesoField, altezzaField,
        nomeCaregiverField, caregiverTelefono,
        existingAssistito.id
      ).run()
      // imei separato: UNIQUE constraint → non bloccante se duplicato
      if (imei) {
        try {
          await c.env.DB.prepare(`UPDATE assistiti SET imei=? WHERE id=?`).bind(imei, existingAssistito.id).run()
        } catch (_) {}
      }
      return c.json({ success: true, action: 'updated', nome: nomeCompleto, servizio, piano, imei, debug: debugInfo })
    }
  } catch (error) {
    console.error('❌ [FIX-ASSISTITO]', error)
    return c.json({ success: false, error: error instanceof Error ? error.message : String(error), leadId }, 500)
  }
})
/**
 * 3. PAGAMENTO MANUALE
 * Conferma pagamento ricevuto + TRIGGER EMAIL FORM CONFIGURAZIONE
 */
app.post('/api/leads/:id/manual-payment', async (c) => {
  const leadId = c.req.param('id')
  
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }
    
    const lead = await c.env.DB.prepare('SELECT * FROM leads WHERE id = ?').bind(leadId).first() as any
    
    if (!lead) {
      return c.json({ success: false, error: 'Lead non trovato' }, 404)
    }
    
    console.log(`✅ [MANUAL-PAYMENT] Conferma pagamento manuale per lead ${leadId}`)

    // ─── TRIGGER PROMOZIONE: se viene passato un codice_promo nel body, applicalo ───
    let scontoApplicato: any = null
    try {
      const bodyRaw = await c.req.raw.clone().text()
      let bodyParsed: any = {}
      try { bodyParsed = JSON.parse(bodyRaw) } catch (_) { /* body vuoto o non-JSON, ok */ }
      const codicePromo = bodyParsed?.codice_promo
      if (codicePromo && (!lead.codice_sconto)) {
        // Applica sconto promozionale solo se il lead non ha già uno sconto
        const promoResult = await applyDiscountToLead(
          c.env.DB, leadId, codicePromo.toUpperCase(), 'PROMOZIONE', 'manual-payment'
        )
        if (promoResult.success) {
          scontoApplicato = promoResult
          console.log(`🏷️ [MANUAL-PAYMENT] Sconto promozionale applicato: ${promoResult.message}`)
        } else {
          console.warn(`⚠️ [MANUAL-PAYMENT] Sconto promo non applicato: ${promoResult.message}`)
        }
      }
    } catch (scontoErr) {
      console.warn('⚠️ [MANUAL-PAYMENT] Errore lettura codice_promo:', scontoErr)
    }
    
    // Aggiorna proforma (se esiste)
    const proforma = await c.env.DB.prepare(
      'SELECT * FROM proforma WHERE leadId = ? ORDER BY created_at DESC LIMIT 1'
    ).bind(leadId).first() as any
    
    if (proforma) {
      await c.env.DB.prepare('UPDATE proforma SET status = ? WHERE id = ?')
        .bind('PAID', proforma.id).run()
      console.log(`✅ [MANUAL-PAYMENT] Proforma ${proforma.numero_proforma} marcata come pagata`)
    }
    
    // Genera codice cliente
    const codiceCliente = `CLI-${Date.now()}`
    
    // Aggiorna lead (rimuovo codice_cliente perché la colonna non esiste nella tabella)
    await c.env.DB.prepare(`
      UPDATE leads SET 
        status = 'PAYMENT_RECEIVED',
        updated_at = ?
      WHERE id = ?
    `).bind(new Date().toISOString(), leadId).run()
    
    // 🔥 TRIGGER: Invia email form configurazione
    console.log(`📧 [MANUAL-PAYMENT→CONFIG] Invio email form configurazione`)
    
    const { inviaEmailConfigurazionePostPagamento } = await import('./modules/workflow-email-manager')
    const result = await inviaEmailConfigurazionePostPagamento(
      { ...lead, codiceCliente },
      c.env,
      c.env.DB
    )
    
    if (result.success) {
      // Aggiorna status
      await c.env.DB.prepare('UPDATE leads SET status = ? WHERE id = ?')
        .bind('CONFIGURATION_SENT', leadId).run()
      
      console.log(`✅ [MANUAL-PAYMENT→CONFIG] Email configurazione inviata a ${lead.email}`)
      
      return c.json({
        success: true,
        message: `Pagamento confermato ed email configurazione inviata a ${lead.email}`,
        codiceCliente,
        ...(scontoApplicato ? {
          sconto_applicato: true,
          sconto_info: scontoApplicato.message,
          prezzo_finale: scontoApplicato.prezzo_finale
        } : {})
      })
    } else {
      throw new Error(result.errors.join(', '))
    }
    
  } catch (error) {
    console.error('❌ [MANUAL-PAYMENT] Errore:', error)
    return c.json({
      success: false,
      error: 'Errore durante conferma pagamento',
      details: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

