// POST /api/oneshot-fix-anagrafica-balzarotti-7rp4x
// Aggiorna i dati anagrafici di Giuliana Balzarotti nel lead LEAD-EXCEL-060 (richiedente: Paolo Magrì)
// Dati verificati da documento anagrafico ufficiale:
//   CF: BLZGLN35P67E504R → nata 27/09/1935 a Como (E504)
//   Residenza: Via Statale per Lecco 23/A — 22100 Como (CO)
// Il campo intestatarioContratto è 'assistito' → i campi *Intestatario* puntano all'assistita Giuliana
app.post('/api/oneshot-fix-anagrafica-balzarotti-7rp4x', async (c) => {
  if (!c.env?.DB) return c.json({ success: false, error: 'DB non configurato' }, 500)
  try {
    // Trova il lead: cerca per ID noto, poi per email caregiver, poi per nome assistito
    let lead: any = null
    lead = await c.env.DB.prepare("SELECT * FROM leads WHERE id = 'LEAD-EXCEL-060' LIMIT 1").first()
    if (!lead) lead = await c.env.DB.prepare("SELECT * FROM leads WHERE email = 'paolo@paolomagri.com' LIMIT 1").first()
    if (!lead) lead = await c.env.DB.prepare("SELECT * FROM leads WHERE nomeAssistito = 'Giuliana' AND cognomeAssistito = 'Balzarotti' LIMIT 1").first()
    if (!lead) return c.json({ success: false, error: 'Lead LEAD-EXCEL-060 (Balzarotti/Magrì) non trovato. Controlla il DB.' })

    console.log(`🔧 [ONESHOT-BALZAROTTI] Lead trovato: ${lead.id} — ${lead.nomeRichiedente} ${lead.cognomeRichiedente}`)

    // ── Dati verificati da documento anagrafico ufficiale ─────────────────────
    // CF BLZGLN35P67E504R → G=Giuliana, BLZ=Balzarotti, 35=1935, P=Settembre, 67=giorno F, E504=Como
    const cf              = 'BLZGLN35P67E504R'
    const indirizzo       = 'Via Statale per Lecco 23/A'
    const cap             = '22100'
    const citta           = 'Como'
    const provincia       = 'CO'
    const luogoNascita    = 'Como'
    const dataNascita     = '1935-09-27'   // P=Settembre, 67→67-40=27 (donna)

    // Aggiorna sia i campi assistito sia i campi intestatario
    // (intestatarioContratto = 'assistito' → il contratto usa i campi *Intestatario* per Giuliana)
    await c.env.DB.prepare(`
      UPDATE leads SET
        cfAssistito              = ?,
        indirizzoAssistito       = ?,
        capAssistito             = ?,
        cittaAssistito           = ?,
        provinciaAssistito       = ?,
        luogoNascitaAssistito    = ?,
        dataNascitaAssistito     = ?,
        cfIntestatario           = ?,
        indirizzoIntestatario    = ?,
        capIntestatario          = ?,
        cittaIntestatario        = ?,
        provinciaIntestatario    = ?,
        luogoNascitaIntestatario = ?,
        dataNascitaIntestatario  = ?,
        intestatarioContratto    = 'assistito',
        updated_at               = ?
      WHERE id = ?
    `).bind(
      cf, indirizzo, cap, citta, provincia, luogoNascita, dataNascita,
      cf, indirizzo, cap, citta, provincia, luogoNascita, dataNascita,
      new Date().toISOString(),
      lead.id
    ).run()

    console.log(`✅ [ONESHOT-BALZAROTTI] Anagrafica aggiornata per lead ${lead.id}`)

    return c.json({
      success: true,
      leadId: lead.id,
      messaggio: 'Anagrafica Giuliana Balzarotti aggiornata correttamente',
      datiImpostati: {
        cfAssistito: cf, cfIntestatario: cf,
        indirizzo, cap, citta, provincia,
        luogoNascita, dataNascita,
        intestatarioContratto: 'assistito'
      }
    })
  } catch (e: any) {
    return c.json({ success: false, error: e.message }, 500)
  }
})

// ─────────────────────────────────────────────────────────────────
// ONESHOT: Sincronizza template email_reminder_completamento → DB
// POST /api/oneshot-sync-reminder-ecura-9kx2q
// Nessuna auth richiesta — sostituisce "TeleMedCare" con "eCura" nel DB
// ─────────────────────────────────────────────────────────────────
app.post('/api/oneshot-sync-reminder-ecura-9kx2q', async (c) => {
  const templateName = 'email_reminder_completamento'
  try {
    if (!c.env?.DB) {
      return c.json({ success: false, error: 'Database non configurato' }, 500)
    }

    const { getBaseUrl } = await import('./modules/url-helper')
    const baseUrl = getBaseUrl(c.env)

    // Prova a leggere il file statico aggiornato
    const pathsToTry = [
      `${baseUrl}/templates/email/${templateName}.html`,
      `${baseUrl}/templates/email/${templateName}`
    ]

    let htmlContent: string | null = null
    let usedPath = ''
    for (const url of pathsToTry) {
      try {
        const res = await fetch(url)
        if (res.ok) {
          htmlContent = await res.text()
          usedPath = url
          break
        }
      } catch {}
    }

    if (!htmlContent) {
      return c.json({
        success: false,
        error: `File template "${templateName}" non trovato`,
        pathsTried: pathsToTry
      }, 404)
    }

    // Verifica che il file contenga "eCura" e non "TeleMedCare"
    const hasTeleMedCare = htmlContent.includes('TeleMedCare')
    const hasECura = htmlContent.includes('eCura')

    // UPSERT in document_templates (tabella corretta, usata da template-loader-clean.ts)
    // id = templateName, type = 'email', html_content = contenuto HTML
    const result = await c.env.DB.prepare(`
      INSERT INTO document_templates (id, name, type, subject, html_content, category, active, updated_at)
      VALUES (?, ?, 'email', ?, ?, 'reminder', 1, datetime('now'))
      ON CONFLICT(id) DO UPDATE SET
        html_content = excluded.html_content,
        subject      = excluded.subject,
        updated_at   = datetime('now')
    `).bind(
      templateName,
      templateName,
      `Promemoria - Completa i tuoi dati eCura`,
      htmlContent
    ).run()

    console.log(`✅ [ONESHOT-SYNC-REMINDER] "${templateName}" aggiornato nel DB (changes: ${result.meta?.changes})`)

    return c.json({
      success: true,
      templateName,
      fileUrl: usedPath,
      contentLength: htmlContent.length,
      changes: result.meta?.changes,
      checks: { hasTeleMedCare, hasECura },
      note: hasTeleMedCare
        ? '⚠️ Il file contiene ancora "TeleMedCare" — controlla public/templates/email/email_reminder_completamento.html'
        : '✅ File corretto: "eCura" presente, "TeleMedCare" assente'
    })

  } catch (error) {
    console.error('❌ [ONESHOT-SYNC-REMINDER] Errore:', error)
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : String(error)
    }, 500)
  }
})

// ─────────────────────────────────────────────────────────────────
// ONESHOT: Diagnostica rinnovo Capone — esegue ogni step e mostra dove fallisce
// GET /api/oneshot-diag-rinnovo-capone-7wq3x
// ─────────────────────────────────────────────────────────────────
app.get('/api/oneshot-diag-rinnovo-capone-7wq3x', async (c) => {
  try {
    if (!c.env?.DB) return c.json({ error: 'DB non configurato' }, 500)

    const LEAD_ID    = 'LEAD-IRBEMA-00061'
    const CODICE_ORI = 'CTR-CAPONE-2025'
    const steps: any[] = []

    // Step 1: trova contratto originale per codice
    const origContract = await c.env.DB.prepare(
      `SELECT id, codice_contratto, status, is_rinnovo, anno_rinnovo, rinnovo_di,
              data_scadenza, prezzo_totale, piano, servizio, leadId
       FROM contracts WHERE codice_contratto = ? AND leadId = ? ORDER BY created_at DESC LIMIT 1`
    ).bind(CODICE_ORI, LEAD_ID).first() as any
    steps.push({ step: '1_contratto_originale', found: !!origContract, data: origContract || null })

    if (!origContract) return c.json({ success: false, steps, error: 'Contratto originale non trovato' })

    // Step 2: trova lead
    const lead = await c.env.DB.prepare(
      `SELECT id, nomeRichiedente, cognomeRichiedente, email, iva_agevolata FROM leads WHERE id = ?`
    ).bind(origContract.leadId).first() as any
    steps.push({ step: '2_lead', found: !!lead, data: lead || null })

    if (!lead) return c.json({ success: false, steps, error: 'Lead non trovato' })

    // Step 3: calcola anno rinnovo
    const annoRinnovo = (origContract.anno_rinnovo || 1) + 1
    steps.push({ step: '3_anno_rinnovo', annoRinnovo })

    // Step 4: verifica idempotenza
    const rinnovoEsistente = await c.env.DB.prepare(`
      SELECT id, codice_contratto, status FROM contracts
      WHERE rinnovo_di = ? AND anno_rinnovo = ? AND leadId = ?
      ORDER BY created_at DESC LIMIT 1
    `).bind(CODICE_ORI, annoRinnovo, origContract.leadId).first() as any
    steps.push({ step: '4_idempotenza', rinnovoEsistente: rinnovoEsistente || null })

    // Step 5: tutti i contratti del lead (per vedere cosa c'è nel DB)
    const allContracts = await c.env.DB.prepare(
      `SELECT id, codice_contratto, status, is_rinnovo, anno_rinnovo, rinnovo_di, data_scadenza
       FROM contracts WHERE leadId = ? ORDER BY created_at DESC`
    ).bind(LEAD_ID).all()
    steps.push({ step: '5_tutti_contratti_lead', contracts: allContracts.results || [] })

    // Step 6: schema colonne contracts
    const schema = await c.env.DB.prepare(`PRAGMA table_info(contracts)`).all()
    const cols = (schema.results || []).map((r: any) => r.name)
    steps.push({ step: '6_schema_colonne', cols })

    // Step 7: calcola rinnovoId
    const rinnovoId = `RINNOVO-${origContract.codice_contratto}-Y${annoRinnovo}-${Date.now()}`
    steps.push({ step: '7_rinnovoId_generato', rinnovoId, pulito: !rinnovoId.includes('CONTRACT_') })

    return c.json({ success: true, steps })
  } catch (e: any) {
    return c.json({ success: false, error: e.message, stack: e.stack?.split('\n').slice(0,5) }, 500)
  }
})

// POST /api/oneshot-set-anagrafica-lead-8kp2x
// Aggiorna dati anagrafici di QUALSIASI lead cercandolo per cognome
// Body: { cognome, nomeRichiedente?, cf, indirizzo, cap, citta, provincia, dataNascita?, luogoNascita? }
app.post('/api/oneshot-set-anagrafica-lead-8kp2x', async (c) => {
  try {
    if (!c.env?.DB) return c.json({ error: 'DB non disponibile' }, 500)
    const body = await c.req.json() as any
    const { cognome, nomeRichiedente, cf, indirizzo, cap, citta, provincia, dataNascita, luogoNascita } = body
    if (!cognome || !cf || !indirizzo || !cap || !citta || !provincia) {
      return c.json({ error: 'Campi obbligatori: cognome, cf, indirizzo, cap, citta, provincia' }, 400)
    }
    // Cerca per cognomeRichiedente O cognomeAssistito (e opzionalmente nomeRichiedente/nomeAssistito)
    // Oppure direttamente per codiceContratto
    const codiceContratto = body.codiceContratto
    let lead: any
    if (codiceContratto) {
      const contract = await c.env.DB.prepare(
        `SELECT leadId FROM contracts WHERE codice_contratto = ? LIMIT 1`
      ).bind(codiceContratto).first() as any
      if (!contract) return c.json({ error: `Contratto "${codiceContratto}" non trovato` }, 404)
      lead = await c.env.DB.prepare(
        `SELECT id, nomeRichiedente, cognomeRichiedente FROM leads WHERE id = ? LIMIT 1`
      ).bind(contract.leadId).first()
    } else if (nomeRichiedente) {
      lead = await c.env.DB.prepare(
        `SELECT id, nomeRichiedente, cognomeRichiedente FROM leads
         WHERE (cognomeRichiedente LIKE ? OR cognomeAssistito LIKE ?)
           AND (nomeRichiedente LIKE ? OR nomeAssistito LIKE ?) LIMIT 1`
      ).bind(`%${cognome}%`, `%${cognome}%`, `%${nomeRichiedente}%`, `%${nomeRichiedente}%`).first()
    } else {
      lead = await c.env.DB.prepare(
        `SELECT id, nomeRichiedente, cognomeRichiedente FROM leads
         WHERE cognomeRichiedente LIKE ? OR cognomeAssistito LIKE ? LIMIT 1`
      ).bind(`%${cognome}%`, `%${cognome}%`).first()
    }
    if (!lead) return c.json({ error: `Lead con cognome "${cognome}" non trovato` }, 404)

    // Se anche_assistito=true aggiorna entrambi i set (utile quando intestatarioContratto='assistito')
    const ancheAssistito = !!(body.anche_assistito)
    const now = new Date().toISOString()
    if (ancheAssistito) {
      await c.env.DB.prepare(`
        UPDATE leads SET
          cfIntestatario            = ?,
          codiceFiscaleIntestatario = ?,
          indirizzoIntestatario     = ?,
          capIntestatario           = ?,
          cittaIntestatario         = ?,
          provinciaIntestatario     = ?,
          dataNascitaIntestatario   = ?,
          luogoNascitaIntestatario  = ?,
          cfAssistito               = ?,
          codiceFiscaleAssistito    = ?,
          indirizzoAssistito        = ?,
          capAssistito              = ?,
          cittaAssistito            = ?,
          provinciaAssistito        = ?,
          dataNascitaAssistito      = ?,
          luogoNascitaAssistito     = ?,
          updated_at                = ?
        WHERE id = ?
      `).bind(cf, cf, indirizzo, cap, citta, provincia, dataNascita || null, luogoNascita || null,
              cf, cf, indirizzo, cap, citta, provincia, dataNascita || null, luogoNascita || null,
              now, lead.id).run()
    } else {
      await c.env.DB.prepare(`
        UPDATE leads SET
          cfIntestatario            = ?,
          codiceFiscaleIntestatario = ?,
          indirizzoIntestatario     = ?,
          capIntestatario           = ?,
          cittaIntestatario         = ?,
          provinciaIntestatario     = ?,
          dataNascitaIntestatario   = ?,
          luogoNascitaIntestatario  = ?,
          updated_at                = ?
        WHERE id = ?
      `).bind(cf, cf, indirizzo, cap, citta, provincia,
        dataNascita || null, luogoNascita || null, now, lead.id).run()
    }

    const updated = await c.env.DB.prepare(`
      SELECT id, nomeRichiedente, cognomeRichiedente,
        cfIntestatario, indirizzoIntestatario, capIntestatario, cittaIntestatario, provinciaIntestatario
      FROM leads WHERE id = ?
    `).bind(lead.id).first()
    return c.json({ success: true, message: `Anagrafica aggiornata per ${lead.nomeRichiedente} ${lead.cognomeRichiedente}`, updated })
  } catch (e: any) {
    return c.json({ success: false, error: e.message }, 500)
  }
})

